type s6ParsedSourceResult struct {
	file *ast.File
	err  error
}

var (
	s6ParsedSourceCache    sync.Map
	s6TypeModelCache       sync.Map
	s6TypeGraphCache       sync.Map
	s6ExportPathCache      sync.Map
	s6ExportImporterOnce   sync.Once
	s6ExportImporterCache  types.Importer
	s6ExportImporterMu     sync.Mutex
	s6BindingCache         sync.Map
	s6MutationSummaryCache sync.Map
	s6GlobalEffectCache    sync.Map
	s6GlobalInitCache      sync.Map
	s6RangeIndexCache      sync.Map
	s6RangeSelectorCache   sync.Map
	s6RangeValueCache      sync.Map
	s6IndexedEntryCache    sync.Map
	s6FrozenAppendCache    sync.Map
	s6FrozenSliceCache     sync.Map
	s6ZeroMapElementCache  sync.Map
	s6StableExprKeyCache   sync.Map
	s6LegacyPartialTypes   = s6LegacyPartialTypeRegistry{
		entries: map[s6LegacyPartialTypeKey]s6LegacyPartialTypeRegistration{},
	}
	s6ContractBaselineOnce   sync.Once
	s6ContractBaselineCache  s6ContractBaselineResult
	s6ContractBaselineBuilds atomic.Int64
	s6ContractBaselineReady  atomic.Bool

	s6CatalogSourcesOnce  sync.Once
	s6CatalogSourcesCache s6SourceSetResult
	s6WriteSourcesOnce    sync.Once
	s6WriteSourcesCache   s6SourceSetResult

	s6ConcurrentUnknown     ast.Expr = ast.NewIdent("providerConcurrentUnknown")
	s6RangeUnknownKey       ast.Expr = ast.NewIdent("providerUnresolvedRangeKey")
	s6RangeUnknownValue     ast.Expr = ast.NewIdent("providerUnresolvedRangeValue")
	s6SelectUnknownReceive  ast.Expr = ast.NewIdent("providerUnresolvedSelectReceive")
	s6ChannelUnknownReceive ast.Expr = ast.NewIdent("providerUnresolvedChannelReceive")
	s6UnknownChannel        ast.Expr = ast.NewIdent("providerUnresolvedChannel")
	s6RangeStringIndex      ast.Expr = &ast.BasicLit{Kind: token.INT, Value: "0"}
	s6RangeStringRune       ast.Expr = &ast.BasicLit{Kind: token.CHAR, Value: "'r'"}
	s6BooleanTrue           ast.Expr = ast.NewIdent("true")
	s6BooleanFalse          ast.Expr = ast.NewIdent("false")
	s6NilExpression         ast.Expr = ast.NewIdent("nil")
	s6UnresolvedNamedResult ast.Expr = ast.NewIdent("providerUnresolvedNamedResult")
	s6DeferredUnknown       ast.Expr = ast.NewIdent("providerUnresolvedDeferredArgument")
	s6UnknownCollection     ast.Expr = ast.NewIdent("providerUnresolvedCollectionSnapshot")
	s6UnknownBacking        ast.Expr = ast.NewIdent("providerUnresolvedBackingStore")
	s6ValidatedRangeName    ast.Expr = &ast.BasicLit{
		Kind: token.STRING, Value: `"validated-range-name"`,
	}
)

type s6SourceSetResult struct {
	sources map[string]string
	err     error
}

func s6ParseSource(rel, source string) (*ast.File, error) {
	sum := sha256.Sum256([]byte(source))
	key := rel + ":" + hex.EncodeToString(sum[:])
	if cached, ok := s6ParsedSourceCache.Load(key); ok {
		result := cached.(s6ParsedSourceResult)
		return result.file, result.err
	}
	file, err := parser.ParseFile(token.NewFileSet(), rel, source, 0)
	result := s6ParsedSourceResult{file: file, err: err}
	actual, _ := s6ParsedSourceCache.LoadOrStore(key, result)
	stored := actual.(s6ParsedSourceResult)
	return stored.file, stored.err
}

