func TestS6ProviderFixturesIgnoreGlobalPreset(t *testing.T) {
	configHome := t.TempDir()
	t.Setenv("XDG_CONFIG_HOME", configHome)
	if err := store.SaveGlobalConfig(store.Config{
		Provider: store.ProviderConfig{
			Type:    "openai-compatible",
			BaseURL: "https://global-provider.invalid",
			Model:   "global-preset",
		},
	}); err != nil {
		t.Fatal(err)
	}
	assertPresetRestored := func(t *testing.T) {
		t.Helper()
		config, err := store.LoadGlobalConfig()
		if err != nil {
			t.Fatal(err)
		}
		if !config.Provider.Configured() ||
			config.Provider.Model != "global-preset" {
			t.Fatalf("global provider preset was not restored: %#v", config.Provider)
		}
	}
	t.Run("provider-not-configured", func(t *testing.T) {
		observation := s6ObserveAdvisory(t, "provider-not-configured")
		const message = "No provider was configured, so the heuristic generator was used. Configure one with tpatch provider set and verify it with tpatch provider check."
		advisory, ok := observation.advisoryText["provider-not-configured"]
		if !ok || advisory.Message != message ||
			!s6HasAdvisory(observation, "provider-not-configured") ||
			observation.exit != 0 {
			t.Fatalf("provider-not-configured = %#v", observation)
		}
		assertPresetRestored(t)
	})
	t.Run("provider-required-for-regenerate", func(t *testing.T) {
		observation := s6ObserveRefusal(
			t, "provider-required-for-regenerate",
		)
		const message = "Regeneration requires a configured successful provider unless heuristic replacement is explicitly allowed."
		if observation.code != "provider-required-for-regenerate" ||
			observation.message != message ||
			observation.exit != 3 {
			t.Fatalf("provider-required-for-regenerate = %#v", observation)
		}
		assertPresetRestored(t)
	})
}

func TestS6ContractBaselineBuiltOnce(t *testing.T) {
	before := s6ContractBaselineBuilds.Load()
	if before > 1 {
		t.Fatalf("baseline builder count before validation = %d", before)
	}
	for _, id := range []string{"PIB-227", "PIB-228", "PIB-231"} {
		spec := s6GuardSpecs[id]
		if err := spec.run(t); err != nil {
			t.Fatalf("%s cached baseline validator: %v", id, err)
		}
		if err := spec.sensitivity(t); err == nil {
			t.Fatalf("%s cached sensitivity did not bite", id)
		}
	}
	after := s6ContractBaselineBuilds.Load()
	if after != 1 {
		t.Fatalf(
			"baseline builder count after PIB-227/228/231 validators = %d",
			after,
		)
	}
	catalog, reachable, relationships, err := s6AdvisoryEvidence(t)
	if err != nil {
		t.Fatal(err)
	}
	catalog[0] = "mutated-caller-catalog"
	reachable[s6AdvisoryCatalog[0]] = "mutated-caller-fixture"
	relationships[0].outcome = "mutated-caller-outcome"
	freshCatalog, freshReachable, freshRelationships, err :=
		s6AdvisoryEvidence(t)
	if err != nil {
		t.Fatal(err)
	}
	if freshCatalog[0] != s6AdvisoryCatalog[0] ||
		freshReachable[s6AdvisoryCatalog[0]] ==
			"mutated-caller-fixture" ||
		freshRelationships[0].outcome == "mutated-caller-outcome" {
		t.Fatal("caller mutation contaminated immutable baseline evidence")
	}
	sources, err := s6VocabularyProductionSources(t)
	if err != nil {
		t.Fatal(err)
	}
	sources["internal/cli/prepare_vocabulary_cache_mutation.go"] = `package cli
func injected(report preparePublishReport) {
	report.Action = "mutated-cache-action"
}
`
	if _, err := s6DerivedProductionVocabulariesFromSources(sources); err == nil {
		t.Fatal("synthetic vocabulary mutation reused baseline acceptance")
	}
	if s6ContractBaselineBuilds.Load() != 1 {
		t.Fatal("synthetic mutation rebuilt the immutable baseline")
	}
}

func TestS6HumanRendererRemediationSensitivity(t *testing.T) {
	jsonObservation := s6RuntimeObservation{
		code:           "fixture-refusal",
		exit:           3,
		message:        "The fixture was refused.",
		rawRemediation: "Repair the fixture and retry.",
		retry:          "tpatch prepare fixture --json --quiet",
		relatedObject:  "refusal",
	}
	human := strings.Join([]string{
		"Refusal: fixture-refusal",
		"The fixture was refused.",
		"Repair the fixture and retry.",
		"tpatch prepare fixture",
	}, "\n")
	if err := validateS6HumanCatalogParity(jsonObservation, human); err != nil {
		t.Fatalf("baseline renderer evidence rejected: %v", err)
	}
	mutated := strings.Replace(human, "Repair the fixture and retry.\n", "", 1)
	if err := validateS6HumanCatalogParity(jsonObservation, mutated); err == nil {
		t.Fatal("renderer parity accepted output with remediation removed")
	}
}

