func TestS6ImportedGlobalSensitivity(t *testing.T) {
	helperSource := `package helper
var GlobalPath = "closed-name"
var GlobalPointer = &GlobalPath
var GlobalPaths = map[string]string{"path": "closed-name"}
const SafePath = "closed-name"
func Write(value string) { GlobalPath = value }
func WritePointer(value string) { *GlobalPointer = value }
func WriteMap(value string) { GlobalPaths["path"] = value }
`
	caller := func(body string, alias string) string {
		return `package intentpub
import (
	filesystem "os"
	` + alias + ` "github.com/tesseracode/tesserapatch/internal/helper"
)
func safeRel() string { return "closed-name" }
` + body
	}

	for _, fixture := range []struct {
		name string
		body string
	}{
		{
			name: "imported-global-write-read",
			body: `
func injected(root *filesystem.Root, providerOutput string) {
	helper.Write(providerOutput)
	_ = root.Remove(safeRel())
	_ = root.Remove(helper.GlobalPath)
}
func init() { injected(nil, "") }
`,
		},
		{
			name: "aliased-import-global-write-read",
			body: `
func injected(root *filesystem.Root, providerOutput string) {
	patchhelper.Write(providerOutput)
	_ = root.Remove(safeRel())
	_ = root.Remove(patchhelper.GlobalPath)
}
func init() { injected(nil, "") }
`,
		},
		{
			name: "imported-pointer-global",
			body: `
func injected(root *filesystem.Root, providerOutput string) {
	helper.WritePointer(providerOutput)
	_ = root.Remove(safeRel())
	_ = root.Remove(helper.GlobalPath)
}
func init() { injected(nil, "") }
`,
		},
		{
			name: "imported-map-global",
			body: `
func injected(root *filesystem.Root, providerOutput string) {
	helper.WriteMap(providerOutput)
	_ = root.Remove(safeRel())
	_ = root.Remove(helper.GlobalPaths["path"])
}
func init() { injected(nil, "") }
`,
		},
	} {
		t.Run(fixture.name, func(t *testing.T) {
			alias := "helper"
			if strings.Contains(fixture.name, "aliased") {
				alias = "patchhelper"
			}
			err := validateS6WriteTargetSourceSet(t, map[string]string{
				"internal/helper/helper.go":            helperSource,
				"internal/intentpub/import_fixture.go": caller(fixture.body, alias),
			})
			if err == nil {
				t.Fatal("imported mutable global flow was accepted")
			}
			if strings.Contains(err.Error(), "no rooted path constructors") {
				t.Fatalf("fixture failed before imported global analysis: %v", err)
			}
		})
	}
	t.Run("imported-safe-const", func(t *testing.T) {
		source := caller(`
func injected(root *filesystem.Root) {
	_ = root.Remove(safeRel())
	_ = root.Remove(helper.SafePath)
}
func init() { injected(nil) }
`, "helper")
		if err := validateS6WriteTargetSourceSet(t, map[string]string{
			"internal/helper/helper.go":            helperSource,
			"internal/intentpub/import_fixture.go": source,
		}); err != nil {
			t.Fatalf("imported safe const was rejected: %v", err)
		}
	})
	t.Run("unanalyzed-imported-global", func(t *testing.T) {
		source := `package intentpub
import (
	filesystem "os"
	external "example.com/external"
)
func safeRel() string { return "closed-name" }
func injected(root *filesystem.Root) {
	_ = root.Remove(safeRel())
	_ = root.Remove(external.GlobalPath)
}
func init() { injected(nil) }
`
		err := validateS6WriteTargetSourceSet(t, map[string]string{
			"internal/intentpub/external_fixture.go": source,
		})
		if err == nil || !strings.Contains(err.Error(), "go/types check") {
			t.Fatalf("unanalyzed imported mutable global was not rejected: %v", err)
		}
	})
	t.Run("unanalyzed-imported-global-write", func(t *testing.T) {
		source := `package intentpub
import (
	filesystem "os"
	external "example.com/external"
)
func safeRel() string { return "closed-name" }
func injected(root *filesystem.Root, providerOutput string) {
	external.GlobalPath = providerOutput
	_ = root.Remove(safeRel())
}
func init() { injected(nil, "") }
`
		err := validateS6WriteTargetSourceSet(t, map[string]string{
			"internal/intentpub/external_write_fixture.go": source,
		})
		if err == nil || !strings.Contains(err.Error(), "go/types check") {
			t.Fatalf("unanalyzed imported global write was not rejected: %v", err)
		}
	})
}

