func TestS6BuiltinIdentitySensitivity(t *testing.T) {
	fixtures := map[string]struct {
		declaration string
		shadowCall  string
		builtinCall string
	}{
		"append": {
			"func append([]int, int) []int { return nil }",
			"append(nil, 1)",
			"append([]int{}, 1)",
		},
		"close": {
			"func close(chan int) {}",
			"close(nil)",
			"close(make(chan int))",
		},
		"copy": {
			"func copy([]int, []int) int { return 0 }",
			"copy(nil, nil)",
			"copy([]int{}, []int{})",
		},
		"delete": {
			"func delete(map[string]int, string) {}",
			`delete(nil, "key")`,
			`delete(map[string]int{}, "key")`,
		},
		"len": {
			"func len([]int) int { return 0 }",
			"len(nil)",
			"len([]int{})",
		},
		"make": {
			"func make() int { return 0 }",
			"make()",
			"make([]int, 1)",
		},
		"new": {
			"func new() *int { return nil }",
			"new()",
			"new(int)",
		},
		"panic": {
			"func panic(any) {}",
			`panic("shadow")`,
			`panic("builtin")`,
		},
		"recover": {
			"func recover() any { return nil }",
			"recover()",
			"recover()",
		},
	}
	for name, fixture := range fixtures {
		t.Run(name, func(t *testing.T) {
			for _, test := range []struct {
				label       string
				declaration string
				call        string
				want        bool
			}{
				{"shadowed", fixture.declaration, fixture.shadowCall, false},
				{"predeclared", "", fixture.builtinCall, true},
			} {
				t.Run(test.label, func(t *testing.T) {
					source := `package intentpub
` + test.declaration + `
func probe() { _ = func() any { _ = ` + test.call + `; return nil }() }
`
					if name == "close" || name == "delete" ||
						name == "panic" {
						source = `package intentpub
` + test.declaration + `
func probe() { ` + test.call + ` }
`
					}
					file, err := s6ParseSource("builtin.go", source)
					if err != nil {
						t.Fatal(err)
					}
					model, err := s6BuildSourceTypeModel(map[string]string{
						"internal/intentpub/builtin.go": source,
					})
					if err != nil {
						t.Fatal(err)
					}
					var function *ast.FuncDecl
					var call *ast.CallExpr
					for _, declaration := range file.Decls {
						candidate, ok := declaration.(*ast.FuncDecl)
						if !ok || candidate.Name.Name != "probe" {
							continue
						}
						function = candidate
						ast.Inspect(candidate.Body, func(node ast.Node) bool {
							current, ok := node.(*ast.CallExpr)
							if ok && s6CallName(current) == name {
								call = current
								return false
							}
							return true
						})
					}
					if function == nil || call == nil {
						t.Fatal("fixture call was not discovered")
					}
					analyzer := &s6FlowAnalyzer{
						function: function,
						model:    model,
						pkg:      "internal/intentpub",
						imports:  s6FileImportDirs(file),
						locals: s6FunctionLocalTypes(
							"internal/intentpub", file, function, model,
						),
					}
					if got := s6IsPredeclaredBuiltinCall(
						call, name, analyzer,
					); got != test.want {
						t.Fatalf(
							"builtin identity = %v, want %v", got, test.want,
						)
					}
				})
			}
		})
	}
}

