func TestS6AnalyzerCacheSensitivity(t *testing.T) {
	safe := `package intentpub
import filesystem "os"
func safeRel() string { return "closed-name" }
func injected(root *filesystem.Root) { _ = root.Remove(safeRel()) }
func init() { injected(nil) }
`
	rel := "internal/intentpub/cache_fixture.go"
	safeSources := map[string]string{rel: safe}
	first, err := s6BuildSourceTypeModel(safeSources)
	if err != nil {
		t.Fatal(err)
	}
	second, err := s6BuildSourceTypeModel(safeSources)
	if err != nil || first != second {
		t.Fatalf("identical immutable model was not cached: same=%v err=%v", first == second, err)
	}
	if err := validateS6WriteTargetSourceSet(t, safeSources); err != nil {
		t.Fatalf("safe cache baseline failed: %v", err)
	}
	mutated := strings.Replace(
		safe,
		"func injected(root *filesystem.Root) { _ = root.Remove(safeRel()) }",
		`func injected(root *filesystem.Root) {
	providerOutput := "unsafe"
	_ = root.Remove(providerOutput)
}`,
		1,
	)
	mutatedSources := map[string]string{rel: mutated}
	third, err := s6BuildSourceTypeModel(mutatedSources)
	if err != nil {
		t.Fatal(err)
	}
	if third == first {
		t.Fatal("mutated fixture reused the immutable baseline model")
	}
	if err := validateS6WriteTargetSourceSet(t, mutatedSources); err == nil ||
		!strings.Contains(err.Error(), "providerOutput") {
		t.Fatalf("mutated fixture was served stale from cache: %v", err)
	}
	safeInit := `package intentpub
import (
	filesystem "os"
	environment "os"
)
func safeRel() string { return "closed-name" }
var GlobalPath = "closed-name"
func init() { _ = environment.Getenv("IGNORED") }
func injected(root *filesystem.Root) {
	_ = root.Remove(safeRel())
	_ = root.Remove(GlobalPath)
}
func init() { injected(nil) }
`
	initSources := map[string]string{rel: safeInit}
	if err := validateS6WriteTargetSourceSet(t, initSources); err != nil {
		t.Fatalf("safe initialization cache baseline failed: %v", err)
	}
	unsafeInit := strings.Replace(
		safeInit,
		`func init() { _ = environment.Getenv("IGNORED") }`,
		`func init() { GlobalPath = environment.Getenv("TPATCH_PATH") }`,
		1,
	)
	if err := validateS6WriteTargetSourceSet(
		t, map[string]string{rel: unsafeInit},
	); err == nil {
		t.Fatal("mutated initialization fixture was served stale from cache")
	}
	production, err := s6VocabularyProductionSources(t)
	if err != nil {
		t.Fatal(err)
	}
	var productionRel string
	for candidate := range production {
		productionRel = candidate
		break
	}
	original := production[productionRel]
	production[productionRel] = "mutated caller copy"
	fresh, err := s6CatalogProductionSources(t)
	if err != nil {
		t.Fatal(err)
	}
	if fresh[productionRel] != original {
		t.Fatal("caller mutation contaminated immutable production source cache")
	}

	const (
		firstProjectionRel  = "internal/intent/intent.go"
		secondProjectionRel = "internal/intent/status_schema.go"
	)
	firstProjection := map[string]string{
		firstProjectionRel: s6RepoFile(t, firstProjectionRel),
	}
	secondProjection := s6CloneSourceSet(firstProjection)
	secondProjection[secondProjectionRel] = s6RepoFile(t, secondProjectionRel)
	firstGraph, err := s6BuildTypeGraph(firstProjection)
	if err != nil {
		t.Fatal(err)
	}
	secondGraph, err := s6BuildTypeGraph(secondProjection)
	if err != nil {
		t.Fatal(err)
	}
	if firstGraph.sourceKey != secondGraph.sourceKey {
		t.Fatal("projection cache fixture did not converge on one augmented graph")
	}
	firstModel, err := s6BuildSourceTypeModel(firstProjection)
	if err != nil {
		t.Fatal(err)
	}
	secondModel, err := s6BuildSourceTypeModel(secondProjection)
	if err != nil {
		t.Fatal(err)
	}
	if firstModel == secondModel || firstModel.sourceKey == secondModel.sourceKey {
		t.Fatal("different source projections reused one type model")
	}
	if firstModel.files[secondProjectionRel] != nil ||
		secondModel.files[secondProjectionRel] == nil {
		t.Fatal("type model cache lost the caller-provided file projection")
	}
}

func s6ReportRootTypes() []reflect.Type {
	return []reflect.Type{
		reflect.TypeOf(preparePublishReport{}),
		reflect.TypeOf(intentArchiveListReport{}),
		reflect.TypeOf(intentArchivePurgeReport{}),
	}
}

func s6ForbiddenJSONKeyGuard(*testing.T) error {
	return validateS6JSONKeys(s6ReportRootTypes())
}

func validateS6JSONKeys(roots []reflect.Type) error {
	forbidden := map[string]struct{}{
		"absolute_path":  {},
		"created_at":     {},
		"updated_at":     {},
		"timestamp":      {},
		"duration":       {},
		"duration_ms":    {},
		"hostname":       {},
		"pid":            {},
		"content":        {},
		"body":           {},
		"symlink_target": {},
		"secret":         {},
		"token":          {},
		"env_value":      {},
	}
	seenTypes := map[reflect.Type]bool{}
	var walk func(reflect.Type) error
	walk = func(current reflect.Type) error {
		for current.Kind() == reflect.Pointer ||
			current.Kind() == reflect.Slice ||
			current.Kind() == reflect.Array {
			current = current.Elem()
		}
		if current.Kind() == reflect.Map {
			return fmt.Errorf("wire schema contains map type %s with unguarded runtime keys", current)
		}
		if current.Kind() != reflect.Struct || seenTypes[current] {
			return nil
		}
		seenTypes[current] = true
		for index := 0; index < current.NumField(); index++ {
			field := current.Field(index)
			tag := strings.Split(field.Tag.Get("json"), ",")[0]
			if tag != "" && tag != "-" {
				if _, blocked := forbidden[tag]; blocked {
					return fmt.Errorf("%s.%s exposes forbidden JSON key %q", current, field.Name, tag)
				}
			}
			if field.Type.Kind() == reflect.Map {
				return fmt.Errorf("%s.%s exposes map-typed wire field %q", current, field.Name, tag)
			}
			if err := walk(field.Type); err != nil {
				return err
			}
		}
		return nil
	}
	for _, root := range roots {
		if err := walk(root); err != nil {
			return err
		}
	}
	return nil
}

func s6SPECGuard(t *testing.T) error {
	return validateS6SPEC(s6RepoFile(t, "SPEC.md"))
}

func validateS6SPEC(body string) error {
	section, ok := s6Section(body, "Prepare intent bundle (GH #16 and GH #23)")
	if !ok {
		return errors.New("SPEC lacks the prepare intent-bundle section")
	}
	modeLines := []string{
		"tpatch prepare <slug> --check       [--json] [--quiet] [--path <dir>]",
		"tpatch prepare <slug>               [--json] [--quiet] [--path <dir>] [--timeout <d>] [--timeout-phase <d>] [--no-retry] [--dry-run] [--allow-heuristic]",
		"tpatch prepare <slug> --manual      [--json] [--quiet] [--path <dir>] [--dry-run]",
		"tpatch prepare <slug> --regenerate  [--json] [--quiet] [--path <dir>] [--timeout <d>] [--timeout-phase <d>] [--no-retry] [--dry-run] [--allow-heuristic]",
		"tpatch prepare <slug> --abandon-transaction [--json] [--quiet] [--path <dir>] [--yes]",
	}
	for _, line := range modeLines {
		if !s6ContainsExactLine(section, line) {
			return fmt.Errorf("SPEC lacks exact prepare syntax %q", line)
		}
	}
	for _, line := range []string{
		"tpatch feature intent-archive list  <slug> [--json] [--quiet] [--path <dir>]",
		"tpatch feature intent-archive purge <slug> (--blob <hash>... | --generation <id>... | --orphans | --all) [--yes] [--json] [--quiet] [--path <dir>]",
	} {
		if !s6ContainsExactLine(section, line) {
			return fmt.Errorf("SPEC lacks exact archive syntax %q", line)
		}
	}
	if strings.Contains(section, "tpatch prepare <slug> --mode") ||
		strings.Contains(section, "tpatch feature intent-archive --mode") {
		return errors.New("SPEC documents a nonexistent --mode command form")
	}
	flagStart := strings.Index(section, "Exactly twelve local flags are registered:")
	if flagStart < 0 {
		return errors.New("SPEC lacks the exact local-flag declaration")
	}
	flagText := section[flagStart:]
	if end := strings.Index(flagText, ";"); end >= 0 {
		flagText = flagText[:end]
	}
	var flags []string
	for _, match := range regexp.MustCompile("`(--[a-z-]+)`").FindAllStringSubmatch(flagText, -1) {
		flags = append(flags, match[1])
	}
	expectedFlags := []string{
		"--check", "--manual", "--regenerate", "--abandon-transaction",
		"--allow-heuristic", "--dry-run", "--yes", "--json", "--quiet",
		"--timeout", "--timeout-phase", "--no-retry",
	}
	if !reflect.DeepEqual(flags, expectedFlags) {
		return fmt.Errorf("SPEC local flags = %v, want ordered %v", flags, expectedFlags)
	}
	exitRows := map[string]string{}
	exitRE := regexp.MustCompile(`^\| ` + "`" + `([0-6])` + "`" + ` \| (.+) \|$`)
	for _, line := range strings.Split(section, "\n") {
		if match := exitRE.FindStringSubmatch(line); match != nil {
			if _, duplicate := exitRows[match[1]]; duplicate {
				return fmt.Errorf("SPEC duplicates prepare exit %s", match[1])
			}
			exitRows[match[1]] = match[2]
		}
	}
	if len(exitRows) != 7 {
		return fmt.Errorf("SPEC prepare exit table has %d rows, want 7", len(exitRows))
	}
	for code := 0; code <= 6; code++ {
		if _, ok := exitRows[strconv.Itoa(code)]; !ok {
			return fmt.Errorf("SPEC prepare exit table lacks %d", code)
		}
	}
	if exitRows["4"] != "Retired and unpopulated. `prepare` never exits 4." {
		return fmt.Errorf("SPEC exit 4 = %q, want retired and unpopulated", exitRows["4"])
	}
	required := []string{
		"four mode flags are mutually exclusive by flag",
		"--check --abandon-transaction=false",
		"`--yes` is valid only",
		"`execution_preflight: \"not_evaluated\"`",
		"Linux and macOS",
		"cross-machine exclusion",
		"Human mode sends progress to stderr",
		"`FEATURES.md` is a derived,\nbest-effort refresh outside the publication set",
		"Readers can observe an in-progress prefix",
		"pending-purge recovery as terminal",
		"stops without processing the requested selector",
		"deleting committed blobs does\nnot rewrite Git history",
		"authorship/provenance",
		"general history/undo facility",
	}
	for _, anchor := range required {
		if !strings.Contains(section, anchor) {
			return fmt.Errorf("SPEC is missing S6 contract anchor %q", anchor)
		}
	}
	return nil
}

func s6ContainsExactLine(body, wanted string) bool {
	for _, line := range strings.Split(body, "\n") {
		if line == wanted {
			return true
		}
	}
	return false
}

func s6ExactCommand(content, command string) bool {
	re := regexp.MustCompile(`(?:^|[^A-Za-z0-9_-])` + regexp.QuoteMeta(command) + `(?:$|[\s` + "`" + `])`)
	return re.MatchString(content)
}

func s6SkillCommandGuard(t *testing.T) error {
	return validateS6SkillCommands(s6SkillBodies(t))
}

func validateS6SkillCommands(skills map[string]string) error {
	commands := []string{
		"tpatch prepare",
		"tpatch prepare <slug> --check",
		"tpatch prepare <slug> --manual",
		"tpatch prepare <slug> --regenerate",
		"tpatch prepare <slug> --abandon-transaction",
		"tpatch feature intent-archive list",
		"tpatch feature intent-archive purge",
	}
	for rel, body := range skills {
		for _, command := range commands {
			if !s6ExactCommand(body, command) {
				return fmt.Errorf("%s is missing exact command %q", rel, command)
			}
		}
	}
	return nil
}

type s6MarkdownSection struct {
	title string
	body  string
}

func s6MarkdownSections(body string) []s6MarkdownSection {
	re := regexp.MustCompile(`(?m)^(#{1,6})[ \t]+(.+?)[ \t]*$`)
	matches := re.FindAllStringSubmatchIndex(body, -1)
	sections := make([]s6MarkdownSection, 0, len(matches))
	for index, match := range matches {
		start := match[1]
		end := len(body)
		if index+1 < len(matches) {
			end = matches[index+1][0]
		}
		sections = append(sections, s6MarkdownSection{
			title: strings.TrimSpace(body[match[4]:match[5]]),
			body:  body[start:end],
		})
	}
	return sections
}

func s6Section(body, title string) (string, bool) {
	for _, section := range s6MarkdownSections(body) {
		if strings.EqualFold(section.title, title) {
			return section.body, true
		}
	}
	return "", false
}

func s6SkillPlacementGuard(t *testing.T) error {
	return validateS6SkillPlacement(s6SkillBodies(t))
}

func validateS6SkillPlacement(skills map[string]string) error {
	var canonicalOptional string
	for rel, body := range skills {
		for _, title := range []string{"Phase Ordering", "Before You Run Anything"} {
			section, ok := s6Section(body, title)
			if !ok {
				return fmt.Errorf("%s lacks structural section %q", rel, title)
			}
			if s6ExactCommand(section, "tpatch prepare") {
				return fmt.Errorf("%s inserts prepare into %s", rel, title)
			}
		}
		optional, ok := s6Section(body, "Optional intent preparation and recovery")
		if !ok || !s6ExactCommand(optional, "tpatch prepare") {
			return fmt.Errorf("%s lacks separate optional prepare methodology", rel)
		}
		if canonicalOptional == "" {
			canonicalOptional = optional
		} else if optional != canonicalOptional {
			return fmt.Errorf("%s optional prepare methodology diverges from the six-skill shared wording", rel)
		}
	}
	return nil
}

func s6SkillClaimGuard(t *testing.T) error {
	return validateS6SkillClaims(s6SkillBodies(t))
}

func validateS6SkillClaims(skills map[string]string) error {
	contradictions := []*regexp.Regexp{
		regexp.MustCompile(`(?i)\b(?:the archive|intent archive|prepare|it) (?:certifies|proves) semantic`),
		regexp.MustCompile(`(?i)\b(?:records?|establishes?|provides?)\b.{0,30}\bprovenance\b`),
		regexp.MustCompile(`(?i)\bintent archive is (?:the )?provenance\b`),
	}
	for rel, body := range skills {
		if !strings.Contains(body, "does not certify semantic quality") {
			return fmt.Errorf("%s lacks the semantic non-certification statement", rel)
		}
		if !strings.Contains(body, "it is not authorship or provenance") {
			return fmt.Errorf("%s lacks the archive provenance limit", rel)
		}
		for _, re := range contradictions {
			if match := re.FindString(body); match != "" {
				return fmt.Errorf("%s carries contradictory claim %q", rel, match)
			}
		}
	}
	return nil
}

