type s6DispositionResult struct {
	disposition string
	action      string
	code        string
	exit        int
}

func validateS6DispositionTotality(states []string) error {
	expectedStates := []string{
		intent.StatePresentNonempty,
		intent.StatePresentEmpty,
		intent.StateAbsent,
		intent.StateSymlinkRefused,
		intent.StateNotRegular,
		intent.StateUnreadable,
		intent.StateOversize,
		intent.StateInvalidStructured,
		intent.StateUnstable,
	}
	if !reflect.DeepEqual(states, expectedStates) {
		return fmt.Errorf("artifact state declaration/order = %v, want %v", states, expectedStates)
	}
	requiredGenerate := map[string]s6DispositionResult{
		intent.StatePresentNonempty:   {disposition: "preserved", action: "adopt"},
		intent.StatePresentEmpty:      {disposition: "untouched", action: "none", code: "artifact-empty-not-overwritten", exit: 2},
		intent.StateAbsent:            {disposition: "untouched", action: "none", code: "incoherent-bundle-gap", exit: 2},
		intent.StateSymlinkRefused:    {disposition: "untouched", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateNotRegular:        {disposition: "untouched", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateUnreadable:        {disposition: "untouched", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateOversize:          {disposition: "untouched", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateInvalidStructured: {disposition: "untouched", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateUnstable:          {disposition: "untouched", action: "none", code: "artifact-unstable", exit: 3},
	}
	requiredRegenerate := map[string]s6DispositionResult{
		intent.StatePresentNonempty:   {disposition: "regenerated", action: "regenerate"},
		intent.StatePresentEmpty:      {disposition: "regenerated", action: "regenerate"},
		intent.StateAbsent:            {disposition: "generated", action: "regenerate"},
		intent.StateSymlinkRefused:    {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateNotRegular:        {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateUnreadable:        {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateOversize:          {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateInvalidStructured: {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateUnstable:          {disposition: "regenerated", action: "none", code: "artifact-unstable", exit: 3},
	}
	sidecarGenerate := map[string]s6DispositionResult{
		intent.StatePresentNonempty:   {disposition: "preserved", action: "adopt"},
		intent.StatePresentEmpty:      {disposition: "untouched", action: "adopt"},
		intent.StateAbsent:            {disposition: "absent-optional", action: "adopt"},
		intent.StateSymlinkRefused:    {disposition: "untouched", action: "adopt"},
		intent.StateNotRegular:        {disposition: "untouched", action: "adopt"},
		intent.StateUnreadable:        {disposition: "untouched", action: "adopt"},
		intent.StateOversize:          {disposition: "untouched", action: "adopt"},
		intent.StateInvalidStructured: {disposition: "untouched", action: "adopt"},
		intent.StateUnstable:          {disposition: "untouched", action: "adopt"},
	}
	sidecarRegenerate := map[string]s6DispositionResult{
		intent.StatePresentNonempty:   {disposition: "regenerated", action: "regenerate"},
		intent.StatePresentEmpty:      {disposition: "regenerated", action: "regenerate"},
		intent.StateAbsent:            {disposition: "generated", action: "regenerate"},
		intent.StateSymlinkRefused:    {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateNotRegular:        {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateUnreadable:        {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateOversize:          {disposition: "regenerated", action: "none", code: "artifact-unsafe", exit: 3},
		intent.StateInvalidStructured: {disposition: "regenerated", action: "regenerate"},
		intent.StateUnstable:          {disposition: "regenerated", action: "none", code: "artifact-unstable", exit: 3},
	}
	if len(requiredGenerate) != len(states) ||
		len(requiredRegenerate) != len(states) ||
		len(sidecarGenerate) != len(states) ||
		len(sidecarRegenerate) != len(states) {
		return errors.New("disposition table is not total over the declared artifact states")
	}
	for _, state := range states {
		requiredState := prepareReadState{
			inspection:  intent.Report{Slug: "s6-disposition", FeatureState: intent.FeatureStateRequested},
			analysis:    prepareCaptured{state: state},
			spec:        prepareCaptured{state: intent.StatePresentNonempty},
			exploration: prepareCaptured{state: intent.StatePresentNonempty},
			sidecar:     prepareCaptured{state: intent.StateAbsent},
		}
		if got := s6DispositionFor(requiredState, prepareModeGenerate, 0); got != requiredGenerate[state] {
			return fmt.Errorf("required generate disposition for %q = %+v, want %+v", state, got, requiredGenerate[state])
		}
		if got := s6DispositionFor(requiredState, prepareModeRegenerate, 0); got != requiredRegenerate[state] {
			return fmt.Errorf("required regenerate disposition for %q = %+v, want %+v", state, got, requiredRegenerate[state])
		}
		capturedSidecarState := state
		if state == intent.StateInvalidStructured {
			capturedSidecarState = intent.StatePresentNonempty
		}
		sidecarState := prepareReadState{
			inspection: intent.Report{
				Slug:         "s6-disposition",
				FeatureState: intent.FeatureStateRequested,
				Artifacts: []intent.Artifact{{
					ID:    "analysis_sidecar",
					State: state,
				}},
			},
			analysis:    prepareCaptured{state: intent.StatePresentNonempty},
			spec:        prepareCaptured{state: intent.StatePresentNonempty},
			exploration: prepareCaptured{state: intent.StatePresentNonempty},
			sidecar:     prepareCaptured{state: capturedSidecarState},
		}
		if got := s6DispositionFor(sidecarState, prepareModeGenerate, 3); got != sidecarGenerate[state] {
			return fmt.Errorf("sidecar generate disposition for %q = %+v, want %+v", state, got, sidecarGenerate[state])
		}
		if got := s6DispositionFor(sidecarState, prepareModeRegenerate, 3); got != sidecarRegenerate[state] {
			return fmt.Errorf("sidecar regenerate disposition for %q = %+v, want %+v", state, got, sidecarRegenerate[state])
		}
	}
	return nil
}

func s6DispositionFor(state prepareReadState, mode prepareMode, artifactIndex int) s6DispositionResult {
	plan, code, exit := buildPreparePlan(state, mode)
	disposition := ""
	if artifactIndex < len(plan.artifacts) {
		disposition = plan.artifacts[artifactIndex].Disposition
	}
	return s6DispositionResult{
		disposition: disposition,
		action:      plan.action,
		code:        code,
		exit:        exit,
	}
}

