func s6StoreFeatureStates(t *testing.T) []string {
	t.Helper()
	source := s6RepoFile(t, "internal/store/types.go")
	fileset := token.NewFileSet()
	file, err := parser.ParseFile(fileset, "types.go", source, 0)
	if err != nil {
		t.Fatal(err)
	}
	var values []string
	for _, declaration := range file.Decls {
		generic, ok := declaration.(*ast.GenDecl)
		if !ok || generic.Tok != token.CONST {
			continue
		}
		for _, rawSpec := range generic.Specs {
			spec, ok := rawSpec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			typeName, typed := spec.Type.(*ast.Ident)
			if !typed || typeName.Name != "FeatureState" {
				continue
			}
			for _, rawValue := range spec.Values {
				literal, ok := rawValue.(*ast.BasicLit)
				if !ok || literal.Kind != token.STRING {
					continue
				}
				value, err := strconv.Unquote(literal.Value)
				if err == nil {
					values = append(values, value)
				}
			}
		}
	}
	return values
}

func validateS6FeatureStateTotality(t *testing.T, declared []string) error {
	expected := []string{
		"requested",
		"analyzed",
		"defined",
		"implementing",
		"applied",
		"active",
		"reconciling",
		"reconciling-shadow",
		"blocked",
		"upstream_merged",
		"rejected",
		"unapplied",
	}
	if !reflect.DeepEqual(declared, expected) {
		return fmt.Errorf("FeatureState declaration/order = %v, want %v", declared, expected)
	}
	expectedRefusal := map[string]string{
		"requested":          "",
		"analyzed":           "",
		"defined":            "",
		"implementing":       "state-refused",
		"applied":            "state-refused",
		"active":             "state-refused",
		"reconciling":        "state-refused",
		"reconciling-shadow": "state-refused",
		"blocked":            "state-refused",
		"upstream_merged":    "state-refused",
		"rejected":           "state-refused",
		"unapplied":          "state-refused",
	}
	if len(expectedRefusal) != len(expected) {
		return errors.New("prepare state table is not total over ValidFeatureState")
	}
	for _, value := range declared {
		if !store.ValidFeatureState(store.FeatureState(value)) {
			return fmt.Errorf("ValidFeatureState rejects declared state %q", value)
		}
		if got := prepareStateRefusal(value); got != expectedRefusal[value] {
			return fmt.Errorf("prepareStateRefusal(%q) = %q, want %q", value, got, expectedRefusal[value])
		}
	}
	if store.ValidFeatureState(store.FeatureState("synthetic-thirteenth")) {
		return errors.New("ValidFeatureState default-allows a synthetic thirteenth state")
	}
	return nil
}

