func s6VocabularyWireFieldInventory() map[string]string {
	inventory := map[string]string{}
	type root struct {
		name string
		typ  reflect.Type
	}
	roots := []root{
		{name: "prepare", typ: reflect.TypeOf(preparePublishReport{})},
		{name: "archive-list", typ: reflect.TypeOf(intentArchiveListReport{})},
		{name: "archive-purge", typ: reflect.TypeOf(intentArchivePurgeReport{})},
	}
	seen := map[string]bool{}
	var walk func(string, reflect.Type, string)
	walk = func(rootName string, current reflect.Type, path string) {
		for current.Kind() == reflect.Pointer ||
			current.Kind() == reflect.Slice ||
			current.Kind() == reflect.Array {
			current = current.Elem()
		}
		if current.Kind() != reflect.Struct {
			return
		}
		seenKey := rootName + ":" + current.PkgPath() + "." + current.Name() + ":" + path
		if seen[seenKey] {
			return
		}
		seen[seenKey] = true
		for index := 0; index < current.NumField(); index++ {
			field := current.Field(index)
			tag := strings.Split(field.Tag.Get("json"), ",")[0]
			if tag == "" || tag == "-" {
				continue
			}
			fieldPath := tag
			if path != "" {
				fieldPath = path + "." + tag
			}
			key := ""
			switch {
			case rootName == "prepare" && fieldPath == "mode":
				key = "mode"
			case (rootName == "prepare" || rootName == "archive-purge") &&
				fieldPath == "outcome":
				key = "outcome"
			case (rootName == "prepare" || rootName == "archive-purge") &&
				fieldPath == "action":
				key = "action"
			case rootName == "prepare" && fieldPath == "artifacts.disposition":
				key = "disposition"
			case rootName == "prepare" && fieldPath == "artifacts.generator":
				key = "generator"
			case rootName == "prepare" && fieldPath == "execution_preflight":
				key = "execution_preflight"
			case fieldPath == "recovery.kind":
				key = "recovery.kind"
			case fieldPath == "purge_progress.resume":
				key = "purge_progress.resume"
			case rootName == "archive-purge" && fieldPath == "pending_purge.selector":
				key = "pending_purge.selector"
			case rootName == "archive-purge" &&
				(fieldPath == "remaining_repairs.stages.class" ||
					fieldPath == "remaining_repairs.next_stage.class"):
				key = "remaining_repairs.stages[].class"
			case rootName == "archive-purge" &&
				(fieldPath == "remaining_repairs.stages.kind" ||
					fieldPath == "remaining_repairs.next_stage.kind"):
				key = "remaining_repairs.stages[].kind"
			case rootName == "archive-purge" &&
				fieldPath == "remaining_repairs.stages.repair_cwd":
				key = "repair_cwd"
			case tag == "retry_cwd":
				key = "retry_cwd"
			}
			if key != "" {
				inventory[current.Name()+"."+field.Name] = key
			}
			walk(rootName, field.Type, fieldPath)
		}
	}
	for _, item := range roots {
		walk(item.name, item.typ, "")
	}
	for field, key := range map[string]string{
		"preparePlan.action":                     "action",
		"IntentArchivePurgePlan.Outcome":         "outcome",
		"IntentArchivePurgePlan.Action":          "action",
		"IntentArchivePurgeResult.Outcome":       "outcome",
		"IntentArchivePurgeResult.Action":        "action",
		"IntentArchivePurgeResult.Resume":        "purge_progress.resume",
		"IntentArchiveRepairStage.Class":         "remaining_repairs.stages[].class",
		"IntentArchiveRepairStage.Kind":          "remaining_repairs.stages[].kind",
		"IntentArchiveRepairStage.RepairCWD":     "repair_cwd",
		"IntentArchiveNextRepairStage.Class":     "remaining_repairs.stages[].class",
		"IntentArchiveNextRepairStage.Kind":      "remaining_repairs.stages[].kind",
		"IntentArchivePurgePlan.SelectorKind":    "pending_purge.selector",
		"intentArchivePurgeOptions.selectorKind": "pending_purge.selector",
	} {
		inventory[field] = key
	}
	return inventory
}

