func s6ContractBaseline(t *testing.T) (s6ContractBaselineEvidence, error) {
	t.Helper()
	s6ContractBaselineOnce.Do(func() {
		s6ContractBaselineBuilds.Add(1)
		s6ContractBaselineCache.evidence, s6ContractBaselineCache.err =
			s6BuildContractBaseline(t)
		s6ContractBaselineReady.Store(true)
	})
	return cloneS6ContractBaseline(
		s6ContractBaselineCache.evidence,
	), s6ContractBaselineCache.err
}

func s6BuildContractBaseline(
	t *testing.T,
) (s6ContractBaselineEvidence, error) {
	t.Helper()
	var baseline s6ContractBaselineEvidence
	baseline.atomicErr = s6AtomicClaimGuardUncached(t)

	sources, err := s6VocabularyProductionSources(t)
	if err != nil {
		return baseline, fmt.Errorf("vocabulary production sources: %w", err)
	}
	baseline.vocabularySources = s6CloneSourceSet(sources)
	baseline.vocabularyEmissions, err =
		s6ProductionVocabularyEmissions(sources)
	if err == nil {
		baseline.vocabularies, err =
			s6DerivedProductionVocabulariesFromEmissions(
				sources, baseline.vocabularyEmissions,
			)
	}
	if err != nil {
		return baseline, fmt.Errorf("production vocabulary baseline: %w", err)
	}

	emissionProgram, err := s6BuildEmissionProgram(sources)
	if err != nil {
		return baseline, fmt.Errorf("production emission model: %w", err)
	}
	productionAdvisories, err := emissionProgram.emissionCodes("advisory")
	if err != nil {
		return baseline, fmt.Errorf("production advisory catalog: %w", err)
	}
	expectedAdvisories := append([]string(nil), s6AdvisoryCatalog...)
	sort.Strings(expectedAdvisories)
	if !reflect.DeepEqual(productionAdvisories, expectedAdvisories) {
		return baseline, fmt.Errorf(
			"production advisory codes = %v, want %v",
			productionAdvisories, expectedAdvisories,
		)
	}
	baseline.advisoryCatalog = append(
		[]string(nil), s6AdvisoryCatalog...,
	)
	baseline.advisoryReachable = make(
		map[string]string, len(s6AdvisoryCatalog),
	)
	baseline.advisoryObservations = make(
		map[string]s6RuntimeObservation, len(s6AdvisoryCatalog),
	)
	for _, code := range s6AdvisoryCatalog {
		observation := s6ObserveAdvisory(t, code)
		if !s6HasAdvisory(observation, code) {
			return baseline, fmt.Errorf(
				"advisory fixture %s observed exit=%d advisories=%v",
				code, observation.exit, observation.advisories,
			)
		}
		if observation.exit != s6ExpectedAdvisoryExit(code) {
			return baseline, fmt.Errorf(
				"advisory fixture %s exit=%d, want %d",
				code, observation.exit, s6ExpectedAdvisoryExit(code),
			)
		}
		baseline.advisoryReachable[code] =
			"TestS6AdvisoryRuntimeFixtures/" + code
		baseline.advisoryObservations[code] =
			cloneS6RuntimeObservation(observation)
	}
	exitZero, exitThree := s6ActualRepairRelationships(t)
	root, slug := intentArchiveCLIWorkspace(t)
	noRepairs := s6ArchivePurgeObservation(
		t, "--path", root, "feature", "intent-archive", "purge", slug,
		"--all", "--yes", "--json", "--quiet",
	)
	baseline.advisoryRelationships = []s6RepairRelationship{
		s6Relationship(exitZero),
		s6Relationship(exitThree),
		s6Relationship(noRepairs),
	}

	baseline.refusalCatalog, err = s6RefusalCatalogFromPRD(t)
	if err != nil {
		return baseline, fmt.Errorf("refusal catalog: %w", err)
	}
	if !reflect.DeepEqual(baseline.refusalCatalog, s6RefusalCatalog) {
		return baseline, fmt.Errorf(
			"PRD refusal catalog = %v, want frozen %v",
			baseline.refusalCatalog, s6RefusalCatalog,
		)
	}
	productionRefusals, err := emissionProgram.emissionCodes("refusal")
	if err != nil {
		return baseline, fmt.Errorf("production refusal catalog: %w", err)
	}
	sortedProduction := append([]string(nil), productionRefusals...)
	sortedCatalog := append([]string(nil), baseline.refusalCatalog...)
	sort.Strings(sortedProduction)
	sort.Strings(sortedCatalog)
	if !reflect.DeepEqual(sortedProduction, sortedCatalog) {
		return baseline, fmt.Errorf(
			"production refusal catalog = %v, want normative %v",
			sortedProduction, sortedCatalog,
		)
	}
	baseline.refusalEvidence = make(
		map[string]s6RefusalFixture, len(baseline.refusalCatalog),
	)
	baseline.refusalObservations = make(
		map[string]s6RuntimeObservation, len(baseline.refusalCatalog),
	)
	for _, code := range baseline.refusalCatalog {
		observation := s6ObserveRefusal(t, code)
		baseline.refusalObservations[code] =
			cloneS6RuntimeObservation(observation)
		baseline.refusalEvidence[code] = s6RefusalFixture{
			fixture:       "TestS6RefusalRuntimeFixtures/" + code,
			remediation:   observation.remediation,
			emittedCode:   observation.code,
			exit:          observation.exit,
			expectedExit:  s6ExpectedRefusalExit(code),
			relatedObject: observation.relatedObject,
		}
	}
	return baseline, nil
}

func cloneS6ContractBaseline(
	source s6ContractBaselineEvidence,
) s6ContractBaselineEvidence {
	result := s6ContractBaselineEvidence{
		advisoryCatalog: append(
			[]string(nil), source.advisoryCatalog...,
		),
		advisoryReachable: make(
			map[string]string, len(source.advisoryReachable),
		),
		advisoryRelationships: append(
			[]s6RepairRelationship(nil), source.advisoryRelationships...,
		),
		advisoryObservations: make(
			map[string]s6RuntimeObservation,
			len(source.advisoryObservations),
		),
		refusalCatalog: append(
			[]string(nil), source.refusalCatalog...,
		),
		refusalEvidence: make(
			map[string]s6RefusalFixture, len(source.refusalEvidence),
		),
		refusalObservations: make(
			map[string]s6RuntimeObservation,
			len(source.refusalObservations),
		),
		vocabularies: cloneS6Vocabulary(source.vocabularies),
		vocabularySources: s6CloneSourceSet(
			source.vocabularySources,
		),
		vocabularyEmissions: cloneS6Vocabulary(
			source.vocabularyEmissions,
		),
		atomicErr: source.atomicErr,
	}
	for code, fixture := range source.advisoryReachable {
		result.advisoryReachable[code] = fixture
	}
	for code, observation := range source.advisoryObservations {
		result.advisoryObservations[code] =
			cloneS6RuntimeObservation(observation)
	}
	for code, fixture := range source.refusalEvidence {
		result.refusalEvidence[code] = fixture
	}
	for code, observation := range source.refusalObservations {
		result.refusalObservations[code] =
			cloneS6RuntimeObservation(observation)
	}
	return result
}

func cloneS6RuntimeObservation(
	source s6RuntimeObservation,
) s6RuntimeObservation {
	result := source
	result.advisories = append([]string(nil), source.advisories...)
	result.advisoryText = make(
		map[string]prepareAdvisoryReport, len(source.advisoryText),
	)
	for code, advisory := range source.advisoryText {
		result.advisoryText[code] = advisory
	}
	return result
}

