func s6Relationship(observation s6RuntimeObservation) s6RepairRelationship {
	return s6RepairRelationship{
		exit:              observation.exit,
		outcome:           observation.outcome,
		hasRemaining:      observation.hasRemaining,
		hasRepairAdvisory: s6HasAdvisory(observation, "archive-repairs-remaining"),
	}
}

func validateS6Advisories(
	catalog []string,
	reachable map[string]string,
	relationships []s6RepairRelationship,
) error {
	if !reflect.DeepEqual(catalog, s6AdvisoryCatalog) {
		return fmt.Errorf("advisory catalog = %v, want ordered %v", catalog, s6AdvisoryCatalog)
	}
	seen := map[string]bool{}
	for _, code := range catalog {
		if seen[code] {
			return fmt.Errorf("duplicate advisory code %q", code)
		}
		seen[code] = true
		if strings.TrimSpace(reachable[code]) == "" {
			return fmt.Errorf("advisory code %q has no reachable named fixture", code)
		}
	}
	if len(seen) != 18 {
		return fmt.Errorf("advisory catalog has %d codes, want 18", len(seen))
	}
	for code := range reachable {
		if !seen[code] {
			return fmt.Errorf("extra advisory fixture %q is outside the closed catalog", code)
		}
	}
	wantRelationships := []s6RepairRelationship{
		{exit: 0, outcome: "purged", hasRemaining: true, hasRepairAdvisory: true},
		{exit: 3, outcome: "refused", hasRemaining: true, hasRepairAdvisory: false},
		{exit: 0, outcome: "no-op", hasRemaining: false, hasRepairAdvisory: false},
	}
	if !reflect.DeepEqual(relationships, wantRelationships) {
		return fmt.Errorf(
			"remaining-repair production relationships = %+v, want exact %+v",
			relationships, wantRelationships,
		)
	}
	for _, row := range relationships {
		switch row.exit {
		case 0:
			if row.hasRemaining != row.hasRepairAdvisory {
				return fmt.Errorf("exit-0 remaining/advisory relationship violated: %+v", row)
			}
		case 3:
			if row.hasRepairAdvisory {
				return fmt.Errorf("exit-3 refusal carries archive-repairs-remaining: %+v", row)
			}
		}
	}
	return nil
}

func s6AdvisoryGuard(t *testing.T) error {
	catalog, reachable, relationships, err := s6AdvisoryEvidence(t)
	if err != nil {
		return err
	}
	return validateS6Advisories(catalog, reachable, relationships)
}

