func s6RefusalCatalogFromPRD(t *testing.T) ([]string, error) {
	t.Helper()
	body := s6RepoFile(t, "docs/prds/PRD-prepare-intent-bundle.md")
	start := strings.Index(body, "### 10.4.1 Closed refusal catalog")
	end := strings.Index(body[start:], "### 10.5 Precedence")
	if start < 0 || end < 0 {
		return nil, errors.New("cannot locate §10.4.1 refusal catalog")
	}
	section := body[start : start+end]
	codeRE := regexp.MustCompile("`([a-z][a-z0-9-]+)`")
	seen := map[string]bool{}
	var codes []string
	for _, line := range strings.Split(section, "\n") {
		if !strings.HasPrefix(line, "| `") {
			continue
		}
		firstCell := strings.SplitN(strings.TrimPrefix(line, "|"), "|", 2)[0]
		for _, match := range codeRE.FindAllStringSubmatch(firstCell, -1) {
			code := match[1]
			if !seen[code] {
				seen[code] = true
				codes = append(codes, code)
			}
		}
	}
	if len(codes) == 0 {
		return nil, errors.New("parsed no refusal codes from §10.4.1")
	}
	return codes, nil
}

