func s6ExpectedRefusalExit(code string) int {
	switch code {
	case "artifact-empty-not-overwritten", "incoherent-bundle-gap",
		"not-ready", "staged-output-invalid":
		return 2
	case "entry-appeared", "entry-changed", "status-changed",
		"archive-index-changed", "regenerate-generation-failed",
		"workspace-root-changed",
		"archive-purge-partial":
		return 5
	case "undo-cas-mismatch",
		"recovery-divergent",
		"journal-corrupt",
		"journal-version-mismatch",
		"journal-foreign",
		"journal-path-escape",
		"journal-forged",
		"post-publication-divergence",
		"workspace-root-replaced-after-publication",
		"archive-purge-evidence-divergent":
		return 6
	default:
		return 3
	}
}

