type s6EmissionDomain struct {
	values  map[string]bool
	direct  map[string]bool
	unknown bool
}

func s6NewEmissionDomain() s6EmissionDomain {
	return s6EmissionDomain{values: map[string]bool{}, direct: map[string]bool{}}
}

func (domain *s6EmissionDomain) merge(other s6EmissionDomain) bool {
	changed := false
	if domain.values == nil {
		domain.values = map[string]bool{}
	}
	if domain.direct == nil {
		domain.direct = map[string]bool{}
	}
	for value := range other.values {
		if !domain.values[value] {
			domain.values[value] = true
			changed = true
		}
	}
	for value := range other.direct {
		if !domain.direct[value] {
			domain.direct[value] = true
			changed = true
		}
	}
	if other.unknown && !domain.unknown {
		domain.unknown = true
		changed = true
	}
	return changed
}

type s6EmissionFunction struct {
	key            string
	baseKey        string
	rel            string
	pkg            string
	file           *ast.File
	function       *ast.FuncDecl
	imports        map[string]string
	locals         map[string]s6TypeRef
	bindings       map[string][]ast.Expr
	objectBindings map[*ast.Object][]ast.Expr
	literalCalls   map[*ast.CallExpr]*ast.FuncLit
	closureCache   map[*ast.FuncLit]s6ClosureInvocationSummary
}

type s6EmissionProgram struct {
	functions         map[string]*s6EmissionFunction
	byBase            map[string][]string
	reachable         map[string]bool
	domains           map[string]map[string]s6EmissionDomain
	constants         map[string]string
	types             map[string][]string
	model             *s6SourceTypeModel
	emissionPotential map[string]bool
}

func s6BuildEmissionProgram(sources map[string]string) (*s6EmissionProgram, error) {
	model, err := s6BuildSourceTypeModel(s6EmissionTypeSources(sources))
	if err != nil {
		return nil, err
	}
	constants, err := s6StringConstantValues(sources)
	if err != nil {
		return nil, err
	}
	program := &s6EmissionProgram{
		functions:         map[string]*s6EmissionFunction{},
		byBase:            map[string][]string{},
		reachable:         map[string]bool{},
		domains:           map[string]map[string]s6EmissionDomain{},
		constants:         constants,
		types:             s6TypedStringConstantDomains(sources, constants),
		model:             model,
		emissionPotential: map[string]bool{},
	}
	for rel, source := range sources {
		file, parseErr := s6ParseSource(rel, source)
		if parseErr != nil {
			return nil, parseErr
		}
		pkg := filepath.Dir(rel)
		imports := s6FileImportDirs(file)
		for _, declaration := range file.Decls {
			function, ok := declaration.(*ast.FuncDecl)
			if !ok || function.Body == nil {
				continue
			}
			baseKey := s6PrepareFunctionKey(pkg, function)
			key := s6PrepareReachabilityKey(rel, pkg, function)
			program.functions[key] = &s6EmissionFunction{
				key: key, baseKey: baseKey, rel: rel, pkg: pkg, file: file,
				function: function, imports: imports,
				locals:         s6FunctionLocalTypes(pkg, file, function, model),
				bindings:       s6FunctionBindingValues(function),
				objectBindings: s6FunctionObjectBindingValues(function),
				literalCalls:   s6FunctionLiteralCalls(function),
				closureCache:   map[*ast.FuncLit]s6ClosureInvocationSummary{},
			}
			program.byBase[baseKey] = append(program.byBase[baseKey], key)
		}
	}
	program.emissionPotential = program.publicEmissionPotential()
	var queue []string
	for _, root := range []string{
		"internal/cli.runPreparePublish",
		"internal/cli.runFeatureIntentArchiveList",
		"internal/cli.runFeatureIntentArchivePurge",
	} {
		for _, key := range program.byBase[root] {
			program.reachable[key] = true
			queue = append(queue, key)
		}
	}
	for len(queue) != 0 {
		key := queue[0]
		queue = queue[1:]
		node := program.functions[key]
		for _, call := range s6FunctionCalls(node.function) {
			literal := node.literalCalls[call]
			if literal != nil &&
				program.callMayReachPublicEmission(node, call, literal) {
				_, callReachable, closureErr := s6MutationBindingsBeforeKnownLiteral(
					node.function, call, literal,
					node.pkg, node.imports, node.locals, model,
					node.closureCache,
				)
				if closureErr != nil {
					return nil, fmt.Errorf(
						"%s callable reachability: %w", node.rel, closureErr,
					)
				}
				if !callReachable {
					continue
				}
			}
			for _, callee := range program.resolveCall(node, call) {
				if !program.reachable[callee] {
					program.reachable[callee] = true
					queue = append(queue, callee)
				}
			}
		}
	}
	for key := range program.reachable {
		node := program.functions[key]
		if s6FunctionContainsGoto(node.function) {
			return nil, fmt.Errorf(
				"%s:%s: goto in guarded reachable emission flow is unsupported",
				node.rel, node.function.Name.Name,
			)
		}
	}
	for key := range program.reachable {
		program.domains[key] = map[string]s6EmissionDomain{}
	}
	for {
		changed := false
		for key := range program.reachable {
			node := program.functions[key]
			for _, call := range s6FunctionCalls(node.function) {
				literal := node.literalCalls[call]
				if literal != nil &&
					program.callMayReachPublicEmission(node, call, literal) {
					_, callReachable, closureErr := s6MutationBindingsBeforeKnownLiteral(
						node.function, call, literal,
						node.pkg, node.imports, node.locals, model,
						node.closureCache,
					)
					if closureErr != nil {
						return nil, fmt.Errorf(
							"%s callable domain flow: %w", node.rel, closureErr,
						)
					}
					if !callReachable {
						continue
					}
				}
				for _, calleeKey := range program.resolveCall(node, call) {
					if !program.reachable[calleeKey] {
						continue
					}
					callee := program.functions[calleeKey]
					params := s6FunctionParameterNames(callee.function)
					for index, name := range params {
						if index >= len(call.Args) {
							continue
						}
						value := program.resolveExpression(
							node, call.Args[index], program.domains[key], map[string]bool{},
						)
						current := program.domains[calleeKey][name]
						if current.values == nil {
							current = s6NewEmissionDomain()
						}
						if current.merge(value) {
							program.domains[calleeKey][name] = current
							changed = true
						}
					}
				}
			}
		}
		if !changed {
			break
		}
	}
	return program, nil
}

func s6EmissionTypeSources(sources map[string]string) map[string]string {
	cloned := make(map[string]string, len(sources)+1)
	declared := map[string]bool{}
	hasCLI := false
	for rel, source := range sources {
		cloned[rel] = source
		if filepath.ToSlash(filepath.Dir(rel)) != "internal/cli" {
			continue
		}
		hasCLI = true
		file, err := s6ParseSource(rel, source)
		if err != nil {
			continue
		}
		for _, declaration := range file.Decls {
			switch typed := declaration.(type) {
			case *ast.FuncDecl:
				declared[typed.Name.Name] = true
			case *ast.GenDecl:
				for _, spec := range typed.Specs {
					switch item := spec.(type) {
					case *ast.TypeSpec:
						declared[item.Name.Name] = true
					case *ast.ValueSpec:
						for _, name := range item.Names {
							declared[name.Name] = true
						}
					}
				}
			}
		}
	}
	if !hasCLI {
		return cloned
	}
	var declarations []string
	if !declared["prepareAdvisoryReport"] {
		declarations = append(
			declarations,
			"type prepareAdvisoryReport struct { Code string }",
		)
	}
	if !declared["prepareRefusalReport"] {
		declarations = append(
			declarations,
			"type prepareRefusalReport struct { Code string }",
		)
	}
	if !declared["intentArchiveRefusalReport"] {
		declarations = append(
			declarations,
			"type intentArchiveRefusalReport struct { Code string }",
		)
	}
	if !declared["preparePublishReport"] {
		declarations = append(declarations, `type preparePublishReport struct {
	Advisories []prepareAdvisoryReport
	Refusal *prepareRefusalReport
}`)
	}
	if !declared["prepareAdvisory"] {
		declarations = append(declarations, `func prepareAdvisory(
	code, detail, message string,
) prepareAdvisoryReport {
	return prepareAdvisoryReport{Code: code}
}`)
	}
	if !declared["refusePrepare"] {
		declarations = append(declarations, `func refusePrepare(
	report preparePublishReport,
	code, remediation string,
) preparePublishReport {
	return report
}`)
	}
	if len(declarations) != 0 {
		cloned["internal/cli/zz_s6_emission_types.go"] = "package cli\n" +
			strings.Join(declarations, "\n")
	}
	return cloned
}

func (program *s6EmissionProgram) publicEmissionPotential() map[string]bool {
	potential := map[string]bool{}
	for key, node := range program.functions {
		if s6NodeContainsDirectPublicEmission(node.function.Body) {
			potential[key] = true
		}
	}
	for range len(program.functions) + 1 {
		changed := false
		for key, node := range program.functions {
			if potential[key] {
				continue
			}
			for _, call := range s6FunctionCalls(node.function) {
				for _, callee := range program.resolveCall(node, call) {
					if potential[callee] {
						potential[key] = true
						changed = true
						break
					}
				}
				if potential[key] {
					break
				}
			}
		}
		if !changed {
			break
		}
	}
	return potential
}

func s6NodeContainsDirectPublicEmission(root ast.Node) bool {
	found := false
	ast.Inspect(root, func(node ast.Node) bool {
		if found {
			return false
		}
		switch typed := node.(type) {
		case *ast.CallExpr:
			switch s6CallName(typed) {
			case "prepareAdvisory", "refusePrepare", "intentArchiveSimpleRefusal":
				found = true
			}
		case *ast.CompositeLit:
			switch s6CompositeTypeName(typed.Type) {
			case "prepareAdvisoryReport", "prepareRefusalReport",
				"intentArchiveRefusalReport":
				found = true
			}
		case *ast.AssignStmt:
			for _, lhs := range typed.Lhs {
				if selector, ok := lhs.(*ast.SelectorExpr); ok &&
					selector.Sel.Name == "Code" {
					found = true
				}
			}
		}
		return !found
	})
	return found
}

func (program *s6EmissionProgram) callMayReachPublicEmission(
	node *s6EmissionFunction,
	call *ast.CallExpr,
	literal *ast.FuncLit,
) bool {
	if s6FunctionLiteralMayEmit(literal, "advisory") ||
		s6FunctionLiteralMayEmit(literal, "refusal") {
		return true
	}
	for _, callee := range program.resolveCall(node, call) {
		if program.emissionPotential[callee] {
			return true
		}
	}
	return false
}

func s6FunctionObjectBindingValues(function *ast.FuncDecl) map[*ast.Object][]ast.Expr {
	result := map[*ast.Object][]ast.Expr{}
	ast.Inspect(function.Body, func(raw ast.Node) bool {
		switch typed := raw.(type) {
		case *ast.AssignStmt:
			if len(typed.Lhs) != len(typed.Rhs) {
				return true
			}
			for index, lhs := range typed.Lhs {
				if identifier, ok := lhs.(*ast.Ident); ok && identifier.Obj != nil {
					result[identifier.Obj] = append(result[identifier.Obj], typed.Rhs[index])
				}
			}
		case *ast.ValueSpec:
			if len(typed.Names) != len(typed.Values) {
				return true
			}
			for index, name := range typed.Names {
				if name.Obj != nil {
					result[name.Obj] = append(result[name.Obj], typed.Values[index])
				}
			}
		}
		return true
	})
	return result
}

func s6FunctionCalls(function *ast.FuncDecl) []*ast.CallExpr {
	var calls []*ast.CallExpr
	ast.Inspect(function.Body, func(node ast.Node) bool {
		if call, ok := node.(*ast.CallExpr); ok {
			calls = append(calls, call)
		}
		return true
	})
	return calls
}

func s6FunctionParameterNames(function *ast.FuncDecl) []string {
	var result []string
	if function.Type.Params == nil {
		return result
	}
	for _, field := range function.Type.Params.List {
		for _, name := range field.Names {
			result = append(result, name.Name)
		}
	}
	return result
}

func (program *s6EmissionProgram) resolveCall(
	node *s6EmissionFunction,
	call *ast.CallExpr,
) []string {
	identities, _ := program.resolveCallableIdentities(
		node, call.Fun, map[*ast.Object]bool{}, map[string]bool{},
	)
	var result []string
	for _, identity := range identities {
		result = append(result, program.byBase[identity.functionKey()]...)
	}
	return s6UniqueStrings(result)
}

func (program *s6EmissionProgram) resolveCallableIdentities(
	node *s6EmissionFunction,
	expression ast.Expr,
	resolvingObjects map[*ast.Object]bool,
	resolvingNames map[string]bool,
) ([]s6CallIdentity, bool) {
	_ = resolvingObjects
	_ = resolvingNames
	return s6ResolveCallableIdentitiesFromContext(
		expression,
		s6CallableContext{
			pkg: node.pkg, imports: node.imports, locals: node.locals,
			bindings: s6FunctionBindingsBefore(node.function, expression.Pos()),
			params:   s6FunctionCallableParameters(node.function), functionKey: node.baseKey,
		},
		program.model,
		map[string]bool{},
	)
}

func s6UniqueCallIdentities(values []s6CallIdentity) []s6CallIdentity {
	seen := map[string]bool{}
	var result []s6CallIdentity
	for _, value := range values {
		key := value.functionKey() + ":" + strconv.FormatBool(value.explicitReceiver)
		if value.literal != nil {
			key += ":" + strconv.FormatInt(int64(value.literal.Pos()), 10)
		}
		if value.known && !seen[key] {
			seen[key] = true
			result = append(result, value)
		}
	}
	return result
}

func (program *s6EmissionProgram) resolveExpression(
	node *s6EmissionFunction,
	expression ast.Expr,
	parameters map[string]s6EmissionDomain,
	resolving map[string]bool,
) s6EmissionDomain {
	result := s6NewEmissionDomain()
	switch typed := expression.(type) {
	case *ast.BasicLit:
		if value, ok := s6StringLiteral(typed); ok {
			result.values[value] = true
			result.direct[value] = true
		} else {
			result.unknown = true
		}
	case *ast.Ident:
		if value, ok := program.constants[node.pkg+"."+typed.Name]; ok {
			result.values[value] = true
			result.direct[value] = true
			return result
		}
		if parameter, ok := parameters[typed.Name]; ok {
			result.merge(parameter)
			return result
		}
		if resolving[typed.Name] {
			result.unknown = true
			return result
		}
		candidates := node.objectBindings[typed.Obj]
		if typed.Obj == nil {
			candidates = node.bindings[typed.Name]
		}
		if len(candidates) == 0 {
			tuple := program.resolveTupleResult(
				node, typed.Name, typed.Obj, parameters, resolving,
			)
			if len(tuple.values) != 0 || tuple.unknown {
				return tuple
			}
			result.unknown = true
			return result
		}
		resolving[typed.Name] = true
		for _, candidate := range candidates {
			result.merge(program.resolveExpression(node, candidate, parameters, resolving))
		}
		delete(resolving, typed.Name)
	case *ast.SelectorExpr:
		if alias, ok := typed.X.(*ast.Ident); ok && node.imports[alias.Name] != "" {
			if value, found := program.constants[node.imports[alias.Name]+"."+typed.Sel.Name]; found {
				result.values[value] = true
				result.direct[value] = true
				return result
			}
		}
		ref := s6ExpressionType(node.pkg, node.imports, typed, node.locals, program.model)
		if values := program.types[ref.key()]; len(values) != 0 {
			for _, value := range values {
				result.values[value] = true
			}
			return result
		}
		result.unknown = true
	case *ast.CallExpr:
		if len(typed.Args) == 1 {
			if identifier, ok := typed.Fun.(*ast.Ident); ok && identifier.Name == "string" {
				return program.resolveExpression(node, typed.Args[0], parameters, resolving)
			}
		}
		var merged bool
		for _, calleeKey := range program.resolveCall(node, typed) {
			marker := "call:" + calleeKey
			if resolving[marker] {
				result.unknown = true
				continue
			}
			resolving[marker] = true
			callee := program.functions[calleeKey]
			for _, returned := range program.model.returnExpressions[callee.baseKey][0] {
				result.merge(program.resolveBoundExpression(
					callee, returned, program.domains[calleeKey], resolving,
				))
				merged = true
			}
			delete(resolving, marker)
		}
		if !merged {
			result.unknown = true
		}
	default:
		result.unknown = true
	}
	return result
}

func (program *s6EmissionProgram) resolveBoundExpression(
	node *s6EmissionFunction,
	bound s6BoundExpression,
	parameters map[string]s6EmissionDomain,
	resolving map[string]bool,
) s6EmissionDomain {
	if bound.unresolved || bound.expression == nil {
		result := s6NewEmissionDomain()
		result.unknown = true
		return result
	}
	boundNode := *node
	if bound.pkg != "" {
		boundNode.pkg = bound.pkg
	}
	if bound.imports != nil {
		boundNode.imports = bound.imports
	}
	if bound.locals != nil {
		locals := make(map[string]s6TypeRef, len(node.locals)+len(bound.locals))
		for name, ref := range node.locals {
			locals[name] = ref
		}
		for name, ref := range bound.locals {
			locals[name] = ref
		}
		boundNode.locals = locals
	}
	if bound.bindings != nil {
		boundNode.bindings = bound.bindings.byName
		boundNode.objectBindings = bound.bindings.byObject
	}
	return program.resolveExpression(
		&boundNode, bound.expression, parameters, resolving,
	)
}

func (program *s6EmissionProgram) resolveTupleResult(
	node *s6EmissionFunction,
	name string,
	object *ast.Object,
	parameters map[string]s6EmissionDomain,
	resolving map[string]bool,
) s6EmissionDomain {
	result := s6NewEmissionDomain()
	found := false
	ast.Inspect(node.function.Body, func(raw ast.Node) bool {
		assignment, ok := raw.(*ast.AssignStmt)
		if !ok || len(assignment.Rhs) != 1 || len(assignment.Lhs) <= 1 {
			return true
		}
		call, ok := assignment.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		position := -1
		for index, lhs := range assignment.Lhs {
			if identifier, ok := lhs.(*ast.Ident); ok &&
				((object != nil && identifier.Obj == object) ||
					(object == nil && identifier.Name == name)) {
				position = index
				break
			}
		}
		if position < 0 {
			return true
		}
		result.merge(program.resolveCallResultPosition(
			node, call, position, parameters, resolving,
		))
		found = true
		return true
	})
	if !found {
		return s6NewEmissionDomain()
	}
	return result
}

func (program *s6EmissionProgram) resolveCallResultPosition(
	node *s6EmissionFunction,
	call *ast.CallExpr,
	position int,
	parameters map[string]s6EmissionDomain,
	resolving map[string]bool,
) s6EmissionDomain {
	result := s6NewEmissionDomain()
	found := false
	for _, calleeKey := range program.resolveCall(node, call) {
		found = true
		callee := program.functions[calleeKey]
		marker := "tuple:" + calleeKey + ":" + strconv.Itoa(position)
		if resolving[marker] {
			result.unknown = true
			continue
		}
		returned := program.model.returnExpressions[callee.baseKey][position]
		if len(returned) == 0 {
			result.unknown = true
			continue
		}
		resolving[marker] = true
		for _, candidate := range returned {
			if candidate.tupleForward {
				call, ok := candidate.expression.(*ast.CallExpr)
				if !ok {
					result.unknown = true
					continue
				}
				result.merge(program.resolveCallResultPosition(
					callee, call, candidate.tuplePosition,
					program.domains[calleeKey], resolving,
				))
				continue
			}
			result.merge(program.resolveBoundExpression(
				callee, candidate, program.domains[calleeKey], resolving,
			))
		}
		delete(resolving, marker)
	}
	if !found {
		result.unknown = true
	}
	return result
}

func (program *s6EmissionProgram) resolveAssignmentPosition(
	node *s6EmissionFunction,
	assignment *ast.AssignStmt,
	position int,
	parameters map[string]s6EmissionDomain,
) s6EmissionDomain {
	if len(assignment.Rhs) == len(assignment.Lhs) && position < len(assignment.Rhs) {
		return program.resolveExpression(
			node, assignment.Rhs[position], parameters, map[string]bool{},
		)
	}
	if len(assignment.Rhs) == 1 && len(assignment.Lhs) > 1 {
		if call, ok := assignment.Rhs[0].(*ast.CallExpr); ok {
			return program.resolveCallResultPosition(
				node, call, position, parameters, map[string]bool{},
			)
		}
	}
	result := s6NewEmissionDomain()
	result.unknown = true
	return result
}

func (program *s6EmissionProgram) callableAliasCouldEmit(
	node *s6EmissionFunction,
	call *ast.CallExpr,
	kind string,
	resolved []s6CallIdentity,
) bool {
	identifier, ok := call.Fun.(*ast.Ident)
	var callableField *ast.SelectorExpr
	hasBinding := false
	if ok {
		hasBinding = len(node.objectBindings[identifier.Obj]) != 0 ||
			identifier.Obj == nil && len(node.bindings[identifier.Name]) != 0 ||
			program.model.globalValues[node.pkg+"."+identifier.Name] != nil ||
			s6FunctionCallableParameters(node.function)[identifier.Name]
	} else if selector, selectorOK := call.Fun.(*ast.SelectorExpr); selectorOK {
		callableField = selector
		_, hasBinding, _ = s6CallableFieldValues(
			selector,
			s6CallableContext{
				pkg: node.pkg, imports: node.imports, locals: node.locals,
				bindings:    s6FunctionBindingsBefore(node.function, call.Pos()),
				params:      s6FunctionCallableParameters(node.function),
				functionKey: node.baseKey,
			},
			program.model,
			map[string]bool{},
		)
	}
	if !hasBinding {
		return false
	}
	if kind == "refusal" {
		if len(call.Args) < 2 {
			return false
		}
		ref := s6ExpressionType(
			node.pkg, node.imports, call.Args[0], node.locals, program.model,
		)
		return ref.name == "preparePublishReport" || ref.name == "intentArchivePurgeReport"
	}
	for _, identity := range resolved {
		if identity.name == "prepareAdvisory" {
			return true
		}
	}
	if len(call.Args) < 3 {
		return false
	}
	if ok {
		return s6CallableParameterReturns(
			node.function, identifier.Name, "prepareAdvisoryReport",
		) || program.callableAliasReturns(
			node, identifier, "prepareAdvisoryReport",
		)
	}
	return s6CallableFieldReturns(
		node, callableField, program.model, "prepareAdvisoryReport",
	)
}

func (program *s6EmissionProgram) callableAliasReturns(
	node *s6EmissionFunction,
	identifier *ast.Ident,
	typeName string,
) bool {
	bindings := s6FunctionBindingsBefore(node.function, identifier.Pos())
	for _, candidate := range bindings.candidates(identifier) {
		call, ok := candidate.(*ast.CallExpr)
		if !ok {
			continue
		}
		identities, unresolved := s6ResolveCallableIdentitiesFromContext(
			call.Fun,
			s6CallableContext{
				pkg: node.pkg, imports: node.imports, locals: node.locals,
				bindings: bindings, params: s6FunctionCallableParameters(node.function),
				functionKey: node.baseKey,
			},
			program.model,
			map[string]bool{},
		)
		if unresolved {
			return true
		}
		for _, identity := range identities {
			key := identity.functionKey()
			for _, result := range program.model.functionCallableResults[key][0] {
				if result.name == typeName {
					return true
				}
			}
		}
	}
	return false
}

func s6CallableFieldReturns(
	node *s6EmissionFunction,
	selector *ast.SelectorExpr,
	model *s6SourceTypeModel,
	typeName string,
) bool {
	if selector == nil {
		return false
	}
	base := model.resolveAlias(
		s6ExpressionType(node.pkg, node.imports, selector.X, node.locals, model),
	)
	for _, result := range model.callableFieldResults[base.key()+"."+selector.Sel.Name] {
		if result.name == typeName {
			return true
		}
	}
	return false
}

func s6CallableParameterReturns(
	function *ast.FuncDecl,
	name string,
	typeName string,
) bool {
	if function.Type.Params == nil {
		return false
	}
	for _, field := range function.Type.Params.List {
		callable, ok := field.Type.(*ast.FuncType)
		if !ok || callable.Results == nil {
			continue
		}
		matchesName := false
		for _, parameter := range field.Names {
			matchesName = matchesName || parameter.Name == name
		}
		if !matchesName {
			continue
		}
		for _, result := range callable.Results.List {
			if s6CompositeTypeName(result.Type) == typeName {
				return true
			}
		}
	}
	return false
}

func (program *s6EmissionProgram) functionLiteralDomains(
	node *s6EmissionFunction,
	literal *ast.FuncLit,
) (map[string]s6EmissionDomain, bool, bool) {
	domains := map[string]s6EmissionDomain{}
	for name, value := range program.domains[node.key] {
		domains[name] = value
	}
	names := s6FunctionTypeParameterNames(literal.Type)
	reachable := false
	unresolved := false
	ast.Inspect(node.function.Body, func(raw ast.Node) bool {
		if raw == literal {
			return false
		}
		call, ok := raw.(*ast.CallExpr)
		if !ok {
			return true
		}
		identities, callUnresolved := program.resolveCallableIdentities(
			node, call.Fun, map[*ast.Object]bool{}, map[string]bool{},
		)
		matches := false
		for _, identity := range identities {
			if s6SameFunctionLiteral(identity.literal, literal) {
				matches = true
				reachable = true
				for index, name := range names {
					if index >= len(call.Args) {
						unresolved = true
						continue
					}
					domain := domains[name]
					if domain.values == nil {
						domain = s6NewEmissionDomain()
					}
					domain.merge(program.resolveExpression(
						node,
						call.Args[index],
						program.domains[node.key],
						map[string]bool{},
					))
					domains[name] = domain
				}
			}
		}
		if callUnresolved && s6ExpressionContainsFunctionLiteral(
			call.Fun,
			literal,
			s6FunctionBindingsBefore(node.function, call.Pos()),
			map[string]bool{},
		) {
			unresolved = true
		}
		for argumentIndex, argument := range call.Args {
			if !s6ExpressionContainsFunctionLiteral(
				argument,
				literal,
				s6FunctionBindingsBefore(node.function, call.Pos()),
				map[string]bool{},
			) {
				continue
			}
			if !matches {
				callbackDomains, invoked, callbackUnresolved :=
					program.functionLiteralCallbackDomains(
						node, call, argumentIndex, names,
					)
				if invoked {
					reachable = true
					for name, value := range callbackDomains {
						domain := domains[name]
						if domain.values == nil {
							domain = s6NewEmissionDomain()
						}
						domain.merge(value)
						domains[name] = domain
					}
				} else {
					unresolved = true
				}
				unresolved = unresolved || callbackUnresolved
			}
		}
		return true
	})
	if s6FunctionLiteralReturned(node.function, literal) {
		for callerKey := range program.reachable {
			caller := program.functions[callerKey]
			for _, call := range s6FunctionCalls(caller.function) {
				identities, callUnresolved := program.resolveCallableIdentities(
					caller, call.Fun, map[*ast.Object]bool{}, map[string]bool{},
				)
				matched := false
				for _, identity := range identities {
					if !s6SameFunctionLiteral(identity.literal, literal) {
						continue
					}
					matched = true
					reachable = true
					for index, name := range names {
						if index >= len(call.Args) {
							unresolved = true
							continue
						}
						domain := domains[name]
						if domain.values == nil {
							domain = s6NewEmissionDomain()
						}
						domain.merge(program.resolveExpression(
							caller,
							call.Args[index],
							program.domains[callerKey],
							map[string]bool{},
						))
						domains[name] = domain
					}
				}
				if callUnresolved && matched {
					unresolved = true
				}
			}
		}
		if !reachable {
			unresolved = true
		}
	}
	return domains, reachable, unresolved
}

func s6FunctionLiteralReturned(
	function *ast.FuncDecl,
	literal *ast.FuncLit,
) bool {
	returned := false
	ast.Inspect(function.Body, func(node ast.Node) bool {
		statement, ok := node.(*ast.ReturnStmt)
		if !ok {
			return true
		}
		bindings := s6FunctionBindingsBefore(function, statement.Pos())
		for _, result := range statement.Results {
			if s6ExpressionContainsFunctionLiteral(
				result, literal, bindings, map[string]bool{},
			) {
				returned = true
				return false
			}
		}
		return true
	})
	return returned
}

func (program *s6EmissionProgram) functionLiteralCallbackDomains(
	caller *s6EmissionFunction,
	outerCall *ast.CallExpr,
	argumentIndex int,
	literalParams []string,
) (map[string]s6EmissionDomain, bool, bool) {
	result := map[string]s6EmissionDomain{}
	invoked := false
	unresolved := false
	for _, calleeKey := range program.resolveCall(caller, outerCall) {
		callee := program.functions[calleeKey]
		params := s6FunctionParameterNames(callee.function)
		if argumentIndex >= len(params) {
			unresolved = true
			continue
		}
		callbackParam := params[argumentIndex]
		if !program.model.calledCallableParams[callee.baseKey][callbackParam] {
			continue
		}
		matchedCall := false
		for _, callbackCall := range s6FunctionCalls(callee.function) {
			bindings := s6FunctionBindingsBefore(
				callee.function, callbackCall.Pos(),
			)
			references := s6CallableParametersReferencedBy(
				callbackCall.Fun,
				map[string]bool{callbackParam: true},
				bindings,
				map[string]bool{},
			)
			if len(references) == 0 {
				continue
			}
			matchedCall = true
			invoked = true
			for index, name := range literalParams {
				if index >= len(callbackCall.Args) {
					unresolved = true
					continue
				}
				domain := result[name]
				if domain.values == nil {
					domain = s6NewEmissionDomain()
				}
				domain.merge(program.resolveExpression(
					callee,
					callbackCall.Args[index],
					program.domains[calleeKey],
					map[string]bool{},
				))
				result[name] = domain
			}
		}
		if !matchedCall {
			unresolved = true
		}
	}
	return result, invoked, unresolved
}

func s6FunctionTypeParameterNames(function *ast.FuncType) []string {
	var result []string
	if function == nil || function.Params == nil {
		return result
	}
	for _, field := range function.Params.List {
		for _, name := range field.Names {
			result = append(result, name.Name)
		}
	}
	return result
}

func (program *s6EmissionProgram) emissionCodes(kind string) ([]string, error) {
	seen := map[string]bool{}
	for key := range program.reachable {
		node := program.functions[key]
		var scanErr error
		ast.Inspect(node.function.Body, func(raw ast.Node) bool {
			if scanErr != nil {
				return false
			}
			if raw == nil {
				return false
			}
			parameters := program.domains[key]
			if literal := s6InnermostContainingFunctionLiteral(
				node.function, raw.Pos(),
			); literal != nil {
				if !s6FunctionLiteralMayEmit(literal, kind) {
					return false
				}
				literalDomains, reachable, unresolved := program.functionLiteralDomains(
					node, literal,
				)
				if unresolved {
					scanErr = fmt.Errorf(
						"%s:%s has unresolved invoked function-literal %s flow",
						node.rel, node.function.Name.Name, kind,
					)
					return false
				}
				if !reachable {
					return false
				}
				parameters = literalDomains
			}
			var expression ast.Expr
			var resolvedDomain *s6EmissionDomain
			switch typed := raw.(type) {
			case *ast.CallExpr:
				identities, unresolved := program.resolveCallableIdentities(
					node, typed.Fun, map[*ast.Object]bool{}, map[string]bool{},
				)
				if unresolved && program.callableAliasCouldEmit(node, typed, kind, identities) {
					scanErr = fmt.Errorf(
						"%s:%s has unresolved reachable public %s callable alias %s resolved=%v",
						node.rel, node.function.Name.Name, kind, s6CallName(typed), identities,
					)
					return false
				}
				for _, identity := range identities {
					if kind == "advisory" && identity.name == "prepareAdvisory" &&
						len(typed.Args) != 0 {
						expression = typed.Args[0]
					}
					if kind == "refusal" {
						switch identity.name {
						case "refusePrepare":
							if len(typed.Args) >= 2 {
								expression = typed.Args[1]
							}
						case "intentArchiveSimpleRefusal":
							if len(typed.Args) != 0 {
								expression = typed.Args[0]
							}
						}
					}
				}
			case *ast.CompositeLit:
				if (kind == "advisory" && node.function.Name.Name == "prepareAdvisory") ||
					(kind == "refusal" &&
						(node.function.Name.Name == "refusePrepare" ||
							node.function.Name.Name == "intentArchiveSimpleRefusal")) {
					return true
				}
				typeName := s6CompositeTypeName(typed.Type)
				isTarget := kind == "advisory" && typeName == "prepareAdvisoryReport"
				isTarget = isTarget || kind == "refusal" &&
					(typeName == "prepareRefusalReport" ||
						typeName == "intentArchiveRefusalReport")
				if !isTarget {
					return true
				}
				for _, rawField := range typed.Elts {
					field, ok := rawField.(*ast.KeyValueExpr)
					if !ok {
						continue
					}
					name, ok := field.Key.(*ast.Ident)
					if ok && name.Name == "Code" {
						expression = field.Value
					}
				}
			case *ast.AssignStmt:
				for index, lhs := range typed.Lhs {
					selector, ok := lhs.(*ast.SelectorExpr)
					if !ok || selector.Sel.Name != "Code" {
						continue
					}
					parent := s6ExpressionType(
						node.pkg, node.imports, selector.X, node.locals, program.model,
					)
					isTarget := kind == "refusal" &&
						(parent.name == "prepareRefusalReport" ||
							parent.name == "intentArchiveRefusalReport")
					isTarget = isTarget || kind == "advisory" &&
						parent.name == "prepareAdvisoryReport"
					if isTarget {
						domain := program.resolveAssignmentPosition(
							node, typed, index, parameters,
						)
						resolvedDomain = &domain
					}
				}
			}
			if expression == nil && resolvedDomain == nil {
				return true
			}
			domain := s6NewEmissionDomain()
			if resolvedDomain != nil {
				domain = *resolvedDomain
			} else {
				domain = program.resolveExpression(
					node, expression, parameters, map[string]bool{},
				)
			}
			if domain.unknown {
				values := make([]string, 0, len(domain.values))
				for value := range domain.values {
					values = append(values, value)
				}
				sort.Strings(values)
				scanErr = fmt.Errorf(
					"%s:%s has unresolved reachable public %s code (resolved=%v)",
					node.rel, node.function.Name.Name, kind, values,
				)
				return false
			}
			for value := range domain.values {
				if value == "" {
					continue
				}
				if kind == "refusal" && !domain.direct[value] &&
					program.forwardedInternalCodeIsMapped(value) {
					continue
				}
				seen[value] = true
			}
			return true
		})
		if scanErr != nil {
			return nil, scanErr
		}
	}
	codes := make([]string, 0, len(seen))
	for code := range seen {
		codes = append(codes, code)
	}
	sort.Strings(codes)
	return codes, nil
}

func s6FunctionLiteralMayEmit(literal *ast.FuncLit, kind string) bool {
	found := false
	ast.Inspect(literal.Body, func(node ast.Node) bool {
		if found {
			return false
		}
		switch typed := node.(type) {
		case *ast.CallExpr:
			name := s6CallName(typed)
			if kind == "advisory" && name == "prepareAdvisory" {
				found = true
			}
			if kind == "refusal" &&
				(name == "refusePrepare" || name == "intentArchiveSimpleRefusal") {
				found = true
			}
		case *ast.CompositeLit:
			name := s6CompositeTypeName(typed.Type)
			if kind == "advisory" && name == "prepareAdvisoryReport" {
				found = true
			}
			if kind == "refusal" &&
				(name == "prepareRefusalReport" || name == "intentArchiveRefusalReport") {
				found = true
			}
		case *ast.AssignStmt:
			for _, lhs := range typed.Lhs {
				if selector, ok := lhs.(*ast.SelectorExpr); ok &&
					selector.Sel.Name == "Code" {
					found = true
				}
			}
		}
		return !found
	})
	return found
}

func (program *s6EmissionProgram) forwardedInternalCodeIsMapped(code string) bool {
	names := map[string]bool{}
	for key, value := range program.constants {
		if value == code {
			names[key[strings.LastIndex(key, ".")+1:]] = true
		}
	}
	if len(names) == 0 {
		return false
	}
	references := func(node ast.Node) bool {
		found := false
		ast.Inspect(node, func(raw ast.Node) bool {
			switch typed := raw.(type) {
			case *ast.Ident:
				found = found || names[typed.Name]
			case *ast.SelectorExpr:
				found = found || names[typed.Sel.Name]
			}
			return !found
		})
		return found
	}
	codeShape := regexp.MustCompile(`^[a-z][a-z0-9]*(?:-[a-z0-9]+)+$`)
	for key := range program.reachable {
		node := program.functions[key]
		mapped := false
		hasMappedAssignment := func(body ast.Node) bool {
			found := false
			ast.Inspect(body, func(raw ast.Node) bool {
				assignment, ok := raw.(*ast.AssignStmt)
				if !ok {
					return true
				}
				for index, expression := range assignment.Rhs {
					if index >= len(assignment.Lhs) {
						continue
					}
					if _, ok := assignment.Lhs[index].(*ast.Ident); !ok {
						continue
					}
					domain := program.resolveExpression(
						node, expression, program.domains[key], map[string]bool{},
					)
					for value := range domain.direct {
						if value != code && codeShape.MatchString(value) {
							found = true
							return false
						}
					}
				}
				return !found
			})
			return found
		}
		ast.Inspect(node.function.Body, func(raw ast.Node) bool {
			switch typed := raw.(type) {
			case *ast.IfStmt:
				if references(typed.Cond) && hasMappedAssignment(typed.Body) {
					mapped = true
					return false
				}
			case *ast.CaseClause:
				for _, expression := range typed.List {
					if references(expression) && hasMappedAssignment(typed) {
						mapped = true
						return false
					}
				}
			}
			return !mapped
		})
		if mapped {
			return true
		}
	}
	return false
}

func s6RefusalEmissionCodesFromSources(sources map[string]string) ([]string, error) {
	program, err := s6BuildEmissionProgram(sources)
	if err != nil {
		return nil, err
	}
	return program.emissionCodes("refusal")
}

func validateS6Refusals(
	expected []string,
	catalog []string,
	evidence map[string]s6RefusalFixture,
) error {
	if len(expected) != 53 {
		return fmt.Errorf("refusal catalog has %d codes, want 53", len(expected))
	}
	if !reflect.DeepEqual(catalog, expected) {
		return fmt.Errorf("refusal catalog = %v, want ordered %v", catalog, expected)
	}
	seen := map[string]bool{}
	for _, code := range catalog {
		if seen[code] {
			return fmt.Errorf("duplicate refusal code %q", code)
		}
		seen[code] = true
		item, ok := evidence[code]
		if !ok || item.fixture == "" {
			return fmt.Errorf("refusal code %q has no reachable named fixture", code)
		}
		if item.emittedCode != code {
			return fmt.Errorf("refusal fixture %q emitted code %q", code, item.emittedCode)
		}
		if item.expectedExit != s6ExpectedRefusalExit(code) ||
			item.exit != item.expectedExit {
			return fmt.Errorf(
				"refusal fixture %q exit=%d expected=%d contract=%d",
				code, item.exit, item.expectedExit, s6ExpectedRefusalExit(code),
			)
		}
		if strings.TrimSpace(item.relatedObject) == "" {
			return fmt.Errorf("refusal code %q has no observed related report object", code)
		}
		if strings.TrimSpace(item.remediation) == "" {
			return fmt.Errorf("refusal code %q has empty remediation", code)
		}
		if regexp.MustCompile(`<[^>]+>`).MatchString(item.remediation) {
			return fmt.Errorf("refusal code %q remediation is not self-contained: %q", code, item.remediation)
		}
		startsWithAction := regexp.MustCompile(`(?i)^(?:Use|Run|Move|Fix|Wait|Repair|Restore|Stop|Complete|For|Follow|Remove|Resume|Retry|Upgrade|Inspect|Preserve|Configure|Correct|Warning)\b`).
			MatchString(item.remediation)
		containsConcreteCommand := regexp.MustCompile(`(?i)\brun (?:tpatch|git|rm|cp)\b`).
			MatchString(item.remediation)
		if !startsWithAction && !containsConcreteCommand {
			return fmt.Errorf("refusal code %q remediation is not executable guidance: %q", code, item.remediation)
		}
	}
	for code := range evidence {
		if !seen[code] {
			return fmt.Errorf("extra refusal code %q is outside the closed catalog", code)
		}
	}
	return nil
}

func s6RefusalGuard(t *testing.T) error {
	catalog, evidence, err := s6RefusalEvidence(t)
	if err != nil {
		return err
	}
	return validateS6Refusals(catalog, catalog, evidence)
}

func s6CallName(call *ast.CallExpr) string {
	switch called := call.Fun.(type) {
	case *ast.Ident:
		return called.Name
	case *ast.SelectorExpr:
		return called.Sel.Name
	default:
		return ""
	}
}

func s6IsPredeclaredBuiltinCall(
	call *ast.CallExpr,
	name string,
	analyzer *s6FlowAnalyzer,
) bool {
	identifier, ok := call.Fun.(*ast.Ident)
	if !ok || identifier.Name != name || identifier.Obj != nil {
		return false
	}
	if _, builtin := types.Universe.Lookup(name).(*types.Builtin); !builtin {
		return false
	}
	if analyzer == nil || analyzer.model == nil {
		return true
	}
	key := analyzer.pkg + "." + name
	if len(analyzer.model.functionDecls[key]) != 0 ||
		analyzer.model.globalTypes[key].valid() ||
		analyzer.model.declaredTypes[key] ||
		analyzer.imports[name] != "" {
		return false
	}
	return true
}

func s6NormativeDocuments(t *testing.T) string {
	t.Helper()
	return strings.Join([]string{
		s6RepoFile(t, "docs/prds/PRD-prepare-intent-bundle.md"),
		s6RepoFile(t, "docs/adrs/ADR-035-intent-bundle-publication-and-history.md"),
	}, "\n")
}

func validateS6Citations(body string) error {
	rowRE := regexp.MustCompile(`(?m)^\| (PIB-[0-9]{3}) \|`)
	citationRE := regexp.MustCompile(`\bPIB-[0-9]{3,4}\b`)
	rows := map[string]bool{}
	for _, row := range rowRE.FindAllStringSubmatch(body, -1) {
		rows[row[1]] = true
	}
	for _, citation := range citationRE.FindAllString(body, -1) {
		if !rows[citation] {
			return fmt.Errorf("prose citation %s does not resolve to a matrix row", citation)
		}
	}
	return nil
}

func s6CitationGuard(t *testing.T) error {
	return validateS6Citations(s6NormativeDocuments(t))
}

