func validateS6LedgerFixture(source, packageName, testName, subtest string) error {
	fileset := token.NewFileSet()
	file, err := parser.ParseFile(fileset, "fixture_test.go", source, 0)
	if err != nil {
		return err
	}
	return resolveS6LedgerTarget([]*ast.File{file}, packageName, testName, subtest)
}

func resolveS6LedgerTarget(files []*ast.File, packageName, testName, subtest string) error {
	for _, file := range files {
		if file.Name.Name != packageName {
			continue
		}
		testingAliases := map[string]bool{}
		for _, imported := range file.Imports {
			pathValue, err := strconv.Unquote(imported.Path.Value)
			if err != nil || pathValue != "testing" {
				continue
			}
			alias := "testing"
			if imported.Name != nil {
				alias = imported.Name.Name
			}
			if alias != "_" && alias != "." {
				testingAliases[alias] = true
			}
		}
		for _, declaration := range file.Decls {
			function, ok := declaration.(*ast.FuncDecl)
			if !ok || function.Recv != nil || function.Name.Name != testName ||
				function.Type.Results != nil || function.Body == nil {
				continue
			}
			if function.Type.Params == nil || len(function.Type.Params.List) != 1 {
				return fmt.Errorf("%s has the wrong signature", testName)
			}
			parameter := function.Type.Params.List[0]
			if len(parameter.Names) != 1 {
				return fmt.Errorf("%s must bind exactly one testing receiver", testName)
			}
			pointer, ok := parameter.Type.(*ast.StarExpr)
			if !ok {
				return fmt.Errorf("%s parameter is not *testing.T", testName)
			}
			selector, ok := pointer.X.(*ast.SelectorExpr)
			if !ok || selector.Sel.Name != "T" {
				return fmt.Errorf("%s parameter is not *testing.T", testName)
			}
			alias, ok := selector.X.(*ast.Ident)
			if !ok || !testingAliases[alias.Name] {
				return fmt.Errorf("%s parameter uses the wrong testing package", testName)
			}
			receiver := parameter.Names[0]
			if receiver.Obj == nil {
				return fmt.Errorf("%s testing receiver has no bound object", testName)
			}
			found := subtest == ""
			ast.Inspect(function.Body, func(node ast.Node) bool {
				typed, ok := node.(*ast.CallExpr)
				if !ok || len(typed.Args) == 0 {
					return true
				}
				selected, ok := typed.Fun.(*ast.SelectorExpr)
				if !ok || selected.Sel.Name != "Run" {
					return true
				}
				actualReceiver, ok := selected.X.(*ast.Ident)
				if !ok || actualReceiver.Obj != receiver.Obj {
					return true
				}
				literal, ok := typed.Args[0].(*ast.BasicLit)
				if !ok || literal.Kind != token.STRING {
					return true
				}
				value, err := strconv.Unquote(literal.Value)
				if err == nil && value == subtest {
					found = true
				}
				return true
			})
			if !found {
				return fmt.Errorf("%s lacks literal subtest %q on its outer testing receiver", testName, subtest)
			}
			return nil
		}
	}
	return fmt.Errorf("package %s test %s was not resolved", packageName, testName)
}

func parseS6PackageTests(t *testing.T, dir string) ([]*ast.File, error) {
	t.Helper()
	fullDir := filepath.Join(avpRepoRoot(t), filepath.FromSlash(dir))
	entries, err := os.ReadDir(fullDir)
	if err != nil {
		return nil, err
	}
	fileset := token.NewFileSet()
	var files []*ast.File
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), "_test.go") {
			continue
		}
		file, err := parser.ParseFile(fileset, filepath.Join(fullDir, entry.Name()), nil, 0)
		if err != nil {
			return nil, err
		}
		files = append(files, file)
	}
	return files, nil
}

func validateS6Ledger(t *testing.T, ledger []s6LedgerRow) error {
	expectedIDs := []string{
		"PIB-148", "PIB-149", "PIB-150", "PIB-151", "PIB-152", "PIB-153",
		"PIB-154", "PIB-155", "PIB-156", "PIB-157", "PIB-158", "PIB-159",
		"PIB-215", "PIB-216", "PIB-217", "PIB-218", "PIB-219", "PIB-220",
		"PIB-224", "PIB-225", "PIB-226", "PIB-227", "PIB-228", "PIB-229",
		"PIB-230", "PIB-231", "PIB-232", "PIB-388", "PIB-389", "PIB-390", "PIB-391",
	}
	expectedKinds := []string{
		"U", "U", "U", "U", "I", "I", "S", "G", "I", "C", "G", "G",
		"G", "G", "G", "G", "G", "G",
		"G", "G", "G", "G", "G", "G", "G", "G", "G", "G", "G", "G", "G",
	}
	if len(ledger) != len(expectedIDs) {
		return fmt.Errorf("S6 ledger has %d rows, want 31", len(ledger))
	}
	cache := map[string][]*ast.File{}
	for index, row := range ledger {
		if row.id != expectedIDs[index] {
			return fmt.Errorf("S6 ledger row %d = %s, want %s", index, row.id, expectedIDs[index])
		}
		if row.kind != expectedKinds[index] {
			return fmt.Errorf("%s kind = %s, want %s", row.id, row.kind, expectedKinds[index])
		}
		if len(row.targets) == 0 {
			return fmt.Errorf("%s has no runnable target", row.id)
		}
		for _, target := range row.targets {
			files, ok := cache[target.dir]
			if !ok {
				var err error
				files, err = parseS6PackageTests(t, target.dir)
				if err != nil {
					return err
				}
				cache[target.dir] = files
			}
			if err := resolveS6LedgerTarget(files, target.packageName, target.test, target.subtest); err != nil {
				return fmt.Errorf("%s target %s/%s/%s: %w",
					row.id, target.dir, target.test, target.subtest, err)
			}
		}
	}
	return nil
}

func s6LedgerGuard(t *testing.T) error {
	if err := validateS6Ledger(t, s6AcceptanceLedger()); err != nil {
		return err
	}
	fixtures := []struct {
		name   string
		source string
		pkg    string
		test   string
		sub    string
	}{
		{"comment", "package cli\n// func TestFake(t *testing.T) { t.Run(\"PIB-230\", nil) }\n", "cli", "TestFake", "PIB-230"},
		{"string", "package cli\nconst fake = `func TestFake(t *testing.T) { t.Run(\"PIB-230\", nil) }`\n", "cli", "TestFake", "PIB-230"},
		{"wrong-package", "package other\nimport \"testing\"\nfunc TestFake(t *testing.T) { t.Run(\"PIB-230\", func(t *testing.T){}) }\n", "cli", "TestFake", "PIB-230"},
		{"wrong-signature", "package cli\nfunc TestFake(t string) {}\n", "cli", "TestFake", "PIB-230"},
		{"wrong-receiver", "package cli\nimport \"testing\"\nfunc TestFake(t *testing.T) { other := t; other.Run(\"PIB-230\", func(t *testing.T){}) }\n", "cli", "TestFake", "PIB-230"},
		{"nonliteral", "package cli\nimport \"testing\"\nfunc TestFake(t *testing.T) { name := \"PIB-230\"; t.Run(name, func(t *testing.T){}) }\n", "cli", "TestFake", "PIB-230"},
		{"nested-function-shadow", "package cli\nimport \"testing\"\nfunc TestFake(t *testing.T) { func(t *testing.T) { t.Run(\"PIB-230\", func(t *testing.T){}) }(t) }\n", "cli", "TestFake", "PIB-230"},
		{"local-shadow", "package cli\nimport \"testing\"\nfunc TestFake(t *testing.T) { { t := struct{ Run func(string, func(*testing.T)) }{}; t.Run(\"PIB-230\", func(t *testing.T){}) } }\n", "cli", "TestFake", "PIB-230"},
	}
	for _, fixture := range fixtures {
		if err := validateS6LedgerFixture(fixture.source, fixture.pkg, fixture.test, fixture.sub); err == nil {
			return fmt.Errorf("ledger resolver accepted %s fixture", fixture.name)
		}
	}
	if err := validateS6LedgerFixture(
		"package cli\nimport \"testing\"\nfunc TestFake(t *testing.T) { t.Run(\"PIB-230\", func(t *testing.T){}) }\n",
		"cli", "TestFake", "PIB-230",
	); err != nil {
		return fmt.Errorf("ledger resolver rejected valid literal fixture: %w", err)
	}
	renameTargets := []string{
		"PIB-148-final-symlink",
		"PIB-149-final-directory",
		"PIB-151-artifacts-symlink",
	}
	for _, missing := range renameTargets {
		var siblings strings.Builder
		siblings.WriteString("package intentpub\nimport \"testing\"\nfunc TestPIB148PIB149PIB151RenameFinalGate(t *testing.T) {\n")
		for _, candidate := range renameTargets {
			if candidate != missing {
				fmt.Fprintf(&siblings, "\tt.Run(%q, func(t *testing.T){})\n", candidate)
			}
		}
		siblings.WriteString("}\n")
		if err := validateS6LedgerFixture(
			siblings.String(), "intentpub",
			"TestPIB148PIB149PIB151RenameFinalGate", missing,
		); err == nil {
			return fmt.Errorf("ledger resolver accepted missing rename case %s while siblings remained", missing)
		}
	}
	return nil
}

func s6GuardIDsFromLedger() []string {
	var ids []string
	for _, row := range s6AcceptanceLedger() {
		if strings.Contains(row.kind, "G") {
			ids = append(ids, row.id)
		}
	}
	return ids
}

func validateS6SensitivityMeta(t *testing.T, guards map[string]s6GuardSpec) error {
	t.Helper()
	guardIDs := s6GuardIDsFromLedger()
	if len(guardIDs) != 22 {
		return fmt.Errorf("S6 ledger declares %d G rows, want 22", len(guardIDs))
	}
	if len(guards) != len(guardIDs) {
		return fmt.Errorf("S6 guard meta-table has %d rows, want %d", len(guards), len(guardIDs))
	}
	fixtures := map[string]string{}
	for _, id := range guardIDs {
		spec, ok := guards[id]
		if !ok {
			return fmt.Errorf("S6 guard meta-table is missing %s", id)
		}
		if spec.run == nil || spec.sensitivity == nil || strings.TrimSpace(spec.fixture) == "" {
			return fmt.Errorf("%s lacks a validator or sensitivity fixture", id)
		}
		if prior := fixtures[spec.fixture]; prior != "" {
			return fmt.Errorf("%s and %s share sensitivity fixture %q", prior, id, spec.fixture)
		}
		fixtures[spec.fixture] = id
		if id != "PIB-231" {
			if err := spec.run(t); err != nil {
				return fmt.Errorf("%s baseline validator failed before mutation: %w", id, err)
			}
		} else if len(guards) != len(guardIDs) {
			return errors.New("PIB-231 baseline meta-validator rejected the complete guard set")
		}
		if err := spec.sensitivity(t); err == nil {
			return fmt.Errorf("%s sensitivity fixture %q did not fail its validator", id, spec.fixture)
		}
	}
	for id := range guards {
		if !containsS6String(guardIDs, id) {
			return fmt.Errorf("S6 guard meta-table has unexpected row %s", id)
		}
	}
	return nil
}

func s6SensitivityMetaGuard(t *testing.T) error {
	return validateS6SensitivityMeta(t, s6GuardSpecs)
}

func containsS6String(values []string, wanted string) bool {
	for _, value := range values {
		if value == wanted {
			return true
		}
	}
	return false
}

