func validateS6InjectionObservations(observed map[string]injectionSeamObservation) error {
	if len(prepareInjectionSeamRegistry) != 37 {
		return fmt.Errorf("injection registry has %d seams, want 37", len(prepareInjectionSeamRegistry))
	}
	for name, specification := range prepareInjectionSeamRegistry {
		item := observed[name]
		if item.declarations != 1 ||
			item.calls == 0 ||
			item.assignments != 0 ||
			item.initialized ||
			item.owner != specification.owner ||
			item.signature != specification.signature {
			return fmt.Errorf(
				"%s = %+v, want owner=%s signature=%s one nil declaration, callpoint, no assignment",
				name, item, specification.owner, specification.signature,
			)
		}
	}
	for name := range observed {
		if _, ok := prepareInjectionSeamRegistry[name]; !ok {
			return fmt.Errorf("unregistered injection seam %s", name)
		}
	}
	return nil
}

