func validateS6RedactionMessage(message, matchedSource string) error {
	if matchedSource == "" {
		return errors.New("redaction sensitivity requires a matched source substring")
	}
	if strings.Contains(message, matchedSource) {
		return errors.New("redaction message echoes the matched source substring")
	}
	return nil
}

func s6RedactionGuard(t *testing.T) error {
	root, slug := prepareS4Workspace(t, "S6 redaction message")
	prepareS4WriteReadyBundle(t, root, slug, false)
	raw := "Authorization: Bearer " + strings.Repeat("x", 24)
	spec := filepath.Join(root, ".tpatch", "features", slug, "spec.md")
	if err := os.WriteFile(spec, []byte(raw+"\n"), 0o644); err != nil {
		return err
	}
	code, stdout, stderr, _ := runPrepare(
		t, "--path", root, "prepare", slug, "--regenerate", "--allow-heuristic", "--json", "--quiet",
	)
	if code != 3 {
		return fmt.Errorf("redaction fixture exit = %d, want 3; stdout=%q stderr=%q", code, stdout, stderr)
	}
	var report preparePublishReport
	if err := json.Unmarshal([]byte(stdout), &report); err != nil {
		return err
	}
	if report.Refusal == nil || report.Refusal.Code != "archive-content-refused-sensitive" {
		return fmt.Errorf("redaction fixture report = %#v", report)
	}
	return validateS6RedactionMessage(stdout+stderr, raw)
}

func validateS6ArchiveHistory(skills map[string]string) error {
	positive := []*regexp.Regexp{
		regexp.MustCompile(`(?i)\b(?:use|treat) (?:the )?intent archive as (?:a )?(?:general )?history\b`),
		regexp.MustCompile(`(?i)\bintent archive (?:is|provides) (?:a )?(?:general )?(?:history|undo)\b`),
		regexp.MustCompile(`(?i)\barchive-backed undo\b`),
	}
	for rel, body := range skills {
		if !strings.Contains(body, "it is not a general history or undo facility") {
			return fmt.Errorf("%s lacks the archive history/undo limit", rel)
		}
		if !strings.Contains(body, "Deleting a committed blob from the current tree does not rewrite Git history") {
			return fmt.Errorf("%s lacks the committed-history caveat", rel)
		}
		for _, re := range positive {
			if match := re.FindString(body); match != "" {
				return fmt.Errorf("%s presents archive as history/undo: %q", rel, match)
			}
		}
	}
	return nil
}

func s6ArchiveHistoryGuard(t *testing.T) error {
	return validateS6ArchiveHistory(s6SkillBodies(t))
}

func validateS6ProviderRequirement(skills map[string]string) error {
	required := "`--regenerate` requires a configured successful provider unless explicit `--allow-heuristic` is passed."
	contradiction := regexp.MustCompile(`(?i)--regenerate.{0,80}(?:silently|automatically).{0,30}heuristic`)
	for rel, body := range skills {
		if strings.Count(body, required) != 1 {
			return fmt.Errorf("%s must carry exactly one provider requirement", rel)
		}
		if match := contradiction.FindString(body); match != "" {
			return fmt.Errorf("%s contradicts provider requirement: %q", rel, match)
		}
	}
	return nil
}

func s6ProviderRequirementGuard(t *testing.T) error {
	return validateS6ProviderRequirement(s6SkillBodies(t))
}

func validateS6GoldenProvenance(acknowledgement, expected string, settings map[string]string) error {
	const frozen = "cacaaf867ebde100b699e20d76010f92316afc72"
	if prepareCheckBaseline != frozen || acceptedRoutingTip != frozen {
		return fmt.Errorf(
			"frozen prepare provenance = baseline %s routing tip %s, want %s",
			prepareCheckBaseline, acceptedRoutingTip, frozen,
		)
	}
	if expected != frozen {
		return fmt.Errorf("expected provenance %s, want frozen %s", expected, frozen)
	}
	if err := validatePreparePIBProducerEvidence(acknowledgement, expected, settings); err != nil {
		return err
	}
	if err := validatePreparePIBComparisonInputs("", ""); err != nil {
		return err
	}
	if err := validatePrepareCheckFixtureOrdering([]string{
		"docs/handoff/CURRENT.md",
		"internal/cli/prepare_pib_golden_test.go",
	}); err != nil {
		return err
	}
	if err := validatePreparePIBComparisonInputs("baseline-binary", ""); err == nil {
		return errors.New("comparison mode accepted a phase baseline override")
	}
	if err := validatePreparePIBComparisonInputs("", "check-baseline-binary"); err == nil {
		return errors.New("comparison mode accepted a check baseline override")
	}
	if err := validatePrepareCheckFixtureOrdering([]string{"internal/cli/prepare_publish.go"}); err == nil {
		return errors.New("history ordering accepted mutating production before the fixtures")
	}
	return nil
}

