type s6TypeGraphImporter struct {
	builder *s6TypeGraphBuilder
}

func (typed *s6TypeGraphImporter) Import(path string) (*types.Package, error) {
	return typed.ImportFrom(path, "", 0)
}

func (typed *s6TypeGraphImporter) ImportFrom(
	path string,
	_ string,
	_ types.ImportMode,
) (*types.Package, error) {
	normalized, local := s6NormalizeModulePackage(path)
	if local {
		return typed.builder.checkPackage(normalized)
	}
	s6ExportImporterMu.Lock()
	defer s6ExportImporterMu.Unlock()
	return typed.builder.fallback.Import(path)
}

