func s6OnceCollectionDomainUnknown(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) bool {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6OnceCollectionDomainUnknown(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.SliceExpr:
		return s6OnceCollectionDomainUnknown(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.IndexExpr:
		return s6OnceCollectionDomainUnknown(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.CompositeLit:
		return false
	case *ast.CallExpr:
		return !s6IsPredeclaredBuiltinCall(typed, "make", analyzer)
	case *ast.Ident:
		key := s6IdentifierFlowKey(typed)
		if resolving[key] {
			return true
		}
		resolving[key] = true
		defer delete(resolving, key)
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 {
			if s6IsFunctionParameter(analyzer, typed) {
				return true
			}
			globalKey := analyzer.pkg + "." + typed.Name
			if s6IdentifierIsPackageGlobal(
				typed, analyzer.function, globalKey, analyzer.model,
			) {
				candidates = bindings.globalByKey[globalKey]
				if len(candidates) == 0 {
					candidates = s6GlobalInitialExpressions(
						analyzer.model, globalKey,
					)
				}
				if len(candidates) == 0 {
					return true
				}
			}
			return false
		}
		for _, candidate := range candidates {
			if s6OnceCollectionDomainUnknown(
				candidate, bindings, analyzer, resolving,
			) {
				return true
			}
		}
		return false
	case *ast.SelectorExpr:
		if key, modeled, external := s6ImportedGlobalKey(
			typed, analyzer.imports, analyzer.model,
		); modeled {
			candidates := bindings.globalByKey[key]
			if len(candidates) == 0 {
				candidates = s6GlobalInitialExpressions(analyzer.model, key)
			}
			return len(candidates) == 0
		} else if external {
			return true
		}
		values := s6LocalFieldExpressions(typed, bindings)
		if len(values) == 0 {
			return true
		}
		for _, value := range values {
			if s6OnceCollectionDomainUnknown(
				value, bindings, analyzer, resolving,
			) {
				return true
			}
		}
		return false
	default:
		return true
	}
}

func s6ApplyOnceMethodValueAssignments(
	bindings *s6ReachingBindings,
	lhs []ast.Expr,
	rhs []ast.Expr,
	analyzer *s6FlowAnalyzer,
) {
	if bindings == nil || analyzer == nil || analyzer.model == nil {
		return
	}
	for index, target := range lhs {
		identifier, ok := target.(*ast.Ident)
		if !ok {
			continue
		}
		var source ast.Expr
		switch {
		case len(rhs) == len(lhs) && index < len(rhs):
			source = rhs[index]
		case len(rhs) == 1 && len(lhs) == 1:
			source = rhs[0]
		default:
			continue
		}
		key := s6OnceMethodBindingKey(identifier, analyzer)
		method, matched := s6ResolveOnceMethodValue(
			source, bindings, analyzer, map[string]bool{},
		)
		if !matched {
			delete(bindings.onceMethods, key)
			continue
		}
		bindings.onceMethods[key] = method
	}
}

func s6ResolveOnceMethodValue(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) (s6OnceMethodValue, bool) {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6ResolveOnceMethodValue(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.SelectorExpr:
		if typed.Sel.Name != "Do" ||
			!s6ExpressionIsSyncOnce(typed.X, analyzer) {
			return s6OnceMethodValue{}, false
		}
		identities, unresolved := s6OnceIdentities(
			typed.X, bindings, analyzer, map[string]bool{},
		)
		return s6OnceMethodValue{
			identities: identities,
			unresolved: unresolved || len(identities) == 0,
		}, true
	case *ast.Ident:
		key := s6OnceMethodBindingKey(typed, analyzer)
		if method, ok := bindings.onceMethods[key]; ok {
			return s6CloneOnceMethodValue(method), true
		}
		flowKey := "once-method:" + s6IdentifierFlowKey(typed)
		if resolving[flowKey] {
			return s6OnceMethodValue{
				identities: map[string]bool{}, unresolved: true,
			}, true
		}
		resolving[flowKey] = true
		defer delete(resolving, flowKey)
		for _, candidate := range bindings.candidates(typed) {
			if method, ok := s6ResolveOnceMethodValue(
				candidate, bindings, analyzer, resolving,
			); ok {
				return method, true
			}
		}
	}
	return s6OnceMethodValue{}, false
}

func s6OnceMethodBindingKey(
	identifier *ast.Ident,
	analyzer *s6FlowAnalyzer,
) string {
	if analyzer != nil && analyzer.model != nil {
		globalKey := analyzer.pkg + "." + identifier.Name
		if s6IdentifierIsPackageGlobal(
			identifier, analyzer.function, globalKey, analyzer.model,
		) {
			return "global:" + globalKey
		}
	}
	return "local:" + s6IdentifierFlowKey(identifier)
}

func s6FreezeAppendResult(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) []ast.Expr {
	if call == nil || len(call.Args) == 0 ||
		analyzer == nil || analyzer.model == nil {
		if call != nil {
			return []ast.Expr{call}
		}
		return []ast.Expr{s6DeferredUnknown}
	}
	sources, sourceUnresolved := s6FreezeCollectionExpression(
		call.Args[0], bindings, analyzer, map[string]bool{},
	)
	if sourceUnresolved || len(sources) == 0 {
		s6FailClosedCollectionFreeze(bindings, analyzer, call.Args[0])
		return []ast.Expr{s6DeferredUnknown}
	}
	arguments := make([][]ast.Expr, len(call.Args)-1)
	for index, argument := range call.Args[1:] {
		var values []ast.Expr
		var unresolved bool
		if call.Ellipsis.IsValid() {
			values, unresolved = s6FreezeCollectionExpression(
				argument, bindings, analyzer, map[string]bool{},
			)
		} else {
			values, unresolved = s6FreezeAppendArgument(
				argument, bindings, analyzer, map[string]bool{},
			)
		}
		if unresolved || len(values) == 0 {
			s6FailClosedCollectionFreeze(bindings, analyzer, argument)
			return []ast.Expr{s6DeferredUnknown}
		}
		arguments[index] = values
	}
	results := make([]ast.Expr, 0, len(sources))
	for _, source := range sources {
		if s6AppendChainContainsPosition(source, call.Pos(), analyzer) {
			results = append(results, source)
			continue
		}
		frozen := *call
		frozen.Args = []ast.Expr{source}
		valid := true
		for _, values := range arguments {
			if len(values) != 1 {
				valid = false
				break
			}
			frozen.Args = append(frozen.Args, values[0])
		}
		if !valid {
			s6FailClosedCollectionFreeze(bindings, analyzer, call)
			return []ast.Expr{s6DeferredUnknown}
		}
		signature := fmt.Sprintf("%p|%s", call, s6StableExpressionKey(source))
		for _, argument := range frozen.Args[1:] {
			signature += "|" + s6StableExpressionKey(argument)
		}
		actual, _ := s6FrozenAppendCache.LoadOrStore(
			signature, ast.Expr(&frozen),
		)
		results = append(results, actual.(ast.Expr))
	}
	return results
}

func s6AppendChainContainsPosition(
	expression ast.Expr,
	position token.Pos,
	analyzer *s6FlowAnalyzer,
) bool {
	call, ok := expression.(*ast.CallExpr)
	if !ok || !s6IsPredeclaredBuiltinCall(call, "append", analyzer) {
		return false
	}
	if call.Pos() == position {
		return true
	}
	return len(call.Args) != 0 &&
		s6AppendChainContainsPosition(call.Args[0], position, analyzer)
}

func s6FreezeAppendArgument(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) ([]ast.Expr, bool) {
	values, unresolved := s6SnapshotDeferredExpression(
		expression, bindings, analyzer, resolving,
	)
	if !unresolved && len(values) != 0 {
		return values, false
	}
	candidates := []ast.Expr{expression}
	if identifier, ok := expression.(*ast.Ident); ok {
		if bound := bindings.candidates(identifier); len(bound) != 0 {
			candidates = bound
		}
	}
	var frozen []ast.Expr
	for _, candidate := range candidates {
		if _, ok := candidate.(*ast.CompositeLit); ok {
			frozen = s6AppendUniqueExpressions(frozen, candidate)
		}
	}
	if len(frozen) == 0 {
		switch expression.(type) {
		case *ast.Ident, *ast.SelectorExpr, *ast.IndexExpr, *ast.BinaryExpr:
			ref := s6ExpressionType(
				analyzer.pkg, analyzer.imports, expression,
				analyzer.locals, analyzer.model,
			)
			if !s6TypeContainsValueOnce(
				ref, analyzer.model, map[string]bool{},
			) {
				return []ast.Expr{expression}, false
			}
		}
		return values, true
	}
	return frozen, false
}

func s6FreezeCollectionExpression(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) ([]ast.Expr, bool) {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6FreezeCollectionExpression(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.Ident:
		key := "freeze-collection:" + s6IdentifierFlowKey(typed)
		if resolving[key] {
			return []ast.Expr{s6DeferredUnknown}, true
		}
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 {
			return []ast.Expr{typed}, s6IsFunctionParameter(analyzer, typed)
		}
		resolving[key] = true
		defer delete(resolving, key)
		var values []ast.Expr
		unresolved := false
		for _, candidate := range candidates {
			resolved, candidateUnresolved := s6FreezeCollectionExpression(
				candidate, bindings, analyzer, resolving,
			)
			values = s6AppendUniqueExpressions(values, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return values, unresolved
	case *ast.SelectorExpr:
		key := "freeze-selector:" + s6StableExpressionKey(typed)
		if resolving[key] {
			return []ast.Expr{s6DeferredUnknown}, true
		}
		resolving[key] = true
		defer delete(resolving, key)
		values, unresolved := s6FrozenCollectionFieldValues(
			typed.X, typed.Sel.Name, bindings, analyzer, resolving,
		)
		return s6FreezeCollectionCandidates(
			values, unresolved, bindings, analyzer, resolving,
		)
	case *ast.IndexExpr:
		key := "freeze-index:" + s6StableExpressionKey(typed)
		if resolving[key] {
			return []ast.Expr{s6DeferredUnknown}, true
		}
		resolving[key] = true
		defer delete(resolving, key)
		indices, indexUnresolved := s6SnapshotDeferredExpression(
			typed.Index, bindings, analyzer, resolving,
		)
		values, valueUnresolved := s6CollectionIndexValues(
			typed.X, indices, bindings, analyzer, resolving,
		)
		return s6FreezeCollectionCandidates(
			values, indexUnresolved || valueUnresolved,
			bindings, analyzer, resolving,
		)
	case *ast.SliceExpr:
		sources, unresolved := s6FreezeCollectionExpression(
			typed.X, bindings, analyzer, resolving,
		)
		var values []ast.Expr
		for _, source := range sources {
			if s6SliceChainContainsExpression(source, typed) {
				values = append(values, source)
				continue
			}
			key := struct {
				slice  *ast.SliceExpr
				source string
			}{slice: typed, source: s6StableExpressionKey(source)}
			frozen := ast.Expr(&ast.SliceExpr{
				X: source, Low: typed.Low, High: typed.High,
				Max: typed.Max, Slice3: typed.Slice3,
			})
			actual, _ := s6FrozenSliceCache.LoadOrStore(key, frozen)
			values = append(values, actual.(ast.Expr))
		}
		return values, unresolved || len(values) == 0
	case *ast.UnaryExpr:
		if typed.Op == token.MUL {
			values, unresolved := s6CollectionDereferenceValues(
				typed.X, bindings, analyzer, resolving,
			)
			return s6FreezeCollectionCandidates(
				values, unresolved, bindings, analyzer, resolving,
			)
		}
	case *ast.TypeAssertExpr:
		return s6FreezeCollectionExpression(
			typed.X, bindings, analyzer, resolving,
		)
	default:
		return []ast.Expr{expression}, false
	}
	return []ast.Expr{s6DeferredUnknown}, true
}

func s6SliceChainContainsExpression(
	expression ast.Expr,
	target *ast.SliceExpr,
) bool {
	for {
		slice, ok := expression.(*ast.SliceExpr)
		if !ok {
			return false
		}
		if slice.Pos() == target.Pos() && slice.End() == target.End() {
			return true
		}
		expression = slice.X
	}
}

func s6FreezeCollectionCandidates(
	candidates []ast.Expr,
	unresolved bool,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) ([]ast.Expr, bool) {
	var values []ast.Expr
	for _, candidate := range candidates {
		resolved, candidateUnresolved := s6FreezeCollectionExpression(
			candidate, bindings, analyzer, resolving,
		)
		values = s6AppendUniqueExpressions(values, resolved...)
		unresolved = unresolved || candidateUnresolved
	}
	if len(values) == 0 {
		return []ast.Expr{s6DeferredUnknown}, true
	}
	return values, unresolved
}

func s6FrozenCollectionFieldValues(
	base ast.Expr,
	field string,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) ([]ast.Expr, bool) {
	switch typed := base.(type) {
	case *ast.ParenExpr:
		return s6FrozenCollectionFieldValues(
			typed.X, field, bindings, analyzer, resolving,
		)
	case *ast.UnaryExpr:
		if typed.Op == token.AND || typed.Op == token.MUL {
			return s6FrozenCollectionFieldValues(
				typed.X, field, bindings, analyzer, resolving,
			)
		}
	case *ast.TypeAssertExpr:
		return s6FrozenCollectionFieldValues(
			typed.X, field, bindings, analyzer, resolving,
		)
	case *ast.Ident:
		key := "collection-field:" + s6IdentifierFlowKey(typed) + "." + field
		if resolving[key] {
			return nil, true
		}
		resolving[key] = true
		defer delete(resolving, key)
		direct := bindings.fieldCandidates(typed, field)
		if len(direct) != 0 {
			return direct, false
		}
		if s6IsFunctionParameter(analyzer, typed) &&
			analyzer != nil && analyzer.model != nil {
			baseRef := analyzer.model.resolveAlias(
				s6ExpressionType(
					analyzer.pkg, analyzer.imports, typed,
					analyzer.locals, analyzer.model,
				),
			)
			fieldRef := analyzer.model.instantiateType(
				baseRef, analyzer.model.fields[baseRef.key()][field],
			)
			if baseRef.pointerDepth == 0 {
				ranged, _, ok := analyzer.model.rangeType(fieldRef)
				if ok &&
					(ranged.containerKind == "slice" ||
						ranged.containerKind == "map") &&
					!s6TypeContainsValueOnce(
						fieldRef, analyzer.model, map[string]bool{},
					) {
					return []ast.Expr{s6UnknownCollection}, false
				}
			}
		}
		var values []ast.Expr
		unresolved := false
		for _, candidate := range bindings.candidates(typed) {
			resolved, candidateUnresolved := s6FrozenCollectionFieldValues(
				candidate, field, bindings, analyzer, resolving,
			)
			values = s6AppendUniqueExpressions(values, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return values, unresolved || len(values) == 0
	case *ast.CompositeLit:
		for _, raw := range typed.Elts {
			item, ok := raw.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			name, ok := item.Key.(*ast.Ident)
			if ok && name.Name == field {
				return []ast.Expr{item.Value}, false
			}
		}
		if analyzer != nil && analyzer.model != nil {
			ref := analyzer.model.resolveAlias(
				s6TypeRefFromExpression(
					analyzer.pkg, analyzer.imports, typed.Type,
				),
			)
			fieldRef := analyzer.model.instantiateType(
				ref, analyzer.model.fields[ref.key()][field],
			)
			if ranged, _, ok := analyzer.model.rangeType(fieldRef); ok &&
				(ranged.containerKind == "slice" ||
					ranged.containerKind == "map") {
				return []ast.Expr{s6NilExpression}, false
			}
		}
	case *ast.SelectorExpr:
		parents, unresolved := s6FrozenCollectionFieldValues(
			typed.X, typed.Sel.Name, bindings, analyzer, resolving,
		)
		var values []ast.Expr
		for _, parent := range parents {
			resolved, candidateUnresolved := s6FrozenCollectionFieldValues(
				parent, field, bindings, analyzer, resolving,
			)
			values = s6AppendUniqueExpressions(values, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return values, unresolved || len(values) == 0
	case *ast.IndexExpr:
		indices, indexUnresolved := s6SnapshotDeferredExpression(
			typed.Index, bindings, analyzer, resolving,
		)
		parents, parentUnresolved := s6CollectionIndexValues(
			typed.X, indices, bindings, analyzer, resolving,
		)
		var values []ast.Expr
		unresolved := parentUnresolved
		if indexUnresolved {
			ref := s6ExpressionType(
				analyzer.pkg, analyzer.imports, typed.X,
				analyzer.locals, analyzer.model,
			)
			ranged, _, ok := analyzer.model.rangeType(ref)
			unresolved = unresolved ||
				!ok || ranged.containerKind != "map"
		}
		for _, parent := range parents {
			resolved, candidateUnresolved := s6FrozenCollectionFieldValues(
				parent, field, bindings, analyzer, resolving,
			)
			values = s6AppendUniqueExpressions(values, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return values, unresolved || len(values) == 0
	case *ast.CallExpr:
		parents, unresolved := s6SnapshotDeferredCallResult(
			typed, bindings, analyzer, resolving,
		)
		var values []ast.Expr
		for _, parent := range parents {
			resolved, candidateUnresolved := s6FrozenCollectionFieldValues(
				parent, field, bindings, analyzer, resolving,
			)
			values = s6AppendUniqueExpressions(values, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		if unresolved && analyzer != nil &&
			analyzer.model != nil {
			resultRef := analyzer.model.resolveAlias(s6ExpressionType(
				analyzer.pkg, analyzer.imports, typed,
				analyzer.locals, analyzer.model,
			))
			fieldRef := analyzer.model.instantiateType(
				resultRef, analyzer.model.fields[resultRef.key()][field],
			)
			if ranged, _, ok := analyzer.model.rangeType(fieldRef); ok &&
				(ranged.containerKind == "slice" ||
					ranged.containerKind == "map") &&
				!s6TypeContainsValueOnce(
					fieldRef, analyzer.model, map[string]bool{},
				) {
				filtered := values[:0]
				for _, value := range values {
					if value != s6DeferredUnknown {
						filtered = append(filtered, value)
					}
				}
				return s6AppendUniqueExpressions(
					filtered, s6UnknownCollection,
				), false
			}
		}
		return values, unresolved || len(values) == 0
	}
	return nil, true
}

func s6CollectionIndexValues(
	collection ast.Expr,
	indices []ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) ([]ast.Expr, bool) {
	switch typed := collection.(type) {
	case *ast.ParenExpr:
		return s6CollectionIndexValues(
			typed.X, indices, bindings, analyzer, resolving,
		)
	case *ast.Ident:
		key := "collection-index:" + s6IdentifierFlowKey(typed)
		if resolving[key] {
			return nil, true
		}
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 {
			return nil, true
		}
		unknownIndex := s6DeferredIndexDomainUnknown(indices)
		var overrides []ast.Expr
		for _, candidate := range candidates {
			literal, ok := candidate.(*ast.CompositeLit)
			if !ok || !s6IsIndexedEntryExpression(literal) {
				continue
			}
			item := literal.Elts[0].(*ast.KeyValueExpr)
			if unknownIndex || s6DeferredIndexMatches(item.Key, indices) {
				overrides = append(overrides, candidate)
			}
		}
		if len(overrides) != 0 {
			candidates = overrides
		}
		resolving[key] = true
		defer delete(resolving, key)
		var values []ast.Expr
		unresolved := false
		for _, candidate := range candidates {
			resolved, candidateUnresolved := s6CollectionIndexValues(
				candidate, indices, bindings, analyzer, resolving,
			)
			values = s6AppendUniqueExpressions(values, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return values, unresolved || len(values) == 0
	case *ast.SelectorExpr:
		collections, unresolved := s6FreezeCollectionExpression(
			typed, bindings, analyzer, resolving,
		)
		var values []ast.Expr
		for _, candidate := range collections {
			resolved, candidateUnresolved := s6CollectionIndexValues(
				candidate, indices, bindings, analyzer, resolving,
			)
			values = s6AppendUniqueExpressions(values, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return values, unresolved || len(values) == 0
	case *ast.SliceExpr:
		low := 0
		if typed.Low != nil {
			lows, known := s6StaticInts(
				typed.Low, bindings, map[string]bool{},
			)
			if !known || len(lows) != 1 {
				return nil, true
			}
			low = lows[0]
		}
		var translated []ast.Expr
		for _, index := range indices {
			values, known := s6StaticInts(
				index, bindings, map[string]bool{},
			)
			if !known {
				return nil, true
			}
			for _, value := range values {
				translated = append(
					translated, s6RangeIndexExpression(low+value),
				)
			}
		}
		return s6CollectionIndexValues(
			typed.X, translated, bindings, analyzer, resolving,
		)
	case *ast.CompositeLit:
		var values []ast.Expr
		unresolved := false
		mapLiteral := false
		if _, mapLiteral = typed.Type.(*ast.MapType); mapLiteral {
			unknownIndex := s6DeferredIndexDomainUnknown(indices)
			for _, raw := range typed.Elts {
				item, ok := raw.(*ast.KeyValueExpr)
				if !ok {
					unresolved = true
					continue
				}
				if unknownIndex || s6DeferredIndexMatches(item.Key, indices) {
					values = s6AppendUniqueExpressions(values, item.Value)
				}
			}
			return values, unresolved || len(values) == 0
		}
		for position, raw := range typed.Elts {
			value := raw
			index := ast.Expr(s6RangeIndexExpression(position))
			if item, ok := raw.(*ast.KeyValueExpr); ok {
				index = item.Key
				value = item.Value
			}
			if s6DeferredIndexMatches(index, indices) {
				values = s6AppendUniqueExpressions(values, value)
			}
		}
		return values, len(values) == 0
	case *ast.CallExpr:
		if s6IsPredeclaredBuiltinCall(typed, "make", analyzer) &&
			len(typed.Args) != 0 {
			if mapping, ok := typed.Args[0].(*ast.MapType); ok {
				zero := ast.Expr(&ast.CompositeLit{Type: mapping.Value})
				actual, _ := s6ZeroMapElementCache.LoadOrStore(
					typed, zero,
				)
				return []ast.Expr{actual.(ast.Expr)}, false
			}
		}
		return nil, true
	default:
		values, unresolved := s6SnapshotDeferredIndex(
			collection, indices, bindings, analyzer, resolving,
		)
		return values, unresolved || len(values) == 0
	}
}

func s6DeferredIndexDomainUnknown(indices []ast.Expr) bool {
	if len(indices) == 0 {
		return true
	}
	for _, index := range indices {
		if s6DeferredScalarValue(index) == "" {
			return true
		}
	}
	return false
}

func s6CollectionDereferenceValues(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) ([]ast.Expr, bool) {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6CollectionDereferenceValues(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.Ident:
		key := "collection-deref:" + s6IdentifierFlowKey(typed)
		if resolving[key] {
			return nil, true
		}
		resolving[key] = true
		defer delete(resolving, key)
		var values []ast.Expr
		unresolved := false
		for _, candidate := range bindings.candidates(typed) {
			resolved, candidateUnresolved := s6CollectionDereferenceValues(
				candidate, bindings, analyzer, resolving,
			)
			values = s6AppendUniqueExpressions(values, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return values, unresolved || len(values) == 0
	case *ast.UnaryExpr:
		if typed.Op == token.AND {
			return []ast.Expr{typed.X}, false
		}
	case *ast.TypeAssertExpr:
		return s6CollectionDereferenceValues(
			typed.X, bindings, analyzer, resolving,
		)
	}
	return nil, true
}

func s6FailClosedCollectionFreeze(
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	expressions ...ast.Expr,
) {
	if bindings != nil && bindings.analysisErr == nil &&
		s6AnalyzerHasGuardedState(analyzer) {
		position := token.NoPos
		if len(expressions) != 0 && expressions[0] != nil {
			position = expressions[0].Pos()
		}
		bindings.analysisErr = fmt.Errorf(
			"collection pre-assignment snapshot is unresolved in guarded flow at %d",
			position,
		)
	}
}

func s6StableExpressionKey(expression ast.Expr) string {
	if expression == nil {
		return "<nil>"
	}
	cacheable := expression.Pos().IsValid()
	if cacheable {
		if cached, ok := s6StableExprKeyCache.Load(expression); ok {
			return cached.(string)
		}
	}
	var formatted bytes.Buffer
	if err := format.Node(&formatted, token.NewFileSet(), expression); err != nil {
		return fmt.Sprintf("%T:%d:%d", expression, expression.Pos(), expression.End())
	}
	identity := strings.Builder{}
	ast.Inspect(expression, func(node ast.Node) bool {
		if node == nil {
			return true
		}
		fmt.Fprintf(
			&identity, "|%T:%d:%d", node, node.Pos(), node.End(),
		)
		if identifier, ok := node.(*ast.Ident); ok && identifier.Obj != nil {
			fmt.Fprintf(&identity, ":%p", identifier.Obj)
		}
		return true
	})
	key := fmt.Sprintf(
		"%T:%s%s", expression, formatted.String(), identity.String(),
	)
	if !cacheable {
		return key
	}
	actual, _ := s6StableExprKeyCache.LoadOrStore(expression, key)
	return actual.(string)
}

func TestS6StableExpressionKeyCacheSensitivity(t *testing.T) {
	parse := func(source string) ast.Expr {
		t.Helper()
		expression, err := parser.ParseExpr(source)
		if err != nil {
			t.Fatal(err)
		}
		return expression
	}
	expression := parse("1 + 2")
	equivalent := parse("1 + 2")
	different := parse("1 - 2")
	key := s6StableExpressionKey(expression)
	if got := s6StableExpressionKey(equivalent); got != key {
		t.Fatalf("equivalent expression key = %q, want %q", got, key)
	}
	if got := s6StableExpressionKey(different); got == key {
		t.Fatalf("different expression reused key %q", got)
	}

	const sentinel = "stable-expression-cache-hit"
	s6StableExprKeyCache.Store(expression, sentinel)
	t.Cleanup(func() {
		s6StableExprKeyCache.Delete(expression)
		s6StableExprKeyCache.Delete(equivalent)
		s6StableExprKeyCache.Delete(different)
	})
	if got := s6StableExpressionKey(expression); got != sentinel {
		t.Fatalf("cached expression key = %q, want %q", got, sentinel)
	}

	transient := ast.NewIdent("transient")
	_ = s6StableExpressionKey(transient)
	if _, cached := s6StableExprKeyCache.Load(transient); cached {
		t.Fatal("positionless expression was retained in the stable-key cache")
	}
}

func s6AppendAssignmentNeedsFreeze(
	call *ast.CallExpr,
	assignment *ast.AssignStmt,
	rhsIndex int,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	if call == nil || len(call.Args) == 0 ||
		assignment == nil || analyzer == nil || analyzer.model == nil {
		return false
	}
	var targets []ast.Expr
	switch {
	case len(assignment.Rhs) == len(assignment.Lhs) &&
		rhsIndex < len(assignment.Lhs):
		targets = []ast.Expr{assignment.Lhs[rhsIndex]}
	case len(assignment.Rhs) == 1:
		targets = assignment.Lhs
	}
	sourceIdentities, sourceUnresolved := s6BackingIdentities(
		call.Args[0], bindings, analyzer, map[string]bool{},
	)
	for _, target := range targets {
		if s6SameStorageExpression(target, call.Args[0]) {
			return true
		}
		targetIdentifier, targetOK := target.(*ast.Ident)
		sourceIdentifier, sourceOK := call.Args[0].(*ast.Ident)
		if targetOK && sourceOK &&
			(targetIdentifier.Obj != nil &&
				targetIdentifier.Obj == sourceIdentifier.Obj ||
				targetIdentifier.Obj == nil &&
					targetIdentifier.Name == sourceIdentifier.Name) {
			return true
		}
		targetIdentities, targetUnresolved := s6BackingIdentities(
			target, bindings, analyzer, map[string]bool{},
		)
		if s6BackingSetsIntersect(targetIdentities, sourceIdentities) {
			return true
		}
		if sourceUnresolved && targetUnresolved && targetOK {
			return true
		}
	}
	return false
}

func s6SameStorageExpression(left, right ast.Expr) bool {
	switch typed := left.(type) {
	case *ast.ParenExpr:
		return s6SameStorageExpression(typed.X, right)
	case *ast.Ident:
		other, ok := right.(*ast.Ident)
		if !ok {
			return false
		}
		if typed.Obj != nil || other.Obj != nil {
			return typed.Obj != nil && typed.Obj == other.Obj
		}
		return typed.Name == other.Name
	case *ast.SelectorExpr:
		other, ok := right.(*ast.SelectorExpr)
		return ok && typed.Sel.Name == other.Sel.Name &&
			s6SameStorageExpression(typed.X, other.X)
	case *ast.IndexExpr:
		other, ok := right.(*ast.IndexExpr)
		return ok && s6SameStorageExpression(typed.X, other.X) &&
			s6OnceIndexIdentity(typed.Index) != "" &&
			s6OnceIndexIdentity(typed.Index) == s6OnceIndexIdentity(other.Index)
	case *ast.SliceExpr:
		other, ok := right.(*ast.SliceExpr)
		return ok && s6SameStorageExpression(typed.X, other.X) &&
			typed.Low == other.Low && typed.High == other.High &&
			typed.Max == other.Max && typed.Slice3 == other.Slice3
	}
	if parenthesized, ok := right.(*ast.ParenExpr); ok {
		return s6SameStorageExpression(left, parenthesized.X)
	}
	return left == right
}

func s6ApplyBindingAssignment(
	bindings *s6ReachingBindings,
	assignment *ast.AssignStmt,
	analyzers ...*s6FlowAnalyzer,
) {
	var analyzer *s6FlowAnalyzer
	if len(analyzers) != 0 {
		analyzer = analyzers[0]
	}
	s6ApplyOnceMethodValueAssignments(
		bindings, assignment.Lhs, assignment.Rhs, analyzer,
	)
	merge := assignment.Tok != token.ASSIGN && assignment.Tok != token.DEFINE
	var receiveValues, receiveOK []ast.Expr
	receiveAssignment := false
	if len(assignment.Rhs) == 1 {
		if receive, ok := assignment.Rhs[0].(*ast.UnaryExpr); ok &&
			receive.Op == token.ARROW {
			receiveAssignment = true
			s6RejectUsedOnceChannelReceive(
				receive.X, bindings, analyzer,
			)
			receiveValues, receiveOK = s6ChannelReceiveValues(
				receive.X, bindings, analyzer,
			)
		}
	}
	if !receiveAssignment {
		s6ApplyOnceAssignmentCopies(
			bindings, assignment.Lhs, assignment.Rhs, analyzer,
		)
	}
	rhsValues := make([][]ast.Expr, len(assignment.Rhs))
	for index, expression := range assignment.Rhs {
		rhsValues[index] = []ast.Expr{expression}
		if s6ExpressionHasSharedBacking(expression, analyzer) {
			var unresolved bool
			rhsValues[index], unresolved = s6FreezeCollectionExpression(
				expression, bindings, analyzer, map[string]bool{},
			)
			if unresolved {
				s6FailClosedCollectionFreeze(bindings, analyzer, expression)
			}
		}
		if call, ok := expression.(*ast.CallExpr); ok &&
			s6IsPredeclaredBuiltinCall(call, "append", analyzer) &&
			s6AppendAssignmentNeedsFreeze(
				call, assignment, index, bindings, analyzer,
			) {
			rhsValues[index] = s6FreezeAppendResult(
				call, bindings, analyzer,
			)
		}
	}
	for index, lhs := range assignment.Lhs {
		var values []ast.Expr
		if receiveValues != nil {
			if index == 0 {
				values = receiveValues
			} else {
				values = receiveOK
			}
		}
		switch {
		case len(values) != 0:
		case len(assignment.Rhs) == len(assignment.Lhs) && index < len(assignment.Rhs):
			values = rhsValues[index]
		case len(assignment.Rhs) == 1:
			values = rhsValues[0]
		default:
			continue
		}
		switch target := lhs.(type) {
		case *ast.Ident:
			s6SetReachingBinding(bindings, target, values, merge)
			if analyzer != nil && analyzer.model != nil {
				key := analyzer.pkg + "." + target.Name
				if s6IdentifierIsPackageGlobal(
					target, analyzer.function, key, analyzer.model,
				) {
					s6SetReachingGlobal(bindings, key, values, merge)
					aliases := map[string]bool{}
					for _, value := range values {
						for alias := range s6GlobalAliasReferences(
							value, key, analyzer.pkg, analyzer.imports,
							analyzer.function, bindings, analyzer.model,
						) {
							aliases[alias] = true
						}
					}
					s6SetGlobalAliases(bindings, key, aliases, merge)
				}
			}
			if len(assignment.Rhs) == 1 && len(assignment.Lhs) > 1 {
				if call, ok := assignment.Rhs[0].(*ast.CallExpr); ok {
					tuple := s6TupleCallPosition{call: call, position: index}
					if merge {
						bindings.tupleByName[target.Name] =
							s6AppendUniqueTuplePositions(
								bindings.tupleByName[target.Name], tuple,
							)
						if target.Obj != nil {
							bindings.tupleByObj[target.Obj] =
								s6AppendUniqueTuplePositions(
									bindings.tupleByObj[target.Obj], tuple,
								)
						}
					} else {
						bindings.tupleByName[target.Name] =
							[]s6TupleCallPosition{tuple}
						if target.Obj != nil {
							bindings.tupleByObj[target.Obj] =
								[]s6TupleCallPosition{tuple}
						}
					}
				}
			}
		case *ast.StarExpr:
			if !s6AssignThroughPointer(
				bindings, target.X, values, merge, map[string]bool{}, analyzer,
			) && analyzer != nil && analyzer.model != nil &&
				bindings.analysisErr == nil {
				bindings.analysisErr = errors.New(
					"indirect assignment target is unresolved",
				)
			}
		case *ast.SelectorExpr:
			if analyzer != nil && analyzer.model != nil {
				if key, modeled, external := s6ImportedGlobalKey(
					target, analyzer.imports, analyzer.model,
				); modeled {
					s6SetReachingGlobal(bindings, key, values, merge)
					aliases := map[string]bool{}
					for _, value := range values {
						for alias := range s6GlobalAliasReferences(
							value, key, analyzer.pkg, analyzer.imports,
							analyzer.function, bindings, analyzer.model,
						) {
							aliases[alias] = true
						}
					}
					s6SetGlobalAliases(bindings, key, aliases, merge)
					continue
				} else if external && bindings.analysisErr == nil {
					bindings.analysisErr = errors.New(
						"write to imported mutable global is unresolved",
					)
					continue
				}
			}
			if base, ok := target.X.(*ast.Ident); ok {
				s6SetReachingField(bindings, base, target.Sel.Name, values, merge)
				if analyzer != nil && analyzer.model != nil {
					key := analyzer.pkg + "." + base.Name
					if s6IdentifierIsPackageGlobal(
						base, analyzer.function, key, analyzer.model,
					) {
						s6SetReachingGlobal(bindings, key, values, true)
						aliases := map[string]bool{}
						for _, value := range values {
							for alias := range s6GlobalAliasReferences(
								value, key, analyzer.pkg, analyzer.imports,
								analyzer.function, bindings, analyzer.model,
							) {
								aliases[alias] = true
							}
						}
						s6SetGlobalAliases(bindings, key, aliases, true)
					}
				}
			}
		case *ast.IndexExpr:
			propagated := false
			if analyzer != nil {
				propagated = s6PropagateBackingWrite(
					bindings, target, values, analyzer,
				)
			}
			if !propagated {
				if base, ok := target.X.(*ast.Ident); ok {
					entries := make([]ast.Expr, 0, len(values))
					for _, value := range values {
						entries = append(
							entries, s6IndexedEntryExpression(target, value),
						)
					}
					replaced := s6ReplaceIndexedEntries(
						bindings.candidates(base), target.Index, entries,
					)
					s6SetReachingBinding(bindings, base, replaced, false)
					if analyzer != nil && analyzer.model != nil {
						key := analyzer.pkg + "." + base.Name
						if s6IdentifierIsPackageGlobal(
							base, analyzer.function, key, analyzer.model,
						) {
							s6SetReachingGlobal(bindings, key, entries, true)
							aliases := map[string]bool{}
							for _, value := range values {
								for alias := range s6GlobalAliasReferences(
									value, key, analyzer.pkg, analyzer.imports,
									analyzer.function, bindings, analyzer.model,
								) {
									aliases[alias] = true
								}
							}
							s6SetGlobalAliases(bindings, key, aliases, true)
						}
					}
				}
			}
		}
	}
}

func s6PropagateBackingWrite(
	bindings *s6ReachingBindings,
	target *ast.IndexExpr,
	values []ast.Expr,
	analyzer *s6FlowAnalyzer,
) bool {
	identities, unresolved := s6BackingIdentities(
		target.X, bindings, analyzer, map[string]bool{},
	)
	if len(identities) == 0 {
		if unresolved && analyzer != nil && analyzer.goroutineContext &&
			bindings.analysisErr == nil {
			bindings.analysisErr = errors.New(
				"collection backing identity is unresolved",
			)
		}
		return false
	}
	entries := make([]ast.Expr, 0, len(values))
	for _, value := range values {
		entries = append(entries, s6IndexedEntryExpression(target, value))
	}
	matched := false
	if analyzer != nil && analyzer.model != nil {
		if key, global := s6GlobalExpressionKey(
			target.X, analyzer.pkg, analyzer.imports,
			analyzer.function, analyzer.model,
		); global {
			aliases := s6ExpandGlobalAliasSet(
				map[string]bool{key: true}, bindings, analyzer.model,
			)
			for alias := range aliases {
				matched = true
				bindings.globalByKey[alias] = s6ReplaceIndexedEntries(
					bindings.globalByKey[alias], target.Index, entries,
				)
			}
		}
	}
	for object, candidates := range bindings.byObject {
		backings, candidateUnresolved := s6StorageIdentitiesForBinding(
			object, candidates, bindings, analyzer,
		)
		if candidateUnresolved {
			backings[s6UnknownBacking] = true
		}
		if !s6BackingSetsIntersect(identities, backings) {
			continue
		}
		matched = true
		bindings.byObject[object] = s6ReplaceIndexedEntries(
			bindings.byObject[object], target.Index, entries,
		)
		if object != nil {
			bindings.byName[object.Name] = s6ReplaceIndexedEntries(
				bindings.byName[object.Name], target.Index, entries,
			)
		}
	}
	for name, candidates := range bindings.byName {
		backings, candidateUnresolved := s6BackingIdentitiesFromValues(
			candidates, bindings, analyzer, map[string]bool{},
		)
		if candidateUnresolved {
			backings[s6UnknownBacking] = true
		}
		if s6BackingSetsIntersect(identities, backings) {
			matched = true
			bindings.byName[name] = s6ReplaceIndexedEntries(
				bindings.byName[name], target.Index, entries,
			)
		}
	}
	for key, candidates := range bindings.globalByKey {
		backings, candidateUnresolved := s6BackingIdentitiesFromValues(
			candidates, bindings, analyzer, map[string]bool{},
		)
		if candidateUnresolved {
			backings[s6UnknownBacking] = true
		}
		if !s6BackingSetsIntersect(identities, backings) {
			continue
		}
		matched = true
		bindings.globalByKey[key] = s6ReplaceIndexedEntries(
			bindings.globalByKey[key], target.Index, entries,
		)
		aliases := map[string]bool{}
		for _, value := range values {
			for alias := range s6GlobalAliasReferences(
				value, key, analyzer.pkg, analyzer.imports,
				analyzer.function, bindings, analyzer.model,
			) {
				aliases[alias] = true
			}
		}
		s6SetGlobalAliases(bindings, key, aliases, true)
	}
	for object, fields := range bindings.fieldsByObj {
		for field, candidates := range fields {
			backings, candidateUnresolved := s6BackingIdentitiesFromValues(
				candidates, bindings, analyzer, map[string]bool{},
			)
			if candidateUnresolved {
				backings[s6UnknownBacking] = true
			}
			if !s6BackingSetsIntersect(identities, backings) {
				continue
			}
			matched = true
			bindings.fieldsByObj[object][field] = s6ReplaceIndexedEntries(
				bindings.fieldsByObj[object][field], target.Index, entries,
			)
			if object != nil {
				if bindings.fieldsByName[object.Name] == nil {
					bindings.fieldsByName[object.Name] = map[string][]ast.Expr{}
				}
				bindings.fieldsByName[object.Name][field] = s6ReplaceIndexedEntries(
					bindings.fieldsByName[object.Name][field],
					target.Index, entries,
				)
			}
		}
	}
	for name, fields := range bindings.fieldsByName {
		for field, candidates := range fields {
			backings, candidateUnresolved := s6BackingIdentitiesFromValues(
				candidates, bindings, analyzer, map[string]bool{},
			)
			if candidateUnresolved {
				backings[s6UnknownBacking] = true
			}
			if s6BackingSetsIntersect(identities, backings) {
				matched = true
				bindings.fieldsByName[name][field] = s6ReplaceIndexedEntries(
					bindings.fieldsByName[name][field],
					target.Index, entries,
				)
			}
		}
	}
	if unresolved && analyzer != nil && analyzer.goroutineContext &&
		bindings.analysisErr == nil {
		bindings.analysisErr = errors.New(
			"goroutine collection backing identity is unresolved",
		)
	}
	return matched
}

func s6StorageIdentitiesForBinding(
	object *ast.Object,
	values []ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) (map[ast.Node]bool, bool) {
	identities, unresolved := s6BackingIdentitiesFromValues(
		values, bindings, analyzer, map[string]bool{},
	)
	if object == nil || analyzer == nil || analyzer.model == nil {
		return identities, unresolved
	}
	ref := analyzer.model.resolveAlias(analyzer.locals[object.Name])
	ranged, _, ok := analyzer.model.rangeType(ref)
	if ok && ranged.containerKind == "array" {
		if declaration, ok := object.Decl.(ast.Node); ok {
			identities[declaration] = true
		}
	}
	return identities, unresolved
}

func s6AssignThroughPointer(
	bindings *s6ReachingBindings,
	expression ast.Expr,
	values []ast.Expr,
	merge bool,
	resolving map[string]bool,
	analyzers ...*s6FlowAnalyzer,
) bool {
	var analyzer *s6FlowAnalyzer
	if len(analyzers) != 0 {
		analyzer = analyzers[0]
	}
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6AssignThroughPointer(
			bindings, typed.X, values, merge, resolving, analyzer,
		)
	case *ast.UnaryExpr:
		if typed.Op != token.AND {
			return false
		}
		switch target := typed.X.(type) {
		case *ast.Ident:
			resolvedValues := s6ResolveAssignmentValues(
				values, bindings, map[string]bool{},
			)
			s6SetReachingBinding(
				bindings, target, resolvedValues, merge,
			)
			if analyzer != nil && analyzer.model != nil {
				key := analyzer.pkg + "." + target.Name
				if s6IdentifierIsPackageGlobal(
					target, analyzer.function, key, analyzer.model,
				) {
					s6SetReachingGlobal(bindings, key, resolvedValues, merge)
				}
			}
			return true
		case *ast.SelectorExpr:
			base, ok := target.X.(*ast.Ident)
			if !ok {
				return false
			}
			s6SetReachingField(
				bindings, base, target.Sel.Name,
				s6ResolveAssignmentValues(values, bindings, map[string]bool{}),
				merge,
			)
			return true
		case *ast.IndexExpr:
			base, ok := target.X.(*ast.Ident)
			if !ok {
				return false
			}
			entries := make([]ast.Expr, 0, len(values))
			for _, value := range values {
				entries = append(
					entries, s6IndexedEntryExpression(target, value),
				)
			}
			s6SetReachingBinding(bindings, base, entries, true)
			return true
		default:
			return false
		}
	case *ast.Ident:
		if resolving[typed.Name] {
			return false
		}
		resolving[typed.Name] = true
		defer delete(resolving, typed.Name)
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 && analyzer != nil && analyzer.model != nil {
			key := analyzer.pkg + "." + typed.Name
			if s6IdentifierIsPackageGlobal(
				typed, analyzer.function, key, analyzer.model,
			) {
				candidates = bindings.globalByKey[key]
			}
		}
		if len(candidates) == 0 {
			return false
		}
		resolved := false
		for _, candidate := range candidates {
			resolved = s6AssignThroughPointer(
				bindings, candidate, values, merge, resolving, analyzer,
			) || resolved
		}
		return resolved
	case *ast.SelectorExpr, *ast.IndexExpr, *ast.TypeAssertExpr, *ast.CallExpr:
		if analyzer == nil ||
			(!analyzer.goroutineContext &&
				!analyzer.recursiveExpressionContext) {
			return false
		}
		resolvedValues, unresolved := s6SnapshotDeferredExpression(
			expression, bindings, analyzer, map[string]bool{},
		)
		resolved := false
		for _, candidate := range resolvedValues {
			if candidate == expression || candidate == s6DeferredUnknown {
				continue
			}
			resolved = s6AssignThroughPointer(
				bindings, candidate, values, merge, resolving, analyzer,
			) || resolved
		}
		return resolved && !unresolved
	default:
		return false
	}
}

func s6ResolveAssignmentValues(
	values []ast.Expr,
	bindings *s6ReachingBindings,
	resolving map[string]bool,
) []ast.Expr {
	var result []ast.Expr
	for _, value := range values {
		switch typed := value.(type) {
		case *ast.StarExpr:
			pointers := s6ResolveAssignmentValues(
				[]ast.Expr{typed.X}, bindings, resolving,
			)
			resolved := false
			for _, pointer := range pointers {
				address, ok := pointer.(*ast.UnaryExpr)
				if !ok || address.Op != token.AND {
					continue
				}
				result = s6AppendUniqueExpressions(
					result,
					s6ResolveAssignmentValues(
						[]ast.Expr{address.X}, bindings, resolving,
					)...,
				)
				resolved = true
			}
			if !resolved {
				result = s6AppendUniqueExpressions(result, value)
			}
			continue
		case *ast.SelectorExpr:
			if base, ok := typed.X.(*ast.Ident); ok {
				candidates := bindings.fieldCandidates(base, typed.Sel.Name)
				if len(candidates) != 0 {
					result = s6AppendUniqueExpressions(
						result,
						s6ResolveAssignmentValues(candidates, bindings, resolving)...,
					)
					continue
				}
			}
			result = s6AppendUniqueExpressions(result, value)
			continue
		}
		identifier, ok := value.(*ast.Ident)
		if !ok || resolving[s6IdentifierFlowKey(identifier)] {
			result = s6AppendUniqueExpressions(result, value)
			continue
		}
		candidates := bindings.candidates(identifier)
		if len(candidates) == 0 {
			result = s6AppendUniqueExpressions(result, value)
			continue
		}
		key := s6IdentifierFlowKey(identifier)
		resolving[key] = true
		result = s6AppendUniqueExpressions(
			result,
			s6ResolveAssignmentValues(candidates, bindings, resolving)...,
		)
		delete(resolving, key)
	}
	return result
}

func s6ApplyBindingDecl(
	bindings *s6ReachingBindings,
	declaration *ast.DeclStmt,
	analyzers ...*s6FlowAnalyzer,
) {
	generic, ok := declaration.Decl.(*ast.GenDecl)
	if !ok {
		return
	}
	for _, raw := range generic.Specs {
		spec, ok := raw.(*ast.ValueSpec)
		if !ok {
			continue
		}
		var analyzer *s6FlowAnalyzer
		if len(analyzers) != 0 {
			analyzer = analyzers[0]
		}
		lhs := make([]ast.Expr, len(spec.Names))
		for index, name := range spec.Names {
			lhs[index] = name
		}
		s6ApplyOnceMethodValueAssignments(
			bindings, lhs, spec.Values, analyzer,
		)
		s6ApplyOnceAssignmentCopies(bindings, lhs, spec.Values, analyzer)
		for index, name := range spec.Names {
			if index < len(spec.Values) {
				s6SetReachingBinding(bindings, name, []ast.Expr{spec.Values[index]}, false)
			}
		}
	}
}

func s6BindingsThroughStatements(
	statements []ast.Stmt,
	before token.Pos,
	state *s6ReachingBindings,
	functions ...*ast.FuncDecl,
) (*s6ReachingBindings, bool) {
	analyzer := &s6FlowAnalyzer{target: before}
	if len(functions) != 0 {
		analyzer.function = functions[0]
	}
	result := analyzer.analyzeStatements(
		statements, []*s6FlowFrame{s6NewFlowFrame(state)},
	)
	if len(analyzer.observed) != 0 {
		return s6MergeReachingBindings(analyzer.observed...), true
	}
	var states []*s6ReachingBindings
	for _, frame := range result.normal {
		states = append(states, frame.bindings)
	}
	for _, transfer := range result.transfers {
		if transfer.kind == token.RETURN {
			states = append(states, transfer.frame.bindings)
		}
	}
	if len(states) == 0 {
		unreachable := s6NewReachingBindings()
		unreachable.reachable = false
		return unreachable, false
	}
	return s6MergeReachingBindings(states...), false
}

func s6BindingsInsideStatement(
	statement ast.Stmt,
	before token.Pos,
	state *s6ReachingBindings,
) (*s6ReachingBindings, bool) {
	switch typed := statement.(type) {
	case *ast.BlockStmt:
		return s6BindingsThroughStatements(typed.List, before, state)
	case *ast.IfStmt:
		current := s6CloneReachingBindings(state)
		if typed.Init != nil && before > typed.Init.End() {
			current, _ = s6BindingsAfterStatement(typed.Init, current)
		}
		if before >= typed.Body.Pos() && before <= typed.Body.End() {
			return s6BindingsThroughStatements(typed.Body.List, before, current)
		}
		if typed.Else != nil && before >= typed.Else.Pos() && before <= typed.Else.End() {
			return s6BindingsInsideStatement(typed.Else, before, current)
		}
		return current, true
	case *ast.ForStmt:
		current := s6CloneReachingBindings(state)
		if typed.Init != nil && before > typed.Init.End() {
			current, _ = s6BindingsAfterStatement(typed.Init, current)
		}
		if before >= typed.Body.Pos() && before <= typed.Body.End() {
			entry := s6LoopEntryFixedPoint(typed.Body.List, typed.Post, current)
			return s6BindingsThroughStatements(typed.Body.List, before, entry)
		}
		return current, true
	case *ast.RangeStmt:
		if before >= typed.Body.Pos() && before <= typed.Body.End() {
			entry := s6LoopEntryFixedPoint(typed.Body.List, nil, state)
			return s6BindingsThroughStatements(typed.Body.List, before, entry)
		}
		return state, true
	case *ast.SwitchStmt:
		current := s6CloneReachingBindings(state)
		if typed.Init != nil && before > typed.Init.End() {
			current, _ = s6BindingsAfterStatement(typed.Init, current)
		}
		return s6BindingsInsideCaseClauses(typed.Body.List, before, current)
	case *ast.TypeSwitchStmt:
		current := s6CloneReachingBindings(state)
		if typed.Init != nil && before > typed.Init.End() {
			current, _ = s6BindingsAfterStatement(typed.Init, current)
		}
		return s6BindingsInsideCaseClauses(typed.Body.List, before, current)
	case *ast.SelectStmt:
		return s6BindingsInsideCommClauses(typed.Body.List, before, state)
	case *ast.LabeledStmt:
		return s6BindingsInsideStatement(typed.Stmt, before, state)
	default:
		return state, true
	}
}

func s6BindingsInsideCaseClauses(
	statements []ast.Stmt,
	before token.Pos,
	state *s6ReachingBindings,
) (*s6ReachingBindings, bool) {
	var fallthroughState *s6ReachingBindings
	for _, statement := range statements {
		clause, ok := statement.(*ast.CaseClause)
		if !ok {
			continue
		}
		entry := state
		if fallthroughState != nil {
			entry = s6MergeReachingBindings(state, fallthroughState)
		}
		if before >= clause.Pos() && before <= clause.End() {
			return s6BindingsThroughStatements(clause.Body, before, entry)
		}
		branch, _ := s6BindingsThroughStatements(clause.Body, token.NoPos, entry)
		fallthroughState = nil
		if s6CaseFallsThrough(clause) {
			fallthroughState = branch
		}
	}
	return state, true
}

func s6CaseFallsThrough(clause *ast.CaseClause) bool {
	if clause == nil || len(clause.Body) == 0 {
		return false
	}
	branch, ok := clause.Body[len(clause.Body)-1].(*ast.BranchStmt)
	return ok && branch.Tok == token.FALLTHROUGH
}

func s6BindingsInsideCommClauses(
	statements []ast.Stmt,
	before token.Pos,
	state *s6ReachingBindings,
) (*s6ReachingBindings, bool) {
	for _, statement := range statements {
		clause, ok := statement.(*ast.CommClause)
		if ok && before >= clause.Pos() && before <= clause.End() {
			return s6BindingsThroughStatements(clause.Body, before, state)
		}
	}
	return state, true
}

func s6BindingsAfterStatement(
	statement ast.Stmt,
	state *s6ReachingBindings,
) (*s6ReachingBindings, bool) {
	analyzer := &s6FlowAnalyzer{}
	result := analyzer.analyzeStatement(statement, s6NewFlowFrame(state), "")
	var states []*s6ReachingBindings
	for _, frame := range result.normal {
		states = append(states, frame.bindings)
	}
	for _, transfer := range result.transfers {
		if transfer.kind == token.RETURN {
			states = append(states, transfer.frame.bindings)
		}
	}
	if len(states) == 0 {
		unreachable := s6NewReachingBindings()
		unreachable.reachable = false
		return unreachable, true
	}
	return s6MergeReachingBindings(states...), len(result.normal) == 0
}

func s6ApplyInvokedClosureEffects(
	expressions []ast.Expr,
	state *s6ReachingBindings,
	analyzers ...*s6FlowAnalyzer,
) *s6ReachingBindings {
	current := s6CloneReachingBindings(state)
	var analyzer *s6FlowAnalyzer
	if len(analyzers) != 0 {
		analyzer = analyzers[0]
	}
	for _, expression := range expressions {
		current = s6ApplyImmediateExpressionEffects(expression, current, analyzer)
		if current.panicking {
			break
		}
	}
	return current
}

func s6ApplyImmediateExpressionEffects(
	expression ast.Expr,
	state *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) *s6ReachingBindings {
	if state.panicking {
		return state
	}
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6ApplyImmediateExpressionEffects(typed.X, state, analyzer)
	case *ast.CallExpr:
		if s6IsPredeclaredBuiltinCall(typed, "recover", analyzer) &&
			len(typed.Args) == 0 {
			current := s6ApplyImmediateExpressionEffects(
				typed.Fun, state, analyzer,
			)
			if analyzer != nil && analyzer.deferredExecution &&
				s6HasUnrecoveredPanic(current) {
				current.panicRecovery &^= s6PanicUnrecovered
				current.panicRecovery |= s6PanicRecovered
			}
			return current
		}
		if s6IsPredeclaredBuiltinCall(typed, "panic", analyzer) &&
			len(typed.Args) == 1 {
			current := s6ApplyImmediateExpressionEffects(
				typed.Fun, state, analyzer,
			)
			current = s6ApplyImmediateExpressionEffects(
				typed.Args[0], current, analyzer,
			)
			s6StartPanic(current, typed)
			return current
		}
		if s6IsPredeclaredBuiltinCall(typed, "close", analyzer) &&
			len(typed.Args) == 1 {
			current := s6ApplyImmediateExpressionEffects(
				typed.Args[0], state, analyzer,
			)
			if current.panicking {
				return current
			}
			s6ApplyChannelClose(typed.Args[0], current, analyzer)
			return current
		}
		if s6IsPredeclaredBuiltinCall(typed, "copy", analyzer) &&
			len(typed.Args) == 2 {
			current := s6ApplyImmediateExpressionEffects(
				typed.Fun, state, analyzer,
			)
			for _, argument := range typed.Args {
				current = s6ApplyCallArgumentEffects(
					argument, current, analyzer,
				)
				if current.panicking {
					return current
				}
			}
			destinationWindow := s6OnceCollectionCopyWindow(
				typed.Args[0], current, analyzer,
			)
			sourceWindow := s6OnceCollectionCopyWindow(
				typed.Args[1], current, analyzer,
			)
			copyMaximum, copyMaximumKnown := s6CopyMaximumCount(
				destinationWindow, sourceWindow,
			)
			s6RejectUsedOnceCollectionWindow(
				typed.Args[0], copyMaximum, copyMaximumKnown,
				current, analyzer,
			)
			s6RejectUsedOnceCollectionWindow(
				typed.Args[1], copyMaximum, copyMaximumKnown,
				current, analyzer,
			)
			if current.analysisErr == nil {
				s6ApplyFreshOnceCollectionCopy(
					typed.Args[0], typed.Args[1],
					copyMaximum, copyMaximumKnown,
					current, analyzer,
				)
			}
			return current
		}
		if s6IsPredeclaredBuiltinCall(typed, "append", analyzer) &&
			len(typed.Args) >= 1 {
			current := s6ApplyImmediateExpressionEffects(
				typed.Fun, state, analyzer,
			)
			for _, argument := range typed.Args {
				current = s6ApplyCallArgumentEffects(
					argument, current, analyzer,
				)
				if current.panicking {
					return current
				}
			}
			_, allocate := s6AppendBackingPossibilities(
				typed, current, analyzer,
			)
			if allocate {
				s6RejectUsedOnceCollectionCopy(
					typed.Args[0], current, analyzer,
				)
			}
			if typed.Ellipsis.IsValid() && len(typed.Args) > 1 {
				s6RejectUsedOnceCollectionCopy(
					typed.Args[len(typed.Args)-1], current, analyzer,
				)
			}
			return current
		}
		if analyzer != nil && analyzer.ordinaryEffects &&
			s6CallName(typed) == "WithRoot" && len(typed.Args) == 1 {
			current := s6ApplyImmediateExpressionEffects(
				typed.Fun, state, analyzer,
			)
			return s6EvaluateImmediateCallEffects(
				&ast.CallExpr{
					Fun:  typed.Args[0],
					Args: []ast.Expr{s6DeferredUnknown},
				},
				current,
				analyzer,
			)
		}
		if onceState, onceCall := s6ApplySyncOnceDo(
			typed, state, analyzer,
		); onceCall {
			return onceState
		}
		if callbackState, callbackCall :=
			s6CheckOpaqueCallbackCall(typed, state, analyzer); callbackCall {
			return callbackState
		}
		if s6CallHasNoModeledBindingEffects(typed, analyzer) {
			current := s6ApplyImmediateExpressionEffects(
				typed.Fun, state, analyzer,
			)
			for _, argument := range typed.Args {
				current = s6ApplyCallArgumentEffects(
					argument, current, analyzer,
				)
			}
			return current
		}
		if s6IdentityMayMutate(s6CallIdentity{name: s6CallName(typed)}) {
			current := s6ApplyImmediateExpressionEffects(
				typed.Fun, state, analyzer,
			)
			for _, argument := range typed.Args {
				current = s6ApplyCallArgumentEffects(
					argument, current, analyzer,
				)
			}
			return current
		}
		if literals, unresolved := s6ResolveLocalFunctionLiterals(
			typed.Fun, state, map[string]bool{},
		); !unresolved && len(literals) != 0 {
			callAnalyzer := analyzer
			if analyzer != nil {
				clone := *analyzer
				clone.recursiveExpressionContext = true
				callAnalyzer = &clone
			}
			return s6EvaluateImmediateCallEffects(typed, state, callAnalyzer)
		}
		if local, unresolved := s6ResolvedLocalCall(
			typed, state, analyzer,
		); local && analyzer != nil && analyzer.ordinaryEffects {
			callEffects := s6CallMayHaveOrdinaryEffects(typed, state, analyzer)
			globalEffects := s6ResolvedCallGlobalEffects(typed, state, analyzer)
			globalRelevant := s6GlobalEffectsReachBindings(
				globalEffects, analyzer.reachableGlobals, state, analyzer.model,
			)
			if globalEffects.unresolved &&
				len(analyzer.reachableGlobals) != 0 {
				failed := s6CloneReachingBindings(state)
				failed.analysisErr = fmt.Errorf(
					"guarded global effects are unresolved: %s (%s)",
					s6CallName(typed),
					s6SortedBoolMapKey(globalEffects.unresolvedCalls),
				)
				return failed
			}
			if analyzer.initializerExpression ||
				callEffects && s6ResolvedCallMayMutate(
					typed, state, analyzer,
				) || globalRelevant ||
				s6ResolvedCallReturnsValueOnce(typed, state, analyzer) ||
				s6ResolvedCallMayPanic(typed, state, analyzer) {
				clone := *analyzer
				clone.recursiveExpressionContext = true
				evaluated := s6EvaluateImmediateCallEffects(typed, state, &clone)
				escaped := s6ExpandGlobalAliasSet(
					globalEffects.escapes, evaluated, analyzer.model,
				)
				reachable := s6ExpandGlobalAliasSet(
					analyzer.reachableGlobals, evaluated, analyzer.model,
				)
				for key := range escaped {
					if reachable[key] {
						s6SetReachingGlobal(
							evaluated, key,
							[]ast.Expr{ast.NewIdent("providerUnresolvedGlobalEscape")},
							true,
						)
					}
				}
				return evaluated
			}
		} else if unresolved && analyzer != nil && analyzer.goroutineContext &&
			s6GoroutineDynamicCallTouchesGuarded(typed, state, analyzer) {
			failed := s6CloneReachingBindings(state)
			failed.analysisErr = errors.New(
				"goroutine dynamic helper receives guarded alias",
			)
			return failed
		} else if unresolved && s6CallHasNoModeledBindingEffects(
			typed, analyzer,
		) {
			current := s6ApplyImmediateExpressionEffects(
				typed.Fun, state, analyzer,
			)
			for _, argument := range typed.Args {
				current = s6ApplyCallArgumentEffects(
					argument, current, analyzer,
				)
			}
			return current
		} else if unresolved && analyzer != nil &&
			!analyzer.goroutineContext &&
			analyzer.ordinaryEffects &&
			s6GuardedCallableIsLocal(typed, state, analyzer) &&
			(analyzer.recursiveExpressionContext ||
				s6CallMayHaveOrdinaryEffects(typed, state, analyzer)) {
			failed := s6CloneReachingBindings(state)
			failed.analysisErr = fmt.Errorf(
				"guarded expression callable is unresolved: %s",
				s6CallName(typed),
			)
			return failed
		}
		current := s6MarkEscapedChannelsFromCall(
			typed, state, analyzer,
		)
		current = s6ApplyImmediateExpressionEffects(typed.Fun, current, analyzer)
		for _, argument := range typed.Args {
			current = s6ApplyCallArgumentEffects(
				argument, current, analyzer,
			)
		}
		return current
	case *ast.BinaryExpr:
		if typed.Op == token.LAND || typed.Op == token.LOR {
			return s6ApplyShortCircuitExpressionEffects(typed, state, analyzer)
		}
		current := s6ApplyImmediateExpressionEffects(typed.X, state, analyzer)
		if current.panicking {
			return current
		}
		return s6ApplyImmediateExpressionEffects(typed.Y, current, analyzer)
	case *ast.UnaryExpr:
		return s6ApplyImmediateExpressionEffects(typed.X, state, analyzer)
	case *ast.SelectorExpr:
		return s6ApplyImmediateExpressionEffects(typed.X, state, analyzer)
	case *ast.IndexExpr:
		current := s6ApplyImmediateExpressionEffects(typed.X, state, analyzer)
		if current.panicking {
			return current
		}
		current = s6ApplyImmediateExpressionEffects(
			typed.Index, current, analyzer,
		)
		if current.panicking {
			return current
		}
		s6RejectUsedOnceValueCopy(typed.Index, current, analyzer)
		s6RejectUsedOnceMapLookupCopy(typed, current, analyzer)
		return current
	case *ast.SliceExpr:
		current := s6ApplyImmediateExpressionEffects(typed.X, state, analyzer)
		if current.panicking {
			return current
		}
		for _, bound := range []ast.Expr{typed.Low, typed.High, typed.Max} {
			if bound != nil {
				current = s6ApplyImmediateExpressionEffects(
					bound, current, analyzer,
				)
				if current.panicking {
					return current
				}
			}
		}

		return current
	case *ast.IndexListExpr:
		current := s6ApplyImmediateExpressionEffects(typed.X, state, analyzer)
		for _, index := range typed.Indices {
			current = s6ApplyImmediateExpressionEffects(index, current, analyzer)
			if current.panicking {
				return current
			}
		}
		return current
	case *ast.CompositeLit:
		current := state
		for _, raw := range typed.Elts {
			if item, ok := raw.(*ast.KeyValueExpr); ok {
				current = s6ApplyImmediateExpressionEffects(
					item.Key, current, analyzer,
				)
				if current.panicking {
					return current
				}
				s6RejectUsedOnceValueCopy(item.Key, current, analyzer)
				current = s6ApplyImmediateExpressionEffects(
					item.Value, current, analyzer,
				)
				if current.panicking {
					return current
				}
				s6RejectUsedOnceValueCopy(item.Value, current, analyzer)
				continue
			}
			current = s6ApplyImmediateExpressionEffects(raw, current, analyzer)
			if current.panicking {
				return current
			}
			s6RejectUsedOnceValueCopy(raw, current, analyzer)
		}
		return current
	case *ast.TypeAssertExpr:
		return s6ApplyImmediateExpressionEffects(typed.X, state, analyzer)
	case *ast.KeyValueExpr:
		current := s6ApplyImmediateExpressionEffects(typed.Key, state, analyzer)
		if current.panicking {
			return current
		}
		return s6ApplyImmediateExpressionEffects(typed.Value, current, analyzer)
	default:
		return state
	}
}

func s6ResolvedCallMayPanic(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	if call == nil || analyzer == nil || analyzer.model == nil {
		return false
	}
	identities, _ := s6ResolveCallableIdentitiesFromContext(
		call.Fun,
		s6CallableContext{
			pkg: analyzer.pkg, imports: analyzer.imports, locals: analyzer.locals,
			bindings: bindings, params: s6AnalyzerCallableParameters(analyzer),
			functionKey: analyzer.functionKey,
		},
		analyzer.model,
		map[string]bool{},
	)
	for _, identity := range identities {
		if s6CallableIdentityMayPanic(
			identity, analyzer.model, map[string]bool{},
		) {
			return true
		}
	}
	return false
}

func s6CallableIdentityMayPanic(
	identity s6CallIdentity,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) bool {
	if identity.name == "panic" && !identity.known {
		return true
	}
	key := identity.functionKey()
	if resolving[key] {
		return false
	}
	resolving[key] = true
	defer delete(resolving, key)
	nodes := []ast.Node{}
	if identity.literal != nil {
		nodes = append(nodes, identity.literal.Body)
	} else {
		for _, declaration := range model.functionDecls[key] {
			nodes = append(nodes, declaration.Body)
		}
	}
	for _, node := range nodes {
		var pkg string
		var imports map[string]string
		var locals map[string]s6TypeRef
		var declaration *ast.FuncDecl
		if identity.literal != nil {
			pkg = identity.pkg
		} else if declarations := model.functionDecls[key]; len(declarations) == 1 {
			declaration = declarations[0]
			pkg = model.functionPackages[declaration]
			imports = model.functionImports[declaration]
			locals = s6FunctionLocalTypes(
				pkg, model.functionFiles[declaration], declaration, model,
			)
		}
		builtinAnalyzer := &s6FlowAnalyzer{
			function: declaration, model: model, pkg: pkg,
			imports: imports, locals: locals, functionKey: key,
		}
		found := false
		ast.Inspect(node, func(node ast.Node) bool {
			if found {
				return false
			}
			if literal, ok := node.(*ast.FuncLit); ok &&
				literal != identity.literal {
				return false
			}
			call, ok := node.(*ast.CallExpr)
			if !ok {
				return true
			}
			if s6IsPredeclaredBuiltinCall(call, "panic", builtinAnalyzer) {
				found = true
				return false
			}
			called := s6ResolveCallIdentity(pkg, imports, call, locals, model)
			if called.known && s6CallableIdentityMayPanic(
				called, model, resolving,
			) {
				found = true
				return false
			}
			return true
		})
		if found {
			return true
		}
	}
	return false
}

func s6ResolvedCallReturnsValueOnce(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	if call == nil || analyzer == nil || analyzer.model == nil {
		return false
	}
	identities, _ := s6ResolveCallableIdentitiesFromContext(
		call.Fun,
		s6CallableContext{
			pkg: analyzer.pkg, imports: analyzer.imports, locals: analyzer.locals,
			bindings: bindings, params: s6AnalyzerCallableParameters(analyzer),
			functionKey: analyzer.functionKey,
		},
		analyzer.model,
		map[string]bool{},
	)
	for _, identity := range identities {
		if identity.literal != nil {
			if identity.literal.Type.Results == nil {
				continue
			}
			for _, result := range identity.literal.Type.Results.List {
				if s6TypeContainsValueOnce(
					s6TypeRefFromExpression(
						analyzer.pkg, analyzer.imports, result.Type,
					),
					analyzer.model,
					map[string]bool{},
				) {
					return true
				}
			}
			continue
		}
		for _, result := range analyzer.model.functionResultLists[identity.functionKey()] {
			if s6TypeContainsValueOnce(
				result, analyzer.model, map[string]bool{},
			) {
				return true
			}
		}
	}
	return false
}

func s6ApplyCallArgumentEffects(
	expression ast.Expr,
	state *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) *s6ReachingBindings {
	current := s6ApplyImmediateExpressionEffects(expression, state, analyzer)
	if !current.panicking {
		s6RejectUsedOnceValueCopy(expression, current, analyzer)
	}
	return current
}

func s6ApplySyncOnceDo(
	call *ast.CallExpr,
	state *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) (*s6ReachingBindings, bool) {
	receivers, frozenIdentities, callbackIndex, matched, callableUnresolved :=
		s6OnceDoCallInfo(call, state, analyzer)
	if !matched {
		return state, false
	}
	current := s6ApplyImmediateExpressionEffects(call.Fun, state, analyzer)
	if current.panicking {
		return current, true
	}
	identities := map[string]bool{}
	for identity := range frozenIdentities {
		identities[identity] = true
	}
	identityUnresolved := callableUnresolved
	if callbackIndex != 1 {
		for _, receiver := range receivers {
			resolved, unresolved := s6OnceIdentities(
				receiver, current, analyzer, map[string]bool{},
			)
			for identity := range resolved {
				identities[identity] = true
			}
			identityUnresolved = identityUnresolved || unresolved
		}
	}
	argumentDomains := make([][]ast.Expr, len(call.Args))
	argumentUnresolved := make([]bool, len(call.Args))
	for index, argument := range call.Args {
		current, argumentDomains[index], argumentUnresolved[index] =
			s6EvaluateDeferredExpression(argument, current, analyzer)
		if current.panicking {
			return current, true
		}
		s6RejectUsedOnceValueCopy(argument, current, analyzer)
	}
	if callbackIndex == 1 && len(argumentDomains) != 0 {
		for _, receiver := range argumentDomains[0] {
			resolved, unresolved := s6OnceIdentities(
				receiver, current, analyzer, map[string]bool{},
			)
			for identity := range resolved {
				identities[identity] = true
			}
			identityUnresolved = identityUnresolved || unresolved
		}
		identityUnresolved = identityUnresolved || argumentUnresolved[0]
	}
	if len(identities) != 1 || identityUnresolved {
		if s6AnalyzerHasGuardedState(analyzer) {
			failed := s6CloneReachingBindings(current)
			failed.analysisErr = errors.New(
				"sync.Once receiver reaching guarded flow is unresolved",
			)
			return failed, true
		}
		return current, true
	}
	status := s6OnceNotDone
	first := true
	for identity := range identities {
		candidate := current.onceStates[identity]
		if first {
			status = candidate
			first = false
		} else if status != candidate {
			status = s6OnceUnknown
		}
	}
	setDone := func(bindings *s6ReachingBindings) {
		for identity := range identities {
			bindings.onceStates[identity] = s6OnceDone
		}
	}
	if status == s6OnceDone {
		setDone(current)
		return current, true
	}
	if callbackIndex < 0 || callbackIndex >= len(argumentDomains) ||
		argumentUnresolved[callbackIndex] ||
		len(argumentDomains[callbackIndex]) == 0 {
		failed := s6CloneReachingBindings(current)
		if s6AnalyzerHasGuardedState(analyzer) {
			failed.analysisErr = errors.New(
				"sync.Once callback reaching guarded flow is unresolved",
			)
		}
		setDone(failed)
		return failed, true
	}
	executed := s6ExecuteOnceCallbacks(
		argumentDomains[callbackIndex], current, analyzer,
	)
	setDone(executed)
	if status == s6OnceNotDone {
		return executed, true
	}
	skipped := s6CloneReachingBindings(current)
	setDone(skipped)
	return s6MergeExpressionAlternatives(skipped, executed), true
}

func s6ExecuteOnceCallbacks(
	callbacks []ast.Expr,
	state *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) *s6ReachingBindings {
	var states []*s6ReachingBindings
	for _, callback := range callbacks {
		clone := *analyzer
		clone.recursiveExpressionContext = true
		clone.deferredExecution = false
		states = append(states, s6EvaluateImmediateCallEffects(
			&ast.CallExpr{Fun: callback},
			s6CloneReachingBindings(state),
			&clone,
		))
	}
	if len(states) == 0 {
		failed := s6CloneReachingBindings(state)
		failed.analysisErr = errors.New(
			"sync.Once callback reaching guarded flow is unresolved",
		)
		return failed
	}
	return s6MergeReachingBindings(states...)
}

func s6OnceDoCallInfo(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) ([]ast.Expr, map[string]bool, int, bool, bool) {
	if call == nil || analyzer == nil || analyzer.model == nil {
		return nil, nil, -1, false, false
	}
	var receivers []ast.Expr
	frozenIdentities := map[string]bool{}
	callbackIndex := -1
	unresolved := false
	var inspect func(ast.Expr, map[string]bool)
	inspect = func(expression ast.Expr, resolving map[string]bool) {
		switch typed := expression.(type) {
		case *ast.ParenExpr:
			inspect(typed.X, resolving)
		case *ast.SelectorExpr:
			if typed.Sel.Name != "Do" {
				return
			}
			if s6SyncOnceTypeExpression(typed.X, analyzer) {
				if len(call.Args) < 2 {
					unresolved = true
					return
				}
				callbackIndex = 1
				receivers = append(receivers, call.Args[0])
				return
			}
			if !s6ExpressionIsSyncOnce(typed.X, analyzer) {
				return
			}
			if callbackIndex >= 0 && callbackIndex != 0 {
				unresolved = true
			}
			callbackIndex = 0
			receivers = append(receivers, typed.X)
		case *ast.Ident:
			if method, ok := bindings.onceMethods[s6OnceMethodBindingKey(
				typed, analyzer,
			)]; ok {
				for identity := range method.identities {
					frozenIdentities[identity] = true
				}
				unresolved = unresolved || method.unresolved
				if callbackIndex >= 0 && callbackIndex != 0 {
					unresolved = true
				}
				callbackIndex = 0
				return
			}
			key := s6IdentifierFlowKey(typed)
			if resolving[key] {
				unresolved = true
				return
			}
			resolving[key] = true
			defer delete(resolving, key)
			candidates := bindings.candidates(typed)
			if len(candidates) == 0 {
				globalKey := analyzer.pkg + "." + typed.Name
				candidates = bindings.globalByKey[globalKey]
			}
			if len(candidates) == 0 {
				return
			}
			for _, candidate := range candidates {
				inspect(candidate, resolving)
			}
		}
	}
	inspect(call.Fun, map[string]bool{})
	return receivers, frozenIdentities, callbackIndex,
		len(receivers) != 0 || len(frozenIdentities) != 0, unresolved
}

func s6SyncOnceTypeExpression(
	expression ast.Expr,
	analyzer *s6FlowAnalyzer,
) bool {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6SyncOnceTypeExpression(typed.X, analyzer)
	case *ast.StarExpr:
		return s6SyncOnceTypeExpression(typed.X, analyzer)
	case *ast.SelectorExpr:
		base, ok := typed.X.(*ast.Ident)
		return ok && analyzer.imports[base.Name] == "sync" &&
			typed.Sel.Name == "Once"
	case *ast.Ident:
		ref := s6TypeRef{pkg: analyzer.pkg, name: typed.Name}
		ref = analyzer.model.resolveAlias(ref)
		return ref.pkg == "sync" && ref.name == "Once"
	default:
		return false
	}
}

func s6ExpressionIsSyncOnce(
	expression ast.Expr,
	analyzer *s6FlowAnalyzer,
) bool {
	ref := s6ExpressionType(
		analyzer.pkg, analyzer.imports, expression,
		analyzer.locals, analyzer.model,
	)
	ref = analyzer.model.resolveAlias(ref)
	return ref.pkg == "sync" && ref.name == "Once"
}

func s6OnceIdentities(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) (map[string]bool, bool) {
	identities := map[string]bool{}
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6OnceIdentities(typed.X, bindings, analyzer, resolving)
	case *ast.UnaryExpr:
		if typed.Op == token.AND || typed.Op == token.MUL {
			return s6OnceIdentities(typed.X, bindings, analyzer, resolving)
		}
	case *ast.TypeAssertExpr:
		return s6OnceIdentities(typed.X, bindings, analyzer, resolving)
	case *ast.Ident:
		globalKey := analyzer.pkg + "." + typed.Name
		globalRef := analyzer.model.resolveAlias(
			analyzer.model.globalTypes[globalKey],
		)
		if s6IdentifierIsPackageGlobal(
			typed, analyzer.function, globalKey, analyzer.model,
		) && globalRef.pkg == "sync" && globalRef.name == "Once" &&
			globalRef.pointerDepth == 0 {
			identities["global:"+globalKey] = true
			return identities, false
		}
		ref := s6ExpressionType(
			analyzer.pkg, analyzer.imports, typed,
			analyzer.locals, analyzer.model,
		)
		ref = analyzer.model.resolveAlias(ref)
		if ref.pkg == "sync" && ref.name == "Once" && ref.pointerDepth == 0 {
			identities["local:"+s6IdentifierFlowKey(typed)] = true
			return identities, false
		}
		key := "once:" + s6IdentifierFlowKey(typed)
		if resolving[key] {
			return identities, true
		}
		resolving[key] = true
		defer delete(resolving, key)
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 {
			candidates = bindings.globalByKey[globalKey]
		}
		if len(candidates) == 0 &&
			s6IdentifierIsPackageGlobal(
				typed, analyzer.function, globalKey, analyzer.model,
			) {
			candidates = s6GlobalInitialExpressions(analyzer.model, globalKey)
		}
		if len(candidates) == 0 {
			return identities, true
		}
		unresolved := false
		for _, candidate := range candidates {
			resolved, candidateUnresolved := s6OnceIdentities(
				candidate, bindings, analyzer, resolving,
			)
			for identity := range resolved {
				identities[identity] = true
			}
			unresolved = unresolved || candidateUnresolved
		}
		return identities, unresolved
	case *ast.SelectorExpr:
		if key, modeled, external := s6ImportedGlobalKey(
			typed, analyzer.imports, analyzer.model,
		); modeled {
			ref := analyzer.model.resolveAlias(analyzer.model.globalTypes[key])
			if ref.pkg == "sync" && ref.name == "Once" &&
				ref.pointerDepth == 0 {
				identities["global:"+key] = true
				return identities, false
			}
			aliases := s6ExpandGlobalAliasSet(
				map[string]bool{key: true}, bindings, analyzer.model,
			)
			for alias := range aliases {
				aliasRef := analyzer.model.resolveAlias(
					analyzer.model.globalTypes[alias],
				)
				if aliasRef.pkg == "sync" && aliasRef.name == "Once" &&
					aliasRef.pointerDepth == 0 {
					identities["global:"+alias] = true
				}
			}
			if len(identities) != 0 {
				return identities, false
			}
			candidates := bindings.globalByKey[key]
			if len(candidates) == 0 {
				candidates = s6GlobalInitialExpressions(analyzer.model, key)
			}
			unresolved := len(candidates) == 0
			for _, candidate := range candidates {
				candidateAnalyzer := analyzer
				for _, bound := range analyzer.model.globalValues[key] {
					if bound.expression != candidate {
						continue
					}
					clone := *analyzer
					clone.pkg = bound.pkg
					clone.imports = bound.imports
					clone.function = nil
					candidateAnalyzer = &clone
					break
				}
				resolved, candidateUnresolved := s6OnceIdentities(
					candidate, bindings, candidateAnalyzer, resolving,
				)
				for identity := range resolved {
					identities[identity] = true
				}
				unresolved = unresolved || candidateUnresolved
			}
			return identities, unresolved
		} else if external {
			return identities, true
		}
		if !s6ExpressionIsSyncOnce(typed, analyzer) {
			return identities, true
		}
		baseRef := analyzer.model.resolveAlias(s6ExpressionType(
			analyzer.pkg, analyzer.imports, typed.X,
			analyzer.locals, analyzer.model,
		))
		if baseRef.pointerDepth > 0 {
			candidates, unresolved := s6SnapshotDeferredExpression(
				typed.X, bindings, analyzer, map[string]bool{},
			)
			for _, candidate := range candidates {
				bases, baseUnresolved := s6OnceStorageIdentities(
					candidate, bindings, analyzer, resolving,
				)
				for base := range bases {
					identities["field:"+base+"."+typed.Sel.Name] = true
				}
				unresolved = unresolved || baseUnresolved
			}
			return identities, unresolved || len(identities) == 0
		}
		ref := analyzer.model.resolveAlias(s6ExpressionType(
			analyzer.pkg, analyzer.imports, typed,
			analyzer.locals, analyzer.model,
		))
		if ref.pointerDepth > 0 || ref.interfaceType {
			candidates, unresolved := s6SnapshotDeferredExpression(
				typed, bindings, analyzer, map[string]bool{},
			)
			for _, candidate := range candidates {
				if candidate == typed {
					unresolved = true
					continue
				}
				resolved, candidateUnresolved := s6OnceIdentities(
					candidate, bindings, analyzer, resolving,
				)
				for identity := range resolved {
					identities[identity] = true
				}
				unresolved = unresolved || candidateUnresolved
			}
			return identities, unresolved
		}
		bases, unresolved := s6OnceStorageIdentities(
			typed.X, bindings, analyzer, resolving,
		)
		for base := range bases {
			identities["field:"+base+"."+typed.Sel.Name] = true
		}
		return identities, unresolved
	case *ast.IndexExpr:
		if !s6ExpressionIsSyncOnce(typed, analyzer) {
			return identities, true
		}
		bases, unresolved := s6OnceStorageIdentities(
			typed.X, bindings, analyzer, resolving,
		)
		index := s6OnceIndexIdentity(typed.Index)
		if index == "" {
			return identities, true
		}
		for base := range bases {
			identities["index:"+base+":"+index] = true
		}
		return identities, unresolved
	}
	return identities, true
}

func s6OnceCollectionStorageIdentities(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) (map[string]bool, bool) {
	identities := map[string]bool{}
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6OnceCollectionStorageIdentities(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.SliceExpr:
		return s6OnceCollectionStorageIdentities(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.Ident:
		key := "once-collection:" + s6IdentifierFlowKey(typed)
		if resolving[key] {
			return identities, true
		}
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 {
			globalKey := analyzer.pkg + "." + typed.Name
			if s6IdentifierIsPackageGlobal(
				typed, analyzer.function, globalKey, analyzer.model,
			) {
				identities["global:"+globalKey] = true
				return identities, false
			}
			if s6IsFunctionParameter(analyzer, typed) {
				return identities, true
			}
			identities["local:"+s6IdentifierFlowKey(typed)] = true
			return identities, false
		}
		resolving[key] = true
		defer delete(resolving, key)
		unresolved := false
		for _, candidate := range candidates {
			resolved, candidateUnresolved :=
				s6OnceCollectionStorageIdentities(
					candidate, bindings, analyzer, resolving,
				)
			for identity := range resolved {
				identities[identity] = true
			}
			unresolved = unresolved || candidateUnresolved
		}
		return identities, unresolved
	case *ast.CompositeLit:
		identities[fmt.Sprintf("literal:%d", typed.Pos())] = true
		return identities, false
	case *ast.CallExpr:
		if s6IsPredeclaredBuiltinCall(typed, "make", analyzer) {
			identities[fmt.Sprintf("make:%d", typed.Pos())] = true
			return identities, false
		}
		if s6IsPredeclaredBuiltinCall(typed, "append", analyzer) &&
			len(typed.Args) != 0 {
			retain, allocate := s6AppendBackingPossibilities(
				typed, bindings, analyzer,
			)
			unresolved := false
			if retain {
				source, sourceUnresolved :=
					s6OnceCollectionStorageIdentities(
						typed.Args[0], bindings, analyzer, resolving,
					)
				for identity := range source {
					identities[identity] = true
				}
				unresolved = unresolved || sourceUnresolved
			}
			if allocate {
				identities[fmt.Sprintf("append:%d", typed.Pos())] = true
			}
			return identities, unresolved || len(identities) == 0
		}
	}
	return identities, true
}

func s6AppendBackingPossibilities(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) (bool, bool) {
	if call == nil || len(call.Args) == 0 {
		return true, true
	}
	counts, countKnown := s6AppendCounts(
		call, bindings, analyzer, map[string]bool{},
	)
	if countKnown && len(counts) != 0 {
		allZero := true
		for _, count := range counts {
			allZero = allZero && count == 0
		}
		if allZero {
			return true, false
		}
	}
	if len(call.Args) < 2 {
		return true, false
	}
	shapes, shapeKnown := s6SliceShapes(
		call.Args[0], bindings, analyzer, map[string]bool{},
	)
	if !shapeKnown || !countKnown || len(shapes) == 0 || len(counts) == 0 {
		return true, true
	}
	retain := false
	allocate := false
	for _, shape := range shapes {
		for _, count := range counts {
			newLength := shape.length + count
			if newLength <= shape.capLower {
				retain = true
			}
			if shape.capUpperKnown && newLength > shape.capUpper {
				allocate = true
			}
			if !shape.capUpperKnown && newLength > shape.capLower {
				retain = true
				allocate = true
			}
		}
	}
	return retain, allocate
}

func s6OnceIndexIdentity(expression ast.Expr) string {
	switch typed := expression.(type) {
	case *ast.BasicLit:
		return typed.Value
	case *ast.Ident:
		if typed.Name == "true" || typed.Name == "false" {
			return typed.Name
		}
	}
	return ""
}

func s6OnceStorageIdentities(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) (map[string]bool, bool) {
	identities := map[string]bool{}
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6OnceStorageIdentities(typed.X, bindings, analyzer, resolving)
	case *ast.UnaryExpr:
		if typed.Op == token.AND {
			if identifier, ok := typed.X.(*ast.Ident); ok {
				globalKey := analyzer.pkg + "." + identifier.Name
				if s6IdentifierIsPackageGlobal(
					identifier, analyzer.function, globalKey, analyzer.model,
				) {
					identities["global:"+globalKey] = true
				} else {
					identities["local:"+s6IdentifierFlowKey(identifier)] = true
				}
				return identities, false
			}
			return s6OnceStorageIdentities(
				typed.X, bindings, analyzer, resolving,
			)
		}
		if typed.Op == token.MUL {
			return s6OnceStorageIdentities(
				typed.X, bindings, analyzer, resolving,
			)
		}
	case *ast.TypeAssertExpr:
		return s6OnceStorageIdentities(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.SliceExpr:
		return s6OnceStorageIdentities(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.IndexExpr:
		bases, unresolved := s6OnceCollectionStorageIdentities(
			typed.X, bindings, analyzer, resolving,
		)
		if len(bases) == 0 {
			bases, unresolved = s6OnceStorageIdentities(
				typed.X, bindings, analyzer, resolving,
			)
		}
		index := s6OnceIndexIdentity(typed.Index)
		if index == "" {
			return identities, true
		}
		for base := range bases {
			identities["index:"+base+":"+index] = true
		}
		return identities, unresolved
	case *ast.Ident:
		globalKey := analyzer.pkg + "." + typed.Name
		if s6IdentifierIsPackageGlobal(
			typed, analyzer.function, globalKey, analyzer.model,
		) {
			identities["global:"+globalKey] = true
			return identities, false
		}
		ref := s6ExpressionType(
			analyzer.pkg, analyzer.imports, typed,
			analyzer.locals, analyzer.model,
		)
		ref = analyzer.model.resolveAlias(ref)
		if ref.pointerDepth == 0 {
			identities["local:"+s6IdentifierFlowKey(typed)] = true
			return identities, false
		}
		key := "once-storage:" + s6IdentifierFlowKey(typed)
		if resolving[key] {
			return identities, true
		}
		resolving[key] = true
		defer delete(resolving, key)
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 {
			return identities, true
		}
		unresolved := false
		for _, candidate := range candidates {
			resolved, candidateUnresolved := s6OnceStorageIdentities(
				candidate, bindings, analyzer, resolving,
			)
			for identity := range resolved {
				identities[identity] = true
			}
			unresolved = unresolved || candidateUnresolved
		}
		return identities, unresolved
	case *ast.SelectorExpr:
		if key, modeled, external := s6ImportedGlobalKey(
			typed, analyzer.imports, analyzer.model,
		); modeled {
			identities["global:"+key] = true
			return identities, false
		} else if external {
			return identities, true
		}
		bases, unresolved := s6OnceStorageIdentities(
			typed.X, bindings, analyzer, resolving,
		)
		for base := range bases {
			identities["field:"+base+"."+typed.Sel.Name] = true
		}
		return identities, unresolved
	}
	return identities, true
}

func s6TypeRefIsSyncOnce(
	ref s6TypeRef,
	model *s6SourceTypeModel,
) bool {
	ref = model.resolveAlias(ref)
	return ref.pkg == "sync" && ref.name == "Once"
}

func s6CheckOpaqueCallbackCall(
	call *ast.CallExpr,
	state *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) (*s6ReachingBindings, bool) {
	if call == nil || analyzer == nil || analyzer.model == nil ||
		!analyzer.ordinaryEffects || s6DeferredConversionCall(call, analyzer) {
		return state, false
	}
	if local, _ := s6ResolvedLocalCall(call, state, analyzer); local {
		return state, false
	}
	var callbackIndexes []int
	unresolvedCallbacks := map[int]bool{}
	for index, argument := range call.Args {
		if s6ApprovedSynchronousCallbackCall(call, index, state) {
			continue
		}
		callable, unresolved := s6ExpressionIsCallableArgument(
			argument, state, analyzer,
		)
		if callable {
			callbackIndexes = append(callbackIndexes, index)
			unresolvedCallbacks[index] = unresolved
		}
	}
	if len(callbackIndexes) == 0 {
		return state, false
	}
	current := s6MarkEscapedChannelsFromCall(call, state, analyzer)
	current = s6ApplyImmediateExpressionEffects(call.Fun, current, analyzer)
	if current.panicking {
		return current, true
	}
	for _, argument := range call.Args {
		current = s6ApplyCallArgumentEffects(
			argument, current, analyzer,
		)
		if current.panicking {
			return current, true
		}
	}
	for _, index := range callbackIndexes {
		if unresolvedCallbacks[index] {
			if s6AnalyzerHasGuardedState(analyzer) {
				failed := s6CloneReachingBindings(current)
				failed.analysisErr = fmt.Errorf(
					"opaque callback reaching guarded flow is unresolved: %s",
					s6CallName(call),
				)
				return failed, true
			}
			continue
		}
		if s6TriviallyReadOnlyCallback(call.Args[index]) {
			continue
		}
		clone := *analyzer
		clone.recursiveExpressionContext = true
		probe := s6EvaluateImmediateCallEffects(
			&ast.CallExpr{Fun: call.Args[index]},
			s6CloneReachingBindings(current),
			&clone,
		)
		if probe.analysisErr != nil ||
			s6CallbackChangesGuardedState(current, probe, analyzer) {
			failed := s6CloneReachingBindings(current)
			failed.analysisErr = fmt.Errorf(
				"opaque callback may mutate guarded flow: %s",
				s6CallName(call),
			)
			return failed, true
		}
	}
	return current, true
}

func s6TriviallyReadOnlyCallback(expression ast.Expr) bool {
	for {
		parenthesized, ok := expression.(*ast.ParenExpr)
		if !ok {
			break
		}
		expression = parenthesized.X
	}
	literal, ok := expression.(*ast.FuncLit)
	if !ok {
		return false
	}
	readOnly := true
	ast.Inspect(literal.Body, func(node ast.Node) bool {
		if !readOnly || node == nil {
			return false
		}
		if nested, ok := node.(*ast.FuncLit); ok && nested != literal {
			return false
		}
		switch typed := node.(type) {
		case *ast.AssignStmt:
			for _, target := range typed.Lhs {
				identifier, ok := target.(*ast.Ident)
				if !ok || identifier.Name != "_" {
					readOnly = false
					return false
				}
			}
		case *ast.IncDecStmt, *ast.SendStmt, *ast.GoStmt, *ast.DeferStmt,
			*ast.CallExpr:
			readOnly = false
			return false
		case *ast.UnaryExpr:
			if typed.Op == token.ARROW {
				readOnly = false
				return false
			}
		}
		return true
	})
	return readOnly
}

func s6ExpressionIsCallableArgument(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) (bool, bool) {
	if _, ok := expression.(*ast.FuncLit); ok {
		return true, false
	}
	ref := s6ExpressionType(
		analyzer.pkg, analyzer.imports, expression,
		analyzer.locals, analyzer.model,
	)
	ref = analyzer.model.resolveAlias(ref)
	context := s6CallableContext{
		pkg: analyzer.pkg, imports: analyzer.imports, locals: analyzer.locals,
		bindings: bindings, params: s6AnalyzerCallableParameters(analyzer),
		functionKey: analyzer.functionKey,
	}
	identities, unresolved := s6ResolveCallableIdentitiesFromContext(
		expression, context, analyzer.model, map[string]bool{},
	)
	if ref.name == "func" {
		return true, unresolved
	}
	for _, identity := range identities {
		if identity.literal != nil ||
			len(analyzer.model.functionDecls[identity.functionKey()]) != 0 {
			return true, unresolved
		}
	}
	return false, false
}

func s6AnalyzerHasGuardedState(analyzer *s6FlowAnalyzer) bool {
	return analyzer != nil &&
		(len(analyzer.guardedObjects) != 0 ||
			len(analyzer.guardedNames) != 0 ||
			len(analyzer.reachableGlobals) != 0)
}

func s6CallbackChangesGuardedState(
	before *s6ReachingBindings,
	after *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	if before == nil || after == nil || analyzer == nil {
		return false
	}
	objectNames := map[string]bool{}
	for object := range analyzer.guardedObjects {
		if object == nil {
			continue
		}
		objectNames[object.Name] = true
		if !s6SameExpressionDomain(
			before.byObject[object], after.byObject[object],
		) || !s6SameFieldDomains(
			before.fieldsByObj[object], after.fieldsByObj[object],
		) || before.concurrentByObj[object] != after.concurrentByObj[object] {
			return true
		}
	}
	for name := range analyzer.guardedNames {
		if objectNames[name] {
			continue
		}
		if !s6SameExpressionDomain(
			before.byName[name], after.byName[name],
		) || !s6SameFieldDomains(
			before.fieldsByName[name], after.fieldsByName[name],
		) || before.concurrentByName[name] != after.concurrentByName[name] {
			return true
		}
	}
	reachable := s6ExpandGlobalAliasSet(
		analyzer.reachableGlobals, before, analyzer.model,
	)
	reachable = s6ExpandGlobalAliasSet(reachable, after, analyzer.model)
	for key := range reachable {
		if !s6SameExpressionDomain(
			before.globalByKey[key], after.globalByKey[key],
		) || !s6SameBoolSet(
			before.globalAliases[key], after.globalAliases[key],
		) {
			return true
		}
	}
	return false
}

func s6SameBoolSet(left, right map[string]bool) bool {
	if len(left) != len(right) {
		return false
	}
	for key := range left {
		if !right[key] {
			return false
		}
	}
	return true
}

func s6EvaluateImmediateCallEffects(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) *s6ReachingBindings {
	callableState, callableUnresolved := s6EvaluateDeferredCallableExpression(
		call.Fun, s6CloneReachingBindings(bindings), analyzer,
	)
	if callableState.panicking {
		return callableState
	}
	callableCapture := s6CloneReachingBindings(callableState)
	argumentDomains := make([][]ast.Expr, len(call.Args))
	argumentUnresolved := make([]bool, len(call.Args))
	current := callableState
	for index, argument := range call.Args {
		current, argumentDomains[index], argumentUnresolved[index] =
			s6EvaluateDeferredExpression(argument, current, analyzer)
		if current.panicking {
			return current
		}
		s6RejectUsedOnceValueCopy(argument, current, analyzer)
		if len(argumentDomains[index]) == 0 {
			argumentDomains[index] = []ast.Expr{s6DeferredUnknown}
			argumentUnresolved[index] = true
		}
	}
	if len(call.Args) == 1 && s6DeferredConversionCall(call, analyzer) {
		return current
	}
	deferred := s6DeferredCall{
		call:               call,
		capture:            callableCapture,
		callableUnresolved: callableUnresolved,
		immediate:          true,
		args:               argumentDomains,
		argUnresolved:      argumentUnresolved,
	}
	if receiver, receiverUnresolved := s6FreezeDeferredReceiver(
		call, callableCapture, analyzer,
	); len(receiver) != 0 || receiverUnresolved {
		deferred.receiver = receiver
		deferred.receiverUnresolved = receiverUnresolved
	}
	probe := s6NewFlowFrame(current)
	probe.deferred = []s6DeferredCall{deferred}
	return s6ExecuteDeferredCalls(nil, probe, analyzer).bindings
}

func s6ApplyShortCircuitExpressionEffects(
	expression *ast.BinaryExpr,
	state *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) *s6ReachingBindings {
	if analyzer == nil {
		analyzer = &s6FlowAnalyzer{}
	} else {
		clone := *analyzer
		analyzer = &clone
	}
	analyzer.recursiveExpressionContext = true
	leftState := s6ApplyImmediateExpressionEffects(
		expression.X, state, analyzer,
	)
	leftValues, _ := s6SnapshotDeferredExpression(
		expression.X, leftState, analyzer, map[string]bool{},
	)
	canTrue, canFalse := s6BooleanPossibilities(leftValues)
	evaluateRight := expression.Op == token.LAND && canTrue ||
		expression.Op == token.LOR && canFalse
	skipRight := expression.Op == token.LAND && canFalse ||
		expression.Op == token.LOR && canTrue
	var states []*s6ReachingBindings
	if skipRight {
		states = append(states, leftState)
	}
	if evaluateRight {
		states = append(states, s6ApplyImmediateExpressionEffects(
			expression.Y, leftState, analyzer,
		))
	}
	if len(states) == 0 {
		states = append(states, leftState)
	}
	return s6MergeExpressionAlternatives(states...)
}

func s6GuardedCallableIsLocal(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	if call == nil || analyzer == nil ||
		s6DeferredConversionCall(call, analyzer) {
		return false
	}
	switch callable := call.Fun.(type) {
	case *ast.Ident:
		if callable.Name == "openFlags" {
			return false
		}
		if _, seam := prepareInjectionSeamRegistry[callable.Name]; seam {
			return false
		}
		if analyzer.model != nil {
			key := analyzer.pkg + "." + callable.Name
			if ref := analyzer.model.globalTypes[key]; ref.name == "func" &&
				len(analyzer.model.globalValues[key]) == 0 {
				return false
			}
		}
		return !s6IsPredeclaredBuiltinCall(call, callable.Name, analyzer)
	case *ast.SelectorExpr:
		if base, ok := callable.X.(*ast.Ident); ok &&
			analyzer.imports[base.Name] != "" {
			return false
		}
		if analyzer.model == nil {
			return false
		}
		if analyzer.model != nil {
			identity := s6ResolveCallIdentity(
				analyzer.pkg, analyzer.imports, call,
				analyzer.locals, analyzer.model,
			)
			if identity.known && identity.pkg != "" &&
				identity.pkg != analyzer.pkg {
				return false
			}
		}
		if s6ExpressionComesFromImportedCall(
			callable.X, bindings, analyzer,
			map[string]bool{},
		) {
			return false
		}
		if _, unique := s6UniqueDeclaredMethodIdentity(
			analyzer.model, callable.Sel.Name,
		); unique {
			return true
		}
		receiver := analyzer.model.resolveAlias(s6ExpressionType(
			analyzer.pkg, analyzer.imports, callable.X,
			analyzer.locals, analyzer.model,
		))
		if fields := analyzer.model.fields[receiver.key()]; fields != nil &&
			fields[callable.Sel.Name].name == "func" {
			return true
		}
		if base, ok := callable.X.(*ast.Ident); ok &&
			len(bindings.fieldCandidates(base, callable.Sel.Name)) != 0 {
			return true
		}
		return s6TypeRefIsInterface(
			receiver, analyzer.model, map[string]bool{},
		)
	default:
		return true
	}
}

func s6DeclaredFunctionsByName(
	model *s6SourceTypeModel,
	name string,
) []*ast.FuncDecl {
	var declarations []*ast.FuncDecl
	for key, candidates := range model.functionDecls {
		if !strings.HasSuffix(key, "."+name) {
			continue
		}
		for _, candidate := range candidates {
			if candidate.Recv == nil {
				declarations = append(declarations, candidate)
			}
		}
	}
	return declarations
}

func s6DeclarationsHaveNoObservableEffects(
	declarations []*ast.FuncDecl,
	pkg string,
	analyzer *s6FlowAnalyzer,
) bool {
	if len(declarations) == 0 || analyzer == nil || analyzer.model == nil {
		return false
	}
	for _, declaration := range declarations {
		pure := true
		ast.Inspect(declaration.Body, func(node ast.Node) bool {
			if !pure {
				return false
			}
			if literal, ok := node.(*ast.FuncLit); ok && literal != nil {
				return false
			}
			switch typed := node.(type) {
			case *ast.GoStmt, *ast.DeferStmt:
				pure = false
				return false
			case *ast.IncDecStmt:
				if _, local := typed.X.(*ast.Ident); !local {
					pure = false
					return false
				}
			case *ast.AssignStmt:
				for _, target := range typed.Lhs {
					identifier, local := target.(*ast.Ident)
					if !local || analyzer.model.globalTypes[pkg+"."+identifier.Name].valid() {
						pure = false
						return false
					}
				}
			case *ast.CallExpr:
				declarationAnalyzer := &s6FlowAnalyzer{
					function: declaration,
					model:    analyzer.model,
					pkg:      analyzer.model.functionPackages[declaration],
					imports:  analyzer.model.functionImports[declaration],
					locals: s6FunctionLocalTypes(
						analyzer.model.functionPackages[declaration],
						analyzer.model.functionFiles[declaration],
						declaration, analyzer.model,
					),
				}
				if identifier, ok := typed.Fun.(*ast.Ident); ok &&
					s6IsPredeclaredBuiltinCall(
						typed, identifier.Name, declarationAnalyzer,
					) {
					return true
				}
				if selector, ok := typed.Fun.(*ast.SelectorExpr); ok {
					if base, ok := selector.X.(*ast.Ident); ok &&
						analyzer.imports[base.Name] != "" {
						return true
					}
				}
				pure = false
				return false
			}
			return true
		})
		if !pure {
			return false
		}
	}
	return true
}

func s6ExpressionComesFromImportedCall(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
	resolving map[string]bool,
) bool {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6ExpressionComesFromImportedCall(
			typed.X, bindings, analyzer, resolving,
		)
	case *ast.Ident:
		key := s6IdentifierFlowKey(typed)
		if resolving[key] {
			return false
		}
		resolving[key] = true
		defer delete(resolving, key)
		for _, candidate := range bindings.candidates(typed) {
			if s6ExpressionComesFromImportedCall(
				candidate, bindings, analyzer, resolving,
			) {
				return true
			}
		}
	case *ast.CallExpr:
		selector, ok := typed.Fun.(*ast.SelectorExpr)
		if !ok {
			return false
		}
		alias, ok := selector.X.(*ast.Ident)
		return ok && analyzer != nil && analyzer.imports[alias.Name] != ""
	case *ast.SelectorExpr:
		return s6ExpressionComesFromImportedCall(
			typed.X, bindings, analyzer, resolving,
		)
	}
	return false
}

func s6CallHasNoModeledBindingEffects(
	call *ast.CallExpr,
	analyzer *s6FlowAnalyzer,
) bool {
	if call == nil || analyzer == nil || analyzer.model == nil {
		return false
	}
	selector, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	if base, ok := selector.X.(*ast.Ident); ok {
		if imported := analyzer.imports[base.Name]; imported != "" &&
			len(analyzer.model.functionDecls[imported+"."+selector.Sel.Name]) != 0 {
			return false
		}
	}
	switch selector.Sel.Name {
	case "ScratchFactory", "RootOpsFactory", "RandomHex12", "Hook",
		"BeforeRename", "CaptureIndex", "EnumerateBlobs", "ProbeBlob",
		"PreflightIndexCAS", "PreflightBlobRemove", "SyncDirectory",
		"Lstat", "Open", "SameFile", "Stat", "Read", "Write", "Sync",
		"Chmod", "Readdirnames", "Close", "Error", "SyscallConn":
		return true
	}
	ref := s6ExpressionType(
		analyzer.pkg, analyzer.imports, selector.X,
		analyzer.locals, analyzer.model,
	)
	if !s6TypeRefIsInterface(ref, analyzer.model, map[string]bool{}) {
		return false
	}
	return false
}

func s6MarkEscapedChannelsFromCall(
	call *ast.CallExpr,
	state *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) *s6ReachingBindings {
	if call == nil || analyzer == nil ||
		s6DeferredConversionCall(call, analyzer) {
		return state
	}
	if identifier, ok := call.Fun.(*ast.Ident); ok &&
		s6IsPredeclaredBuiltinCall(call, identifier.Name, analyzer) {
		return state
	}
	result := state
	cloned := false
	for _, argument := range call.Args {
		channels, unresolved := s6ChannelIdentities(
			argument, state, analyzer, map[string]bool{},
		)
		if len(channels) == 0 && !unresolved {
			continue
		}
		if !cloned {
			result = s6CloneReachingBindings(state)
			cloned = true
		}
		s6MarkChannelNondeterministic(argument, result, analyzer)
		channels, _ = s6ChannelIdentities(
			argument, result, analyzer, map[string]bool{},
		)
		for identity := range channels {
			queue := result.channelQueues[identity]
			queue.unknownFuture = true
			result.channelQueues[identity] = queue
		}
	}
	return result
}

func s6CallMayHaveOrdinaryEffects(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	if call == nil || analyzer == nil || analyzer.model == nil {
		return false
	}
	if ref := s6ExpressionType(
		analyzer.pkg, analyzer.imports, call.Fun,
		analyzer.locals, analyzer.model,
	); ref.name == "func" {
		return true
	}
	for _, expression := range call.Args {
		if s6CallableCapturesGuarded(
			expression, bindings, analyzer,
		) {
			return true
		}
		if s6ExpressionReferencesGuarded(expression, analyzer) {
			return true
		}
		if backings, _ := s6BackingIdentities(
			expression, bindings, analyzer, map[string]bool{},
		); s6BackingsReachGuarded(backings, bindings, analyzer) {
			return true
		}
		if targets, _, _ := s6GoAliasTargets(
			expression, bindings, analyzer, map[string]bool{},
		); s6IdentifiersReachGuarded(targets, analyzer) {
			return true
		}
	}
	if selector, ok := call.Fun.(*ast.SelectorExpr); ok {
		receiverRef := analyzer.model.resolveAlias(s6ExpressionType(
			analyzer.pkg, analyzer.imports, selector.X,
			analyzer.locals, analyzer.model,
		))
		if receiverRef.container {
			if backings, _ := s6BackingIdentities(
				selector.X, bindings, analyzer, map[string]bool{},
			); s6BackingsReachGuarded(backings, bindings, analyzer) {
				return true
			}
		}
		if targets, _, _ := s6GoAliasTargets(
			selector.X, bindings, analyzer, map[string]bool{},
		); s6IdentifiersReachGuarded(targets, analyzer) {
			return true
		}
	}
	return false
}

func s6ExpressionReferencesGuarded(
	expression ast.Expr,
	analyzer *s6FlowAnalyzer,
) bool {
	found := false
	ast.Inspect(expression, func(node ast.Node) bool {
		identifier, ok := node.(*ast.Ident)
		if !ok {
			return true
		}
		if identifier.Obj != nil && analyzer.guardedObjects[identifier.Obj] ||
			analyzer.guardedNames[identifier.Name] {
			found = true
			return false
		}
		return true
	})
	return found
}

func s6IdentifiersReachGuarded(
	identifiers []*ast.Ident,
	analyzer *s6FlowAnalyzer,
) bool {
	for _, identifier := range identifiers {
		if identifier.Obj != nil && analyzer.guardedObjects[identifier.Obj] ||
			analyzer.guardedNames[identifier.Name] {
			return true
		}
	}
	return false
}

func s6CallableCapturesGuarded(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	literals, _ := s6ResolveLocalFunctionLiterals(
		expression, bindings, map[string]bool{},
	)
	for _, literal := range literals {
		if s6ExpressionReferencesGuarded(literal, analyzer) {
			return true
		}
	}
	return false
}

func s6BackingsReachGuarded(
	backings map[ast.Node]bool,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	if len(backings) == 0 {
		return false
	}
	for object, values := range bindings.byObject {
		if !analyzer.guardedObjects[object] {
			continue
		}
		guarded, _ := s6BackingIdentitiesFromValues(
			values, bindings, analyzer, map[string]bool{},
		)
		if s6BackingSetsIntersect(backings, guarded) {
			return true
		}
	}
	for name, values := range bindings.byName {
		if !analyzer.guardedNames[name] {
			continue
		}
		guarded, _ := s6BackingIdentitiesFromValues(
			values, bindings, analyzer, map[string]bool{},
		)
		if s6BackingSetsIntersect(backings, guarded) {
			return true
		}
	}
	return false
}

type s6GlobalEffectSummary struct {
	reads           map[string]bool
	writes          map[string]bool
	escapes         map[string]bool
	unresolvedCalls map[string]bool
	unresolved      bool
}

func s6NewGlobalEffectSummary() s6GlobalEffectSummary {
	return s6GlobalEffectSummary{
		reads:           map[string]bool{},
		writes:          map[string]bool{},
		escapes:         map[string]bool{},
		unresolvedCalls: map[string]bool{},
	}
}

func (summary *s6GlobalEffectSummary) merge(other s6GlobalEffectSummary) {
	for key := range other.reads {
		summary.reads[key] = true
	}
	for key := range other.writes {
		summary.writes[key] = true
	}
	for key := range other.escapes {
		summary.escapes[key] = true
	}
	for call := range other.unresolvedCalls {
		summary.unresolvedCalls[call] = true
	}
	summary.unresolved = summary.unresolved || other.unresolved
}

func s6GlobalEffectsReachBindings(
	summary s6GlobalEffectSummary,
	reachable map[string]bool,
	bindings *s6ReachingBindings,
	model *s6SourceTypeModel,
) bool {
	affected := map[string]bool{}
	for key := range summary.writes {
		affected[key] = true
	}
	for key := range summary.escapes {
		affected[key] = true
	}
	affected = s6ExpandGlobalAliasSet(affected, bindings, model)
	reachable = s6ExpandGlobalAliasSet(reachable, bindings, model)
	for key := range reachable {
		if affected[key] {
			return true
		}
	}
	reads := s6ExpandGlobalAliasSet(summary.reads, bindings, model)
	readsReachGuarded := false
	for key := range reachable {
		if reads[key] {
			readsReachGuarded = true
			break
		}
	}
	if readsReachGuarded {
		for key := range summary.writes {
			if s6TypeMayCarryGlobalAlias(
				model.globalTypes[key], model, map[string]bool{},
			) {
				return true
			}
		}
	}
	return false
}

func s6ResolvedCallGlobalEffects(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) s6GlobalEffectSummary {
	summary := s6NewGlobalEffectSummary()
	if analyzer == nil || analyzer.model == nil {
		return summary
	}
	identities, unresolved := s6ResolveCallableIdentitiesFromContext(
		call.Fun,
		s6CallableContext{
			pkg: analyzer.pkg, imports: analyzer.imports, locals: analyzer.locals,
			bindings: bindings, params: s6AnalyzerCallableParameters(analyzer),
			functionKey:              analyzer.functionKey,
			guardedExpressionContext: true,
		},
		analyzer.model,
		map[string]bool{},
	)
	if (unresolved || len(identities) == 0) &&
		!s6OpaqueCallHasNoModeledEffects(call, bindings, analyzer) &&
		s6UnresolvedCallMayWriteGlobal(
			call, analyzer.function, analyzer.pkg, bindings, analyzer.model,
		) {
		summary.unresolved = true
		summary.unresolvedCalls[s6CallName(call)] = true
	}
	for _, identity := range identities {
		if identity.literal == nil &&
			len(analyzer.model.functionDecls[identity.functionKey()]) == 0 {
			continue
		}
		summary.merge(s6IdentityGlobalEffects(
			identity, analyzer.model, map[string]bool{},
		))
	}
	return summary
}

func s6IdentityGlobalEffects(
	identity s6CallIdentity,
	model *s6SourceTypeModel,
	visiting map[string]bool,
) s6GlobalEffectSummary {
	summary := s6NewGlobalEffectSummary()
	if model == nil {
		return summary
	}
	key := identity.functionKey()
	if identity.literal != nil {
		key = identity.pkg + ".literal@" + strconv.Itoa(int(identity.literal.Pos()))
	}
	cacheKey := struct {
		sourceKey string
		key       string
	}{sourceKey: model.sourceKey, key: key}
	if cached, ok := s6GlobalEffectCache.Load(cacheKey); ok {
		return cached.(s6GlobalEffectSummary)
	}
	if visiting[key] {
		return summary
	}
	visiting[key] = true
	defer delete(visiting, key)
	if identity.literal != nil {
		summary.merge(s6NodeGlobalEffects(
			identity.literal.Body, identity.pkg, "", nil, model, visiting,
		))
		s6GlobalEffectCache.Store(cacheKey, summary)
		return summary
	}
	declarations := model.functionDecls[key]
	if len(declarations) == 0 {
		if identity.pkg == "" || strings.HasPrefix(identity.pkg, "internal/") {
			summary.unresolved = true
			summary.unresolvedCalls[key] = true
		}
		s6GlobalEffectCache.Store(cacheKey, summary)
		return summary
	}
	for _, declared := range declarations {
		pkg := model.functionPackages[declared]
		summary.merge(s6NodeGlobalEffects(
			declared.Body, pkg, key, declared, model, visiting,
		))
	}
	s6GlobalEffectCache.Store(cacheKey, summary)
	return summary
}

func s6NodeGlobalEffects(
	root ast.Node,
	pkg string,
	functionKey string,
	function *ast.FuncDecl,
	model *s6SourceTypeModel,
	visiting map[string]bool,
) s6GlobalEffectSummary {
	summary := s6NewGlobalEffectSummary()
	if root == nil {
		return summary
	}
	imports := map[string]string{}
	locals := map[string]s6TypeRef{}
	if function != nil {
		imports = model.functionImports[function]
		locals = s6FunctionLocalTypes(
			pkg, model.functionFiles[function], function, model,
		)
	}
	writeOnlyNodes := map[ast.Node]bool{}
	ast.Inspect(root, func(node ast.Node) bool {
		switch typed := node.(type) {
		case *ast.AssignStmt:
			if typed.Tok != token.ASSIGN && typed.Tok != token.DEFINE {
				return true
			}
			for _, target := range typed.Lhs {
				ast.Inspect(target, func(part ast.Node) bool {
					if part != nil {
						writeOnlyNodes[part] = true
					}
					return true
				})
			}
		case *ast.RangeStmt:
			for _, target := range []ast.Expr{typed.Key, typed.Value} {
				if target == nil {
					continue
				}
				ast.Inspect(target, func(part ast.Node) bool {
					if part != nil {
						writeOnlyNodes[part] = true
					}
					return true
				})
			}
		}
		return true
	})
	ast.Inspect(root, func(node ast.Node) bool {
		if node == nil {
			return false
		}
		if _, ok := node.(*ast.FuncLit); ok && node != root {
			return false
		}
		if identifier, ok := node.(*ast.Ident); ok {
			key := pkg + "." + identifier.Name
			if !writeOnlyNodes[identifier] &&
				s6IdentifierIsPackageGlobal(identifier, function, key, model) {
				summary.reads[key] = true
			}
		}
		switch typed := node.(type) {
		case *ast.AssignStmt:
			var assignmentBindings *s6ReachingBindings
			if function != nil {
				assignmentBindings = s6FunctionBindingsBeforeWithAnalyzer(
					function, typed.Pos(),
					&s6FlowAnalyzer{
						function: function, model: model, pkg: pkg,
						imports: imports, locals: locals, functionKey: functionKey,
						initializingGlobals: true,
					},
				)
			} else {
				assignmentBindings = s6NewReachingBindings()
			}
			for _, target := range typed.Lhs {
				for key := range s6GlobalWriteTargets(
					target, pkg, model, function,
				) {
					summary.writes[key] = true
				}
				if indirect, ok := target.(*ast.StarExpr); ok {
					for key := range s6GlobalsReferencedByExpression(
						indirect.X, pkg, imports, function,
						assignmentBindings, model, map[string]bool{},
					) {
						summary.writes[key] = true
					}
				}
			}
		case *ast.IncDecStmt:
			for key := range s6GlobalWriteTargets(
				typed.X, pkg, model, function,
			) {
				summary.writes[key] = true
			}
		case *ast.CallExpr:
			bindings := s6NewReachingBindings()
			if function != nil {
				bindings = s6FunctionBindingsBeforeWithAnalyzer(
					function, typed.Pos(),
					&s6FlowAnalyzer{
						function: function, model: model, pkg: pkg,
						imports: imports, locals: locals, functionKey: functionKey,
						initializingGlobals: true,
					},
				)
			}
			context := s6CallableContext{
				pkg: pkg, imports: imports, locals: locals, bindings: bindings,
				params: s6FunctionCallableParameters(function), functionKey: functionKey,
			}
			identities, unresolved := s6ResolveCallableIdentitiesFromContext(
				typed.Fun, context, model, map[string]bool{},
			)
			callAnalyzer := &s6FlowAnalyzer{
				function: function, model: model, pkg: pkg, imports: imports,
				locals: locals, functionKey: functionKey,
				initializingGlobals: true,
			}
			if s6GlobalSummaryKnownInertCall(typed, callAnalyzer) {
				return true
			}
			if (unresolved || len(identities) == 0) &&
				!s6OpaqueCallHasNoModeledEffects(typed, bindings, callAnalyzer) &&
				!s6GlobalSummaryKnownInertCall(typed, callAnalyzer) &&
				s6UnresolvedCallMayWriteGlobal(
					typed, function, pkg, bindings, model,
				) {
				summary.unresolved = true
				summary.unresolvedCalls[functionKey+"->"+s6CallName(typed)] = true
			}
			for _, called := range identities {
				if called.literal == nil &&
					len(model.functionDecls[called.functionKey()]) == 0 {
					continue
				}
				summary.merge(s6IdentityGlobalEffects(called, model, visiting))
			}
			for _, argument := range typed.Args {
				for key := range s6EscapedGlobalArguments(
					argument, pkg, model, function,
				) {
					if unresolved || len(identities) == 0 {
						summary.escapes[key] = true
						continue
					}
					for _, called := range identities {
						if s6FunctionKeyMayMutate(
							called.functionKey(), model, map[string]bool{},
						) {
							summary.escapes[key] = true
						}
					}
				}
			}
		}
		return true
	})
	return summary
}

func s6GlobalSummaryKnownInertCall(
	call *ast.CallExpr,
	analyzer *s6FlowAnalyzer,
) bool {
	identifier, ok := call.Fun.(*ast.Ident)
	if !ok {
		return false
	}
	for _, name := range []string{
		"len", "cap", "complex", "imag", "max", "min", "real",
	} {
		if identifier.Name == name &&
			s6IsPredeclaredBuiltinCall(call, name, analyzer) {
			return true
		}
	}
	return s6DeferredConversionCall(call, analyzer)
}

func s6UnresolvedCallMayWriteGlobal(
	call *ast.CallExpr,
	function *ast.FuncDecl,
	pkg string,
	bindings *s6ReachingBindings,
	model *s6SourceTypeModel,
) bool {
	if call == nil || model == nil {
		return false
	}
	if len(s6EscapedGlobalArguments(call.Fun, pkg, model, function)) != 0 {
		return true
	}
	for _, argument := range call.Args {
		if len(s6EscapedGlobalArguments(
			argument, pkg, model, function,
		)) != 0 {
			return true
		}
	}
	switch callable := call.Fun.(type) {
	case *ast.ParenExpr:
		return s6UnresolvedCallMayWriteGlobal(
			&ast.CallExpr{Fun: callable.X, Args: call.Args},
			function, pkg, bindings, model,
		)
	case *ast.Ident:
		if s6FunctionCallableParameters(function)[callable.Name] {
			return true
		}
		if model.globalTypes[pkg+"."+callable.Name].valid() {
			return true
		}
		return len(bindings.candidates(callable)) != 0
	case *ast.SelectorExpr:
		if base, ok := callable.X.(*ast.Ident); ok {
			if len(bindings.fieldCandidates(base, callable.Sel.Name)) != 0 {
				return true
			}
		}
		return false
	case *ast.CallExpr, *ast.IndexExpr:
		return true
	default:
		return false
	}
}

func s6GlobalWriteTargets(
	expression ast.Expr,
	pkg string,
	model *s6SourceTypeModel,
	functions ...*ast.FuncDecl,
) map[string]bool {
	keys := map[string]bool{}
	var function *ast.FuncDecl
	if len(functions) != 0 {
		function = functions[0]
	}
	imports := map[string]string{}
	if function != nil {
		imports = model.functionImports[function]
	}
	var visit func(ast.Expr)
	visit = func(candidate ast.Expr) {
		switch typed := candidate.(type) {
		case *ast.ParenExpr:
			visit(typed.X)
		case *ast.Ident:
			key := pkg + "." + typed.Name
			if s6IdentifierIsPackageGlobal(typed, function, key, model) {
				keys[key] = true
			}
		case *ast.SelectorExpr:
			if key, modeled, _ := s6ImportedGlobalKey(
				typed, imports, model,
			); modeled {
				keys[key] = true
				return
			}
			visit(typed.X)
		case *ast.IndexExpr:
			visit(typed.X)
		case *ast.StarExpr:
			visit(typed.X)
		}
	}
	visit(expression)
	return keys
}

func s6GlobalsReferencedByExpression(
	expression ast.Expr,
	pkg string,
	imports map[string]string,
	function *ast.FuncDecl,
	bindings *s6ReachingBindings,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) map[string]bool {
	keys := map[string]bool{}
	var visit func(ast.Expr)
	visit = func(candidate ast.Expr) {
		switch typed := candidate.(type) {
		case *ast.ParenExpr:
			visit(typed.X)
		case *ast.Ident:
			if key, global := s6GlobalExpressionKey(
				typed, pkg, imports, function, model,
			); global {
				keys[key] = true
				return
			}
			flowKey := s6IdentifierFlowKey(typed)
			if resolving[flowKey] {
				return
			}
			resolving[flowKey] = true
			for _, value := range bindings.candidates(typed) {
				visit(value)
			}
			delete(resolving, flowKey)
		case *ast.SelectorExpr:
			if key, global := s6GlobalExpressionKey(
				typed, pkg, imports, function, model,
			); global {
				keys[key] = true
				return
			}
			visit(typed.X)
		case *ast.IndexExpr:
			visit(typed.X)
		case *ast.SliceExpr:
			visit(typed.X)
		case *ast.TypeAssertExpr:
			visit(typed.X)
		case *ast.UnaryExpr:
			visit(typed.X)
		case *ast.CallExpr:
			for _, argument := range typed.Args {
				visit(argument)
			}
		}
	}
	visit(expression)
	return keys
}

func s6IdentifierIsPackageGlobal(
	identifier *ast.Ident,
	function *ast.FuncDecl,
	key string,
	model *s6SourceTypeModel,
) bool {
	if identifier == nil || model == nil {
		return false
	}
	if _, ok := model.globalTypes[key]; !ok {
		return false
	}
	if function == nil || identifier.Obj == nil {
		return true
	}
	declaration, ok := identifier.Obj.Decl.(ast.Node)
	if !ok {
		return true
	}
	return declaration.Pos() < function.Pos() || declaration.Pos() > function.End()
}

func s6EscapedGlobalArguments(
	expression ast.Expr,
	pkg string,
	model *s6SourceTypeModel,
	functions ...*ast.FuncDecl,
) map[string]bool {
	keys := map[string]bool{}
	var function *ast.FuncDecl
	if len(functions) != 0 {
		function = functions[0]
	}
	imports := map[string]string{}
	locals := map[string]s6TypeRef{}
	if function != nil {
		imports = model.functionImports[function]
		locals = s6FunctionLocalTypes(
			pkg, model.functionFiles[function], function, model,
		)
	}
	var visit func(ast.Expr, bool)
	visit = func(candidate ast.Expr, forced bool) {
		switch typed := candidate.(type) {
		case *ast.ParenExpr:
			visit(typed.X, forced)
		case *ast.UnaryExpr:
			if typed.Op == token.AND {
				for key := range s6GlobalWriteTargets(
					typed.X, pkg, model, function,
				) {
					keys[key] = true
				}
				return
			}
			visit(typed.X, forced)
		case *ast.Ident, *ast.SelectorExpr:
			key, global := s6GlobalExpressionKey(
				typed, pkg, imports, function, model,
			)
			if global {
				ref := model.globalTypes[key]
				ref = model.resolveAlias(ref)
				if forced || s6TypeMayCarryGlobalAlias(
					ref, model, map[string]bool{},
				) {
					keys[key] = true
				}
				return
			}
			if selector, ok := typed.(*ast.SelectorExpr); ok {
				ref := s6ExpressionType(
					pkg, imports, selector, locals, model,
				)
				if forced || s6TypeMayCarryGlobalAlias(
					ref, model, map[string]bool{},
				) {
					visit(selector.X, true)
				}
			}
		case *ast.IndexExpr:
			ref := s6ExpressionType(pkg, imports, typed, locals, model)
			if forced || s6TypeMayCarryGlobalAlias(
				ref, model, map[string]bool{},
			) {
				visit(typed.X, true)
			}
		case *ast.SliceExpr:
			visit(typed.X, true)
		case *ast.TypeAssertExpr:
			visit(typed.X, forced)
		case *ast.CallExpr:
			if len(typed.Args) == 1 {
				visit(typed.Args[0], forced)
			}
		case *ast.CompositeLit:
			for _, element := range typed.Elts {
				if pair, ok := element.(*ast.KeyValueExpr); ok {
					visit(pair.Value, forced)
				} else {
					visit(element, forced)
				}
			}
		}
	}
	visit(expression, false)
	return keys
}

func s6ResolvedCallMayMutate(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	if analyzer == nil || analyzer.model == nil {
		return true
	}
	identities, unresolved := s6ResolveCallableIdentitiesFromContext(
		call.Fun,
		s6CallableContext{
			pkg: analyzer.pkg, imports: analyzer.imports, locals: analyzer.locals,
			bindings: bindings, params: s6AnalyzerCallableParameters(analyzer),
			functionKey:              analyzer.functionKey,
			guardedExpressionContext: true,
		},
		analyzer.model,
		map[string]bool{},
	)
	if unresolved || len(identities) == 0 {
		if method, unique := s6UniqueDeclaredMethodIdentity(
			analyzer.model, s6CallName(call),
		); unique {
			identities = []s6CallIdentity{method}
			unresolved = false
		} else if function, unique := s6UniqueDeclaredFunctionIdentity(
			analyzer.model, s6CallName(call),
		); unique {
			identities = []s6CallIdentity{function}
			unresolved = false
		}
	}
	if unresolved || len(identities) == 0 {
		return true
	}
	for _, identity := range identities {
		if identity.literal != nil {
			if s6NodeHasMutationEffects(
				identity.literal.Body, analyzer.pkg, analyzer.imports,
				analyzer.locals, nil, analyzer.model, map[string]bool{},
			) {
				return true
			}
			continue
		}
		if s6FunctionKeyMayMutate(
			identity.functionKey(), analyzer.model, map[string]bool{},
		) {
			return true
		}
	}
	return false
}

func s6FunctionKeyMayMutate(
	key string,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) bool {
	cacheKey := struct {
		sourceKey string
		key       string
	}{sourceKey: model.sourceKey, key: key}
	if cached, ok := s6MutationSummaryCache.Load(cacheKey); ok {
		return cached.(bool)
	}
	if resolving[key] {
		return true
	}
	resolving[key] = true
	defer delete(resolving, key)
	declarations := model.functionDecls[key]
	if len(declarations) == 0 {
		return true
	}
	for _, declaration := range declarations {
		pkg := model.functionPackages[declaration]
		imports := model.functionImports[declaration]
		locals := s6FunctionLocalTypes(
			pkg, model.functionFiles[declaration], declaration, model,
		)
		if s6NodeHasMutationEffects(
			declaration.Body, pkg, imports, locals,
			s6FunctionCallableParameters(declaration), model, resolving,
		) {
			s6MutationSummaryCache.Store(cacheKey, true)
			return true
		}
	}
	s6MutationSummaryCache.Store(cacheKey, false)
	return false
}

func s6NodeHasMutationEffects(
	node ast.Node,
	pkg string,
	imports map[string]string,
	locals map[string]s6TypeRef,
	callableParams map[string]bool,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) bool {
	mutates := false
	ast.Inspect(node, func(raw ast.Node) bool {
		if mutates {
			return false
		}
		switch typed := raw.(type) {
		case *ast.AssignStmt:
			for _, target := range typed.Lhs {
				switch candidate := target.(type) {
				case *ast.StarExpr, *ast.SelectorExpr, *ast.IndexExpr:
					mutates = true
					return false
				case *ast.Ident:
					if model.globalTypes[pkg+"."+candidate.Name].valid() {
						mutates = true
						return false
					}
				}
			}
		case *ast.IncDecStmt:
			if _, local := typed.X.(*ast.Ident); !local {
				mutates = true
				return false
			}
		case *ast.GoStmt:
			mutates = true
			return false
		case *ast.CallExpr:
			if s6IdentityMayMutate(s6CallIdentity{name: s6CallName(typed)}) {
				mutates = true
				return false
			}
			if identifier, ok := typed.Fun.(*ast.Ident); ok &&
				callableParams[identifier.Name] {
				mutates = true
				return false
			}
			if selector, ok := typed.Fun.(*ast.SelectorExpr); ok {
				receiver := model.resolveAlias(s6ExpressionType(
					pkg, imports, selector.X, locals, model,
				))
				if fields := model.fields[receiver.key()]; fields != nil &&
					fields[selector.Sel.Name].name == "func" {
					mutates = true
					return false
				}
			}
			identity := s6ResolveCallIdentity(
				pkg, imports, typed, locals, model,
			)
			if len(model.functionDecls[identity.functionKey()]) != 0 &&
				s6FunctionKeyMayMutate(
					identity.functionKey(), model, resolving,
				) {
				mutates = true
				return false
			}
		}
		return true
	})
	return mutates
}

func s6AssignmentRootIdentifier(expression ast.Expr) *ast.Ident {
	switch typed := expression.(type) {
	case *ast.Ident:
		return typed
	case *ast.ParenExpr:
		return s6AssignmentRootIdentifier(typed.X)
	case *ast.StarExpr:
		return s6AssignmentRootIdentifier(typed.X)
	case *ast.SelectorExpr:
		return s6AssignmentRootIdentifier(typed.X)
	case *ast.IndexExpr:
		return s6AssignmentRootIdentifier(typed.X)
	default:
		return nil
	}
}

func s6ResolvedLocalCall(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) (bool, bool) {
	if analyzer == nil || analyzer.model == nil ||
		s6DeferredConversionCall(call, analyzer) {
		return false, false
	}
	if identifier, ok := call.Fun.(*ast.Ident); ok {
		if s6IsPredeclaredBuiltinCall(call, identifier.Name, analyzer) {
			return false, false
		}
	}
	params := map[string]bool{}
	if analyzer.function != nil {
		params = s6FunctionCallableParameters(analyzer.function)
	}
	identities, unresolved := s6ResolveCallableIdentitiesFromContext(
		call.Fun,
		s6CallableContext{
			pkg: analyzer.pkg, imports: analyzer.imports, locals: analyzer.locals,
			bindings:                 bindings,
			params:                   params,
			functionKey:              analyzer.functionKey,
			goroutineContext:         analyzer.goroutineContext,
			guardedExpressionContext: true,
		},
		analyzer.model,
		map[string]bool{},
	)
	if unresolved || len(identities) == 0 {
		identity := s6ResolveCallIdentity(
			analyzer.pkg, analyzer.imports, call, analyzer.locals, analyzer.model,
		)
		if identity.known &&
			len(analyzer.model.functionDecls[identity.functionKey()]) == 1 {
			return true, false
		}
		if selector, ok := call.Fun.(*ast.SelectorExpr); ok {
			if _, unique := s6UniqueDeclaredMethodIdentity(
				analyzer.model, selector.Sel.Name,
			); unique {
				return true, false
			}
		}
		return false, true
	}
	for _, identity := range identities {
		if identity.literal != nil {
			continue
		}
		if len(analyzer.model.functionDecls[identity.functionKey()]) == 0 {
			return false, true
		}
	}
	return true, false
}

func s6GoroutineDynamicCallTouchesGuarded(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	analyzer *s6FlowAnalyzer,
) bool {
	expressions := append([]ast.Expr{call.Fun}, call.Args...)
	for _, expression := range expressions {
		backings, backingUnresolved := s6BackingIdentities(
			expression, bindings, analyzer, map[string]bool{},
		)
		if s6BackingSetsIntersect(backings, analyzer.goroutineBackings) ||
			(backingUnresolved && len(backings) != 0) {
			return true
		}
		targets, aliasLike, unresolved := s6GoAliasTargets(
			expression, bindings, analyzer, map[string]bool{},
		)
		if aliasLike && unresolved {
			return true
		}
		for _, target := range targets {
			if target.Obj != nil && analyzer.goroutineObjects[target.Obj] {
				return true
			}
		}
	}
	return false
}

func s6ResolveLocalFunctionLiterals(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	resolving map[string]bool,
) ([]*ast.FuncLit, bool) {
	switch typed := expression.(type) {
	case *ast.FuncLit:
		return []*ast.FuncLit{typed}, false
	case *ast.ParenExpr:
		return s6ResolveLocalFunctionLiterals(typed.X, bindings, resolving)
	case *ast.Ident:
		if resolving[typed.Name] {
			return nil, true
		}
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 {
			return nil, false
		}
		resolving[typed.Name] = true
		defer delete(resolving, typed.Name)
		var literals []*ast.FuncLit
		unresolved := false
		for _, candidate := range candidates {
			resolved, candidateUnresolved := s6ResolveLocalFunctionLiterals(
				candidate, bindings, resolving,
			)
			literals = append(literals, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return literals, unresolved
	case *ast.SelectorExpr:
		candidates := s6LocalFieldExpressions(typed, bindings)
		if len(candidates) == 0 {
			return nil, false
		}
		var literals []*ast.FuncLit
		unresolved := false
		for _, candidate := range candidates {
			resolved, candidateUnresolved := s6ResolveLocalFunctionLiterals(
				candidate, bindings, resolving,
			)
			literals = append(literals, resolved...)
			unresolved = unresolved || candidateUnresolved
		}
		return literals, unresolved
	default:
		return nil, false
	}
}

func s6LocalFieldExpressions(
	selector *ast.SelectorExpr,
	bindings *s6ReachingBindings,
) []ast.Expr {
	var bases []ast.Expr
	switch base := selector.X.(type) {
	case *ast.Ident:
		if direct := bindings.fieldCandidates(base, selector.Sel.Name); len(direct) != 0 {
			return direct
		}
		bases = bindings.candidates(base)
	case *ast.SelectorExpr:
		bases = s6LocalFieldExpressions(base, bindings)
	default:
		bases = []ast.Expr{base}
	}
	var values []ast.Expr
	for _, candidate := range bases {
		values = append(
			values,
			s6LocalCompositeFieldValues(
				candidate, selector.Sel.Name, bindings, map[string]bool{},
			)...,
		)
	}
	return values
}

func s6LocalCompositeFieldValues(
	expression ast.Expr,
	field string,
	bindings *s6ReachingBindings,
	resolving map[string]bool,
) []ast.Expr {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6LocalCompositeFieldValues(typed.X, field, bindings, resolving)
	case *ast.Ident:
		if resolving[typed.Name] {
			return nil
		}
		resolving[typed.Name] = true
		defer delete(resolving, typed.Name)
		var values []ast.Expr
		for _, candidate := range bindings.candidates(typed) {
			values = append(
				values,
				s6LocalCompositeFieldValues(
					candidate, field, bindings, resolving,
				)...,
			)
		}
		return values
	case *ast.CompositeLit:
		for _, raw := range typed.Elts {
			keyValue, ok := raw.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			name, ok := keyValue.Key.(*ast.Ident)
			if ok && name.Name == field {
				return []ast.Expr{keyValue.Value}
			}
		}
	}
	return nil
}

func s6FunctionParameters(function *ast.FuncDecl) map[string]bool {
	params := map[string]bool{}
	if function.Type.Params == nil {
		return params
	}
	for _, field := range function.Type.Params.List {
		for _, name := range field.Names {
			params[name.Name] = true
		}
	}
	return params
}

func s6HasNamedFunctionResults(function *ast.FuncDecl) bool {
	if function == nil || function.Type.Results == nil {
		return false
	}
	for _, result := range function.Type.Results.List {
		if len(result.Names) != 0 {
			return true
		}
	}
	return false
}

func s6FunctionCallableParameters(function *ast.FuncDecl) map[string]bool {
	params := map[string]bool{}
	if function == nil || function.Type.Params == nil {
		return params
	}
	for _, field := range function.Type.Params.List {
		if _, ok := field.Type.(*ast.FuncType); !ok {
			continue
		}
		for _, name := range field.Names {
			params[name.Name] = true
		}
	}
	return params
}

func s6AnalyzerCallableParameters(
	analyzer *s6FlowAnalyzer,
) map[string]bool {
	if analyzer == nil {
		return map[string]bool{}
	}
	return s6FunctionCallableParameters(analyzer.function)
}

func s6CallableParametersReferencedBy(
	expression ast.Expr,
	params map[string]bool,
	bindings *s6ReachingBindings,
	resolving map[string]bool,
) []string {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6CallableParametersReferencedBy(typed.X, params, bindings, resolving)
	case *ast.Ident:
		if params[typed.Name] {
			return []string{typed.Name}
		}
		if resolving[typed.Name] {
			return nil
		}
		resolving[typed.Name] = true
		defer delete(resolving, typed.Name)
		var result []string
		for _, candidate := range bindings.candidates(typed) {
			result = append(
				result,
				s6CallableParametersReferencedBy(
					candidate, params, bindings, resolving,
				)...,
			)
		}
		return s6UniqueStrings(result)
	default:
		return nil
	}
}

func s6InvokedCallableParameters(
	function *ast.FuncDecl,
	params map[string]bool,
) []string {
	found := map[string]bool{}
	visitedLiterals := map[token.Pos]bool{}
	var scan func(ast.Node)
	scan = func(root ast.Node) {
		ast.Inspect(root, func(node ast.Node) bool {
			if node == nil {
				return false
			}
			if literal, ok := node.(*ast.FuncLit); ok {
				if node != root {
					return false
				}
				if visitedLiterals[literal.Pos()] {
					return false
				}
				visitedLiterals[literal.Pos()] = true
			}
			call, ok := node.(*ast.CallExpr)
			if !ok {
				return true
			}
			bindings := s6FunctionBindingsBefore(function, call.Pos())
			for _, parameter := range s6CallableParametersReferencedBy(
				call.Fun, params, bindings, map[string]bool{},
			) {
				found[parameter] = true
			}
			literals, _ := s6ResolveLocalFunctionLiterals(
				call.Fun, bindings, map[string]bool{},
			)
			for _, literal := range literals {
				scan(literal)
			}
			if s6ApprovedSynchronousCallbackCall(call, 0, bindings) {
				for _, argument := range call.Args {
					callbacks, _ := s6ResolveLocalFunctionLiterals(
						argument, bindings, map[string]bool{},
					)
					for _, callback := range callbacks {
						scan(callback)
					}
				}
			}
			return true
		})
	}
	scan(function.Body)
	result := make([]string, 0, len(found))
	for parameter := range found {
		result = append(result, parameter)
	}
	sort.Strings(result)
	return result
}

func s6FunctionMutationCallableParameters(function *ast.FuncDecl) map[string]bool {
	params := map[string]bool{}
	if function.Type.Params == nil {
		return params
	}
	for _, field := range function.Type.Params.List {
		callable, ok := field.Type.(*ast.FuncType)
		if !ok || callable.Results == nil {
			continue
		}
		var results []string
		for _, result := range callable.Results.List {
			count := len(result.Names)
			if count == 0 {
				count = 1
			}
			for range count {
				results = append(results, s6CompositeTypeName(result.Type))
			}
		}
		mayMutate := len(results) == 1 && results[0] == "error"
		mayMutate = mayMutate || len(results) == 2 &&
			results[0] == "RootFile" && results[1] == "error"
		if !mayMutate {
			continue
		}
		for _, name := range field.Names {
			params[name.Name] = true
		}
	}
	return params
}

func s6ReturnsString(function *ast.FuncType) bool {
	if function.Results == nil {
		return false
	}
	for _, result := range function.Results.List {
		if ident, ok := result.Type.(*ast.Ident); ok && ident.Name == "string" {
			return true
		}
	}
	return false
}

func s6IsWriteRequestType(expression ast.Expr) bool {
	switch typed := expression.(type) {
	case *ast.Ident:
		return typed.Name == "WriteRequest"
	case *ast.SelectorExpr:
		return typed.Sel.Name == "WriteRequest"
	default:
		return false
	}
}

func validateS6ConstructorDataflow(function *ast.FuncDecl) error {
	var violation string
	ast.Inspect(function.Body, func(node ast.Node) bool {
		if violation != "" {
			return false
		}
		switch typed := node.(type) {
		case *ast.CallExpr:
			if s6ApprovedWriteTargetConstructor(typed) {
				return false
			}
		case *ast.SelectorExpr:
			if typed.Sel.Name == "StageRel" || s6ApprovedPlanTargetSelector(typed) {
				return false
			}
		case *ast.Ident:
			lower := strings.ToLower(typed.Name)
			for _, forbidden := range []string{"provider", "prompt", "response", "content", "body", "bytes", "output"} {
				if strings.Contains(lower, forbidden) {
					violation = "data-derived identifier " + typed.Name
					break
				}
			}
		}
		return true
	})
	if violation != "" {
		return errors.New(violation)
	}
	return nil
}

func validateS6WriteTargetExpression(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	params map[string]bool,
	model *s6SourceTypeModel,
	functionKey string,
	pkg string,
	imports map[string]string,
	locals map[string]s6TypeRef,
	resolving map[string]bool,
) error {
	if bindings != nil {
		if bindings.analysisErr != nil {
			return bindings.analysisErr
		}
		if !bindings.reachable {
			return errors.New("write target flow is unreachable")
		}
	}
	if selector, ok := expression.(*ast.SelectorExpr); ok &&
		functionKey == "internal/intentpub.durableWriteRoot" {
		base, baseOK := selector.X.(*ast.Ident)
		if baseOK && base.Name == "request" &&
			(selector.Sel.Name == "Rel" || selector.Sel.Name == "TempSuffix") {
			return nil
		}
	}
	if selector, ok := expression.(*ast.SelectorExpr); ok {
		if key, modeled, external := s6ImportedGlobalKey(
			selector, imports, model,
		); modeled {
			if resolving["imported-global:"+key] {
				return fmt.Errorf("cyclic imported global target %s", key)
			}
			values := bindings.globalByKey[key]
			if len(values) == 0 {
				values = s6GlobalInitialExpressions(model, key)
			}
			if len(values) == 0 {
				return fmt.Errorf("imported global target %s is unresolved", key)
			}
			resolving["imported-global:"+key] = true
			defer delete(resolving, "imported-global:"+key)
			for _, value := range values {
				if err := validateS6WriteTargetExpression(
					value, bindings, params, model, functionKey,
					pkg, imports, locals, resolving,
				); err != nil {
					return fmt.Errorf(
						"imported global target %s is unsafe: %w", key, err,
					)
				}
			}
			return nil
		} else if external {
			return fmt.Errorf("imported mutable global %s is outside analyzed packages", key)
		}
	}
	if selector, ok := expression.(*ast.SelectorExpr); ok {
		if handled, err := s6ValidateRangeElementSelector(
			selector, bindings, params, model, functionKey,
			pkg, imports, locals, resolving,
		); handled {
			return err
		}
	}
	if call, ok := expression.(*ast.CallExpr); ok {
		if s6MechanicallyApprovedWriteTargetConstructor(
			call, bindings, params, model, functionKey, pkg, imports, locals,
		) {
			return nil
		}
		return s6ValidateWriteTargetCall(
			call, bindings, params, model, functionKey, pkg, imports, locals, resolving,
		)
	}
	if literal, ok := expression.(*ast.BasicLit); ok && literal.Kind == token.STRING {
		value, _ := strconv.Unquote(literal.Value)
		if filepath.IsAbs(value) {
			return errors.New("absolute write target")
		}
	}
	var violation string
	ast.Inspect(expression, func(node ast.Node) bool {
		if violation != "" {
			return false
		}
		switch typed := node.(type) {
		case *ast.CallExpr:
			if s6MechanicallyApprovedWriteTargetConstructor(
				typed, bindings, params, model, functionKey, pkg, imports, locals,
			) {
				return false
			}
			if err := s6ValidateWriteTargetCall(
				typed, bindings, params, model, functionKey,
				pkg, imports, locals, resolving,
			); err != nil {
				violation = err.Error()
			}
			return false
		case *ast.IndexExpr:
			indices, indexUnresolved := s6SnapshotDeferredExpression(
				typed.Index, bindings,
				&s6FlowAnalyzer{
					model: model, pkg: pkg, imports: imports, locals: locals,
					functionKey: functionKey,
				},
				map[string]bool{},
			)
			values, valueUnresolved := s6SnapshotDeferredIndex(
				typed.X, indices, bindings,
				&s6FlowAnalyzer{
					model: model, pkg: pkg, imports: imports, locals: locals,
					functionKey: functionKey,
				},
				map[string]bool{},
			)
			if len(values) != 0 {
				for _, value := range values {
					if err := validateS6WriteTargetExpression(
						value, bindings, params, model, functionKey,
						pkg, imports, locals, resolving,
					); err != nil {
						violation = err.Error()
						break
					}
				}
				if violation == "" && (indexUnresolved || valueUnresolved) {
					violation = "providerUnresolvedCollectionElement"
				}
				return false
			}
			if err := validateS6WriteTargetExpression(
				typed.X, bindings, params, model, functionKey,
				pkg, imports, locals,
				s6WithCollectionElementResolution(
					resolving, typed.X, functionKey,
				),
			); err != nil {
				violation = err.Error()
			}
			return false
		case *ast.SelectorExpr:
			if handled, err := s6ValidateRangeElementSelector(
				typed, bindings, params, model, functionKey,
				pkg, imports, locals, resolving,
			); handled {
				if err != nil {
					violation = err.Error()
				}
				return false
			}
			if functionKey == "internal/intentpub.durableWriteRoot" {
				base, baseOK := typed.X.(*ast.Ident)
				if baseOK && base.Name == "request" &&
					(typed.Sel.Name == "Rel" || typed.Sel.Name == "TempSuffix") {
					return false
				}
			}
			if typed.Sel.Name == "StageRel" || s6ApprovedPlanTargetSelector(typed) {
				return false
			}
		case *ast.Ident:
			lower := strings.ToLower(typed.Name)
			for _, forbidden := range []string{"provider", "prompt", "response", "content", "body", "bytes", "output"} {
				if strings.Contains(lower, forbidden) {
					violation = "write target derives from " + typed.Name
					break
				}
			}
			if violation == "" && !resolving[typed.Name] {
				candidates := bindings.candidates(typed)
				if len(candidates) == 0 && !params[typed.Name] {
					globalKey := pkg + "." + typed.Name
					if _, ok := model.globalTypes[globalKey]; ok {
						candidates, _ = s6GlobalBindingCandidates(bindings, globalKey)
						if len(candidates) == 0 {
							candidates = s6GlobalInitialExpressions(model, globalKey)
						}
					}
				}
				if len(candidates) != 0 {
					resolving[typed.Name] = true
					for _, candidate := range candidates {
						if candidate == expression {
							continue
						}
						if err := validateS6WriteTargetExpression(
							candidate, bindings, params, model, functionKey,
							pkg, imports, locals, resolving,
						); err != nil {
							violation = typed.Name + " may derive from unsafe target data: " + err.Error()
							break
						}
					}
					delete(resolving, typed.Name)
				} else if params[typed.Name] {
					candidates := model.parameterValues[functionKey][typed.Name]
					if len(candidates) == 0 {
						violation = "write target depends on unresolved parameter " + typed.Name
						break
					}
					resolvingKey := functionKey + ":" + typed.Name
					if resolving[resolvingKey] {
						violation = "cyclic write target parameter " + resolvingKey
						break
					}
					resolving[resolvingKey] = true
					validated := 0
					position, collectionElement := s6CollectionElementPosition(
						resolving, typed.Name, functionKey,
					)
					for _, candidate := range candidates {
						if !s6CandidateFunctionReachable(model, candidate) {
							continue
						}
						if candidate.functionKey == functionKey &&
							s6ExpressionReferencesName(candidate.expression, typed.Name) {
							continue
						}
						validated++
						if collectionElement {
							elementResolving := make(
								map[string]bool, len(resolving)+1,
							)
							for key, value := range resolving {
								elementResolving[key] = value
							}
							elementResolving["collection-result-position:"+
								strconv.Itoa(position)] = true
							if err := s6ValidateWriteTargetCollectionExpression(
								candidate.expression,
								candidate.bindings,
								candidate.valueParams,
								model,
								candidate.functionKey,
								candidate.pkg,
								candidate.imports,
								candidate.locals,
								elementResolving,
							); err != nil {
								violation = typed.Name +
									" receives unsafe collection target data: " + err.Error()
								break
							}
							continue
						}
						if err := validateS6WriteTargetExpression(
							candidate.expression,
							candidate.bindings,
							candidate.valueParams,
							model,
							candidate.functionKey,
							candidate.pkg,
							candidate.imports,
							candidate.locals,
							resolving,
						); err != nil {
							violation = typed.Name + " receives unsafe target data: " + err.Error()
							break
						}
					}
					delete(resolving, resolvingKey)
					if violation == "" && validated == 0 {
						violation = "write target parameter has only recursive flow " + resolvingKey
					}
				}
			}
		}
		return true
	})
	if violation != "" {
		return errors.New(violation)
	}
	return nil
}

func s6MechanicallyApprovedWriteTargetConstructor(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	params map[string]bool,
	model *s6SourceTypeModel,
	functionKey string,
	pkg string,
	imports map[string]string,
	locals map[string]s6TypeRef,
) bool {
	if !s6ApprovedWriteTargetConstructor(call) {
		return false
	}
	identities, unresolved := s6ResolveCallableIdentitiesFromContext(
		call.Fun,
		s6CallableContext{
			pkg: pkg, imports: imports, locals: locals, bindings: bindings,
			params: params, functionKey: functionKey,
		},
		model,
		map[string]bool{},
	)
	if unresolved || len(identities) != 1 {
		return false
	}
	if identities[0].name == "CanonicalSlug" &&
		!s6CanonicalSlugConstructorContract(model, identities[0].functionKey()) {
		return false
	}
	switch identities[0].pkg {
	case "internal/cli", "internal/intent", "internal/intentpub", "internal/store":
		return len(model.functionResultLists[identities[0].functionKey()]) != 0
	default:
		return false
	}
}

func s6CanonicalSlugConstructorContract(
	model *s6SourceTypeModel,
	functionKey string,
) bool {
	declarations := model.functionDecls[functionKey]
	if len(declarations) != 1 {
		return false
	}
	function := declarations[0]
	params := s6FunctionParameterNames(function)
	if len(params) != 1 {
		return false
	}
	parameter := params[0]
	rejections := 0
	validatedReturn := false
	ast.Inspect(function.Body, func(node ast.Node) bool {
		statement, ok := node.(*ast.ReturnStmt)
		if !ok {
			return true
		}
		for _, result := range statement.Results {
			identifier, ok := result.(*ast.Ident)
			if ok && identifier.Name == parameter {
				validatedReturn = rejections > 0
			}
			if call, ok := result.(*ast.CallExpr); ok &&
				s6CallName(call) == "New" {
				rejections++
			}
		}
		return true
	})
	return rejections >= 2 && validatedReturn
}

func s6ValidateWriteTargetCall(
	call *ast.CallExpr,
	bindings *s6ReachingBindings,
	params map[string]bool,
	model *s6SourceTypeModel,
	functionKey string,
	pkg string,
	imports map[string]string,
	locals map[string]s6TypeRef,
	resolving map[string]bool,
) error {
	context := s6CallableContext{
		pkg: pkg, imports: imports, locals: locals, bindings: bindings,
		params: params, functionKey: functionKey,
	}
	identities, unresolved := s6ResolveCallableIdentitiesFromContext(
		call.Fun, context, model, map[string]bool{},
	)
	if unresolved || len(identities) != 1 {
		return errors.New("write target helper identity is unresolved")
	}
	identity := identities[0]
	if identity.receiver == "" && identity.name == "string" && len(call.Args) == 1 {
		return validateS6WriteTargetExpression(
			call.Args[0], bindings, params, model, functionKey,
			pkg, imports, locals, resolving,
		)
	}
	if identity.receiver == "" &&
		(identity.pkg == "path" || identity.pkg == "path/filepath") {
		switch identity.name {
		case "Base", "Clean", "Dir", "Join":
			for _, argument := range call.Args {
				if err := validateS6WriteTargetExpression(
					argument, bindings, params, model, functionKey,
					pkg, imports, locals, resolving,
				); err != nil {
					return fmt.Errorf("path helper %s receives unsafe data: %w", identity.name, err)
				}
			}
			return nil
		}
	}
	effects := s6IdentityGlobalEffects(identity, model, map[string]bool{})
	readsRuntimeGlobal := false
	for key := range effects.reads {
		if _, ok := bindings.globalByKey[key]; ok {
			readsRuntimeGlobal = true
			break
		}
	}
	if readsRuntimeGlobal {
		values, unresolved := s6SnapshotDeferredCallResult(
			call, bindings,
			&s6FlowAnalyzer{
				model: model, pkg: pkg, imports: imports, locals: locals,
				functionKey: functionKey, ordinaryEffects: true,
				reachableGlobals: effects.reads,
			},
			map[string]bool{},
		)
		if unresolved {
			return errors.New("write target helper runtime global result is unresolved")
		}
		for _, value := range values {
			if err := validateS6WriteTargetExpression(
				value, bindings, params, model, functionKey,
				pkg, imports, locals, resolving,
			); err != nil {
				return fmt.Errorf(
					"write target helper runtime global result is unsafe: %w", err,
				)
			}
		}
		return nil
	}
	return s6ValidateWriteTargetFunctionResult(
		identity.functionKey(), 0, model, resolving,
	)
}

func s6ValidateWriteTargetFunctionResult(
	functionKey string,
	position int,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) error {
	marker := "write-result:" + functionKey + ":" + strconv.Itoa(position)
	if resolving[marker] {
		return fmt.Errorf("cyclic write target helper %s", functionKey)
	}
	results := model.functionResultLists[functionKey]
	if position >= len(results) {
		return fmt.Errorf("write target helper %s result %d is undeclared", functionKey, position)
	}
	resultType := model.resolveAlias(results[position])
	if resultType.container {
		element := model.resolveAlias(resultType.element())
		if element.name == "string" ||
			model.resolveAlias(model.underlying[element.key()]).name == "string" {
			return s6ValidateWriteTargetCollectionFunctionResult(
				functionKey, position, model, resolving,
			)
		}
	}
	if resultType.name != "string" &&
		model.resolveAlias(model.underlying[resultType.key()]).name != "string" {
		return fmt.Errorf("write target helper %s does not return string", functionKey)
	}
	returned := model.returnExpressions[functionKey][position]
	if len(returned) == 0 {
		return fmt.Errorf("write target helper %s has no resolved return flow", functionKey)
	}
	resolving[marker] = true
	defer delete(resolving, marker)
	for _, candidate := range returned {
		if candidate.unresolved {
			return fmt.Errorf("write target helper %s has unresolved return flow", functionKey)
		}
		if candidate.tupleForward {
			call, ok := candidate.expression.(*ast.CallExpr)
			if !ok {
				return fmt.Errorf("write target helper %s has invalid tuple forwarding", functionKey)
			}
			identities, unresolved := s6ResolveCallableIdentitiesFromContext(
				call.Fun, s6BoundCallableContext(candidate), model, map[string]bool{},
			)
			if unresolved || len(identities) != 1 {
				return fmt.Errorf("write target helper %s forwards to unresolved helper", functionKey)
			}
			if err := s6ValidateWriteTargetFunctionResult(
				identities[0].functionKey(), candidate.tuplePosition, model, resolving,
			); err != nil {
				return err
			}
			continue
		}
		if err := validateS6WriteTargetExpression(
			candidate.expression,
			candidate.bindings,
			candidate.valueParams,
			model,
			candidate.functionKey,
			candidate.pkg,
			candidate.imports,
			candidate.locals,
			resolving,
		); err != nil {
			return fmt.Errorf("write target helper %s returns unsafe data: %w", functionKey, err)
		}
	}
	return nil
}

func s6ValidateWriteTargetCollectionFunctionResult(
	functionKey string,
	position int,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) error {
	marker := "write-collection-result:" + functionKey + ":" + strconv.Itoa(position)
	if resolving[marker] {
		return fmt.Errorf("cyclic write target collection helper %s", functionKey)
	}
	returned := model.returnExpressions[functionKey][position]
	if len(returned) == 0 {
		return fmt.Errorf(
			"write target collection helper %s has no resolved return flow",
			functionKey,
		)
	}
	resolving[marker] = true
	defer delete(resolving, marker)
	for _, candidate := range returned {
		if candidate.unresolved {
			return fmt.Errorf(
				"write target collection helper %s has unresolved return flow",
				functionKey,
			)
		}
		if err := s6ValidateWriteTargetCollectionExpression(
			candidate.expression,
			candidate.bindings,
			candidate.valueParams,
			model,
			candidate.functionKey,
			candidate.pkg,
			candidate.imports,
			candidate.locals,
			resolving,
		); err != nil {
			return fmt.Errorf(
				"write target collection helper %s returns unsafe data: %w",
				functionKey, err,
			)
		}
	}
	return nil
}

func s6ValidateWriteTargetCollectionExpression(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	params map[string]bool,
	model *s6SourceTypeModel,
	functionKey string,
	pkg string,
	imports map[string]string,
	locals map[string]s6TypeRef,
	resolving map[string]bool,
) error {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6ValidateWriteTargetCollectionExpression(
			typed.X, bindings, params, model, functionKey,
			pkg, imports, locals, resolving,
		)
	case *ast.CompositeLit:
		for _, raw := range typed.Elts {
			element := raw
			if item, ok := raw.(*ast.KeyValueExpr); ok {
				element = item.Value
			}
			if err := validateS6WriteTargetExpression(
				element, bindings, params, model, functionKey,
				pkg, imports, locals, resolving,
			); err != nil {
				return err
			}
		}
		return nil
	case *ast.Ident:
		if typed.Name == "nil" {
			return nil
		}
		marker := "write-collection-ident:" + functionKey + ":" + typed.Name
		if resolving[marker] {
			return nil
		}
		resolving[marker] = true
		defer delete(resolving, marker)
		candidates := bindings.candidates(typed)
		if len(candidates) == 0 && params[typed.Name] {
			for _, candidate := range model.parameterValues[functionKey][typed.Name] {
				if err := s6ValidateWriteTargetCollectionExpression(
					candidate.expression,
					candidate.bindings,
					candidate.valueParams,
					model,
					candidate.functionKey,
					candidate.pkg,
					candidate.imports,
					candidate.locals,
					resolving,
				); err != nil {
					return err
				}
			}
			if len(model.parameterValues[functionKey][typed.Name]) != 0 {
				return nil
			}
		}
		if len(candidates) == 0 {
			return fmt.Errorf("unresolved write target collection %s", typed.Name)
		}
		for _, candidate := range candidates {
			if err := s6ValidateWriteTargetCollectionExpression(
				candidate, bindings, params, model, functionKey,
				pkg, imports, locals, resolving,
			); err != nil {
				return err
			}
		}
		return nil
	case *ast.CallExpr:
		builtinAnalyzer := &s6FlowAnalyzer{
			model: model, pkg: pkg,
			imports: imports, locals: locals, functionKey: functionKey,
		}
		if s6IsPredeclaredBuiltinCall(typed, "make", builtinAnalyzer) {
			return nil
		}
		if s6IsPredeclaredBuiltinCall(typed, "append", builtinAnalyzer) &&
			len(typed.Args) != 0 {
			if err := s6ValidateWriteTargetCollectionExpression(
				typed.Args[0], bindings, params, model, functionKey,
				pkg, imports, locals, resolving,
			); err != nil {
				return err
			}
			for _, element := range typed.Args[1:] {
				if err := validateS6WriteTargetExpression(
					element, bindings, params, model, functionKey,
					pkg, imports, locals, resolving,
				); err != nil {
					return err
				}
			}
			return nil
		}
		context := s6CallableContext{
			pkg: pkg, imports: imports, locals: locals, bindings: bindings,
			params: params, functionKey: functionKey,
		}
		identities, unresolved := s6ResolveCallableIdentitiesFromContext(
			typed.Fun, context, model, map[string]bool{},
		)
		if unresolved || len(identities) != 1 {
			return errors.New("write target collection helper identity is unresolved")
		}
		position := 0
		for key := range resolving {
			const prefix = "collection-result-position:"
			if strings.HasPrefix(key, prefix) {
				if parsed, err := strconv.Atoi(strings.TrimPrefix(key, prefix)); err == nil {
					position = parsed
				}
			}
		}
		return s6ValidateWriteTargetCollectionFunctionResult(
			identities[0].functionKey(), position, model, resolving,
		)
	default:
		return fmt.Errorf(
			"unresolved write target collection expression %T", expression,
		)
	}
}

func s6ValidateRangeElementSelector(
	selector *ast.SelectorExpr,
	bindings *s6ReachingBindings,
	params map[string]bool,
	model *s6SourceTypeModel,
	functionKey string,
	pkg string,
	imports map[string]string,
	locals map[string]s6TypeRef,
	resolving map[string]bool,
) (bool, error) {
	base, ok := selector.X.(*ast.Ident)
	if !ok {
		return false, nil
	}
	var fields []s6BoundExpression
	handled := false
	for _, candidate := range bindings.candidates(base) {
		indexed, ok := candidate.(*ast.IndexExpr)
		if !ok {
			continue
		}
		handled = true
		resolved, err := s6CollectionFieldValues(
			indexed.X, selector.Sel.Name,
			s6BoundExpression{
				expression:  indexed.X,
				bindings:    bindings,
				params:      params,
				valueParams: params,
				functionKey: functionKey,
				pkg:         pkg,
				imports:     imports,
				locals:      locals,
			},
			model, map[string]bool{},
		)
		if err != nil {
			return true, err
		}
		fields = append(fields, resolved...)
	}
	if !handled {
		return false, nil
	}
	if len(fields) == 0 {
		return true, fmt.Errorf(
			"range element field %s is unresolved", selector.Sel.Name,
		)
	}
	for _, field := range fields {
		if field.unresolved || field.expression == nil {
			return true, fmt.Errorf(
				"range element field %s has unresolved flow", selector.Sel.Name,
			)
		}
		if err := validateS6WriteTargetExpression(
			field.expression,
			field.bindings,
			field.valueParams,
			model,
			field.functionKey,
			field.pkg,
			field.imports,
			field.locals,
			resolving,
		); err != nil {
			return true, fmt.Errorf(
				"range element field %s is unsafe: %w",
				selector.Sel.Name, err,
			)
		}
	}
	return true, nil
}

func s6CollectionFieldValues(
	expression ast.Expr,
	field string,
	context s6BoundExpression,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) ([]s6BoundExpression, error) {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6CollectionFieldValues(
			typed.X, field, context, model, resolving,
		)
	case *ast.CompositeLit:
		var result []s6BoundExpression
		switch typed.Type.(type) {
		case *ast.ArrayType:
			for _, element := range typed.Elts {
				if item, ok := element.(*ast.KeyValueExpr); ok {
					element = item.Value
				}
				resolved, err := s6CollectionFieldValues(
					element, field, context, model, resolving,
				)
				if err != nil {
					return nil, err
				}
				result = append(result, resolved...)
			}
			return result, nil
		case *ast.MapType:
			for _, element := range typed.Elts {
				item, ok := element.(*ast.KeyValueExpr)
				if !ok {
					return nil, errors.New("map collection element is unresolved")
				}
				resolved, err := s6CollectionFieldValues(
					item.Value, field, context, model, resolving,
				)
				if err != nil {
					return nil, err
				}
				result = append(result, resolved...)
			}
			return result, nil
		}
		for _, raw := range typed.Elts {
			item, ok := raw.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			name, ok := item.Key.(*ast.Ident)
			if ok && name.Name == field {
				value := context
				value.expression = item.Value
				return []s6BoundExpression{value}, nil
			}
		}
		return nil, fmt.Errorf("struct field %s is unresolved", field)
	case *ast.UnaryExpr:
		return s6CollectionFieldValues(
			typed.X, field, context, model, resolving,
		)
	case *ast.IndexExpr:
		return s6CollectionFieldValues(
			typed.X, field, context, model, resolving,
		)
	case *ast.SelectorExpr:
		collections, err := s6StructFieldValues(
			typed, context, model, resolving,
		)
		if err != nil {
			return nil, err
		}
		var result []s6BoundExpression
		for _, collection := range collections {
			resolved, resolveErr := s6CollectionFieldValues(
				collection.expression, field, collection, model, resolving,
			)
			if resolveErr != nil {
				return nil, resolveErr
			}
			result = append(result, resolved...)
		}
		return result, nil
	case *ast.Ident:
		if typed.Name == "nil" {
			return nil, nil
		}
		key := context.functionKey + ":" +
			s6IdentifierFlowKey(typed) + ":" + field
		if resolving[key] {
			return nil, fmt.Errorf("cyclic collection field flow %s", key)
		}
		resolving[key] = true
		defer delete(resolving, key)
		var result []s6BoundExpression
		if context.bindings != nil {
			tuples := context.bindings.tupleByName[typed.Name]
			if typed.Obj != nil && len(context.bindings.tupleByObj[typed.Obj]) != 0 {
				tuples = context.bindings.tupleByObj[typed.Obj]
			}
			if len(tuples) != 0 {
				for index, tuple := range tuples {
					positionKey := "collection-field-result-position:" +
						strconv.Itoa(tuple.position)
					resolving[positionKey] = true
					resolved, err := s6CollectionFieldValues(
						tuple.call, field, context, model, resolving,
					)
					delete(resolving, positionKey)
					if err != nil {
						return nil, fmt.Errorf(
							"collection tuple %s candidate %d: %w",
							typed.Name, index, err,
						)
					}
					result = append(result, resolved...)
				}
				return result, nil
			}
			for _, candidate := range context.bindings.candidates(typed) {
				resolved, err := s6CollectionFieldValues(
					candidate, field, context, model, resolving,
				)
				if err != nil {
					return nil, fmt.Errorf(
						"collection binding %s (%T %s): %w",
						typed.Name, candidate, s6ExpressionCallName(candidate), err,
					)
				}
				result = append(result, resolved...)
			}
		}
		if len(result) != 0 {
			return result, nil
		}
		for _, candidate := range s6LocalBoundValues(
			model, context.functionKey, typed.Name,
		) {
			if candidate.tupleForward {
				call, ok := candidate.expression.(*ast.CallExpr)
				if !ok {
					return nil, fmt.Errorf(
						"local tuple value %s is invalid", typed.Name,
					)
				}
				identities, unresolved := s6ResolveCallableIdentitiesFromContext(
					call.Fun, s6BoundCallableContext(candidate),
					model, map[string]bool{},
				)
				if unresolved || len(identities) != 1 {
					return nil, fmt.Errorf(
						"local tuple value %s helper is unresolved", typed.Name,
					)
				}
				for _, returned := range model.returnExpressions[identities[0].functionKey()][candidate.tuplePosition] {
					resolved, err := s6StructFieldValuesFromExpression(
						returned.expression, field, returned, model, resolving,
					)
					if err != nil {
						return nil, err
					}
					result = append(result, resolved...)
				}
				continue
			}
			resolved, err := s6StructFieldValuesFromExpression(
				candidate.expression, field, candidate, model, resolving,
			)
			if err == nil {
				result = append(result, resolved...)
			}
		}
		if len(result) != 0 {
			return result, nil
		}
		if context.valueParams[typed.Name] || context.params[typed.Name] ||
			s6FunctionReceiverNamed(model, context.functionKey, typed.Name) {
			values := model.parameterValues[context.functionKey][typed.Name]
			if len(values) == 0 {
				return nil, fmt.Errorf(
					"collection parameter %s is unresolved", typed.Name,
				)
			}
			for _, candidate := range values {
				if !s6CandidateFunctionReachable(model, candidate) {
					continue
				}
				resolved, err := s6CollectionFieldValues(
					candidate.expression, field, candidate, model, resolving,
				)
				if err != nil {
					return nil, fmt.Errorf(
						"collection parameter %s candidate from %s (%T %s): %w",
						typed.Name, candidate.functionKey, candidate.expression,
						s6ExpressionCallName(candidate.expression), err,
					)
				}
				result = append(result, resolved...)
			}
			return result, nil
		}
		return nil, fmt.Errorf("collection value %s is unresolved", typed.Name)
	case *ast.CallExpr:
		builtinAnalyzer := &s6FlowAnalyzer{
			model: model, pkg: context.pkg, imports: context.imports,
			locals: context.locals, functionKey: context.functionKey,
		}
		if s6IsPredeclaredBuiltinCall(typed, "make", builtinAnalyzer) {
			return nil, nil
		}
		if s6IsPredeclaredBuiltinCall(typed, "append", builtinAnalyzer) &&
			len(typed.Args) != 0 {
			var result []s6BoundExpression
			base, err := s6CollectionFieldValues(
				typed.Args[0], field, context, model, resolving,
			)
			if err == nil {
				result = append(result, base...)
			}
			for _, element := range typed.Args[1:] {
				resolved, elementErr := s6CollectionFieldValues(
					element, field, context, model, resolving,
				)
				if elementErr != nil {
					return nil, elementErr
				}
				result = append(result, resolved...)
			}
			return result, nil
		}
		identities, unresolved := s6ResolveCallableIdentitiesFromContext(
			typed.Fun, s6BoundCallableContext(context), model, map[string]bool{},
		)
		if unresolved || len(identities) != 1 {
			return nil, errors.New("collection helper identity is unresolved")
		}
		position := 0
		for key := range resolving {
			const prefix = "collection-field-result-position:"
			if strings.HasPrefix(key, prefix) {
				parsed, err := strconv.Atoi(strings.TrimPrefix(key, prefix))
				if err != nil {
					return nil, errors.New("collection field tuple position is invalid")
				}
				position = parsed
			}
		}
		returned := model.returnExpressions[identities[0].functionKey()][position]
		if len(returned) == 0 {
			return nil, fmt.Errorf(
				"collection helper %s result %d is unresolved",
				identities[0].functionKey(), position,
			)
		}
		var result []s6BoundExpression
		for _, candidate := range returned {
			if argument, ok := s6PreservedStructFieldArgument(
				identities[0].functionKey(), typed, candidate, field, model,
			); ok {
				resolved, err := s6StructFieldValuesFromExpression(
					argument, field, context, model, resolving,
				)
				if err != nil {
					return nil, err
				}
				result = append(result, resolved...)
				continue
			}
			resolved, err := s6CollectionFieldValues(
				candidate.expression, field, candidate, model, resolving,
			)
			if err != nil {
				return nil, err
			}
			result = append(result, resolved...)
		}
		return result, nil
	default:
		return nil, fmt.Errorf(
			"collection field %s source %T is unresolved", field, expression,
		)
	}
}

func s6ExpressionCallName(expression ast.Expr) string {
	call, _ := expression.(*ast.CallExpr)
	if call == nil {
		return ""
	}
	return s6CallName(call)
}

func s6StructFieldValues(
	selector *ast.SelectorExpr,
	context s6BoundExpression,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) ([]s6BoundExpression, error) {
	return s6StructFieldValuesFromExpression(
		selector.X, selector.Sel.Name, context, model, resolving,
	)
}

func s6StructFieldValuesFromExpression(
	expression ast.Expr,
	field string,
	context s6BoundExpression,
	model *s6SourceTypeModel,
	resolving map[string]bool,
) ([]s6BoundExpression, error) {
	switch typed := expression.(type) {
	case *ast.ParenExpr:
		return s6StructFieldValuesFromExpression(
			typed.X, field, context, model, resolving,
		)
	case *ast.UnaryExpr:
		return s6StructFieldValuesFromExpression(
			typed.X, field, context, model, resolving,
		)
	case *ast.CompositeLit:
		for _, raw := range typed.Elts {
			item, ok := raw.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			name, ok := item.Key.(*ast.Ident)
			if ok && name.Name == field {
				value := context
				value.expression = item.Value
				return []s6BoundExpression{value}, nil
			}
		}
		return nil, fmt.Errorf("struct field %s is unresolved", field)
	case *ast.Ident:
		key := "struct-field:" + context.functionKey + ":" +
			s6IdentifierFlowKey(typed) + ":" + field
		if resolving[key] {
			return nil, fmt.Errorf("cyclic struct field flow %s", key)
		}
		resolving[key] = true
		defer delete(resolving, key)
		var result []s6BoundExpression
		if context.bindings != nil {
			for _, candidate := range context.bindings.fieldCandidates(typed, field) {
				value := context
				value.expression = candidate
				result = append(result, value)
			}
			if len(result) != 0 {
				return result, nil
			}
			for _, candidate := range context.bindings.candidates(typed) {
				resolved, err := s6StructFieldValuesFromExpression(
					candidate, field, context, model, resolving,
				)
				if err == nil {
					result = append(result, resolved...)
				}
			}
		}
		if len(result) != 0 {
			return result, nil
		}
		if context.valueParams[typed.Name] || context.params[typed.Name] {
			values := model.parameterValues[context.functionKey][typed.Name]
			if len(values) == 0 {
				return nil, fmt.Errorf(
					"struct parameter %s is unresolved", typed.Name,
				)
			}
			for _, candidate := range values {
				if !s6CandidateFunctionReachable(model, candidate) {
					continue
				}
				resolved, err := s6StructFieldValuesFromExpression(
					candidate.expression, field, candidate, model, resolving,
				)
				if err != nil {
					return nil, err
				}
				result = append(result, resolved...)
			}
			return result, nil
		}
		return nil, fmt.Errorf(
			"struct value %s is unresolved (function=%s bindings=%v)",
			typed.Name, context.functionKey, context.bindings != nil,
		)
	case *ast.CallExpr:
		if values, ok := s6ApprovedStructFieldConstructorValues(
			typed, field, context, model,
		); ok {
			return values, nil
		}
		identities, unresolved := s6ResolveCallableIdentitiesFromContext(
			typed.Fun, s6BoundCallableContext(context), model, map[string]bool{},
		)
		if unresolved || len(identities) != 1 {
			return nil, errors.New("struct helper identity is unresolved")
		}
		returned := model.returnExpressions[identities[0].functionKey()][0]
		if len(returned) == 0 {
			return nil, fmt.Errorf(
				"struct helper %s return is unresolved",
				identities[0].functionKey(),
			)
		}
		var result []s6BoundExpression
		for _, candidate := range returned {
			if argument, ok := s6PreservedStructFieldArgument(
				identities[0].functionKey(), typed, candidate, field, model,
			); ok {
				resolved, err := s6StructFieldValuesFromExpression(
					argument, field, context, model, resolving,
				)
				if err != nil {
					return nil, err
				}
				result = append(result, resolved...)
				continue
			}
			resolved, err := s6StructFieldValuesFromExpression(
				candidate.expression, field, candidate, model, resolving,
			)
			if err != nil {
				return nil, err
			}
			result = append(result, resolved...)
		}
		return result, nil
	case *ast.SelectorExpr:
		intermediate, err := s6StructFieldValues(
			typed, context, model, resolving,
		)
		if err != nil {
			return nil, err
		}
		var result []s6BoundExpression
		for _, candidate := range intermediate {
			resolved, resolveErr := s6StructFieldValuesFromExpression(
				candidate.expression, field, candidate, model, resolving,
			)
			if resolveErr != nil {
				return nil, resolveErr
			}
			result = append(result, resolved...)
		}
		return result, nil
	default:
		return nil, fmt.Errorf(
			"struct field %s source %T is unresolved", field, expression,
		)
	}
}

func s6IdentifierFlowKey(identifier *ast.Ident) string {
	if identifier.Obj != nil {
		return fmt.Sprintf("%s@%p", identifier.Name, identifier.Obj)
	}
	return identifier.Name
}

func s6PreservedStructFieldArgument(
	functionKey string,
	call *ast.CallExpr,
	returned s6BoundExpression,
	field string,
	model *s6SourceTypeModel,
) (ast.Expr, bool) {
	identifier, ok := returned.expression.(*ast.Ident)
	if !ok || returned.functionKey != functionKey {
		return nil, false
	}
	params := model.functionParams[functionKey]
	index := -1
	for candidateIndex, name := range params {
		if name == identifier.Name {
			index = candidateIndex
			break
		}
	}
	declarations := model.functionDecls[functionKey]
	if index < 0 || index >= len(call.Args) || len(declarations) != 1 {
		return nil, false
	}
	preserved := true
	ast.Inspect(declarations[0].Body, func(node ast.Node) bool {
		if !preserved || node == nil {
			return false
		}
		switch typed := node.(type) {
		case *ast.FuncLit:
			return false
		case *ast.AssignStmt:
			for _, lhs := range typed.Lhs {
				switch target := lhs.(type) {
				case *ast.Ident:
					if target.Name == identifier.Name {
						preserved = false
					}
				case *ast.SelectorExpr:
					base, baseOK := target.X.(*ast.Ident)
					if baseOK && base.Name == identifier.Name &&
						target.Sel.Name == field {
						preserved = false
					}
				}
			}
		case *ast.IncDecStmt:
			selector, selectorOK := typed.X.(*ast.SelectorExpr)
			if !selectorOK {
				return true
			}
			base, baseOK := selector.X.(*ast.Ident)
			if baseOK &&
				base.Name == identifier.Name && selector.Sel.Name == field {
				preserved = false
			}
		case *ast.UnaryExpr:
			target, targetOK := typed.X.(*ast.Ident)
			if typed.Op == token.AND && targetOK &&
				target.Name == identifier.Name {
				preserved = false
			}
		case *ast.CallExpr:
			for _, argument := range typed.Args {
				target, targetOK := argument.(*ast.Ident)
				if targetOK && target.Name == identifier.Name {
					preserved = false
				}
			}
		}
		return preserved
	})
	if !preserved {
		return nil, false
	}
	return call.Args[index], true
}

func s6ApprovedStructFieldConstructorValues(
	call *ast.CallExpr,
	field string,
	context s6BoundExpression,
	model *s6SourceTypeModel,
) ([]s6BoundExpression, bool) {
	identity := s6ResolveCallIdentity(
		context.pkg, context.imports, call, context.locals, model,
	)
	if identity.functionKey() != "internal/intentpub.NewPlan" ||
		field != "entries" ||
		len(call.Args) != 4 ||
		!s6NewPlanEntriesConstructorContract(model) {
		return nil, false
	}
	value := context
	value.expression = call.Args[3]
	return []s6BoundExpression{value}, true
}

func s6NewPlanEntriesConstructorContract(model *s6SourceTypeModel) bool {
	newPlan := model.functionDecls["internal/intentpub.NewPlan"]
	add := model.functionDecls["internal/intentpub.PlanBuilder.Add"]
	freeze := model.functionDecls["internal/intentpub.PlanBuilder.Freeze"]
	if len(newPlan) != 1 || len(add) != 1 || len(freeze) != 1 ||
		newPlan[0].Body == nil || add[0].Body == nil || freeze[0].Body == nil {
		return false
	}
	params := model.functionParams["internal/intentpub.NewPlan"]
	if len(params) != 4 {
		return false
	}
	builderName := ""
	ast.Inspect(newPlan[0].Body, func(node ast.Node) bool {
		assign, ok := node.(*ast.AssignStmt)
		if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		lhs, lhsOK := assign.Lhs[0].(*ast.Ident)
		call, callOK := assign.Rhs[0].(*ast.CallExpr)
		if lhsOK && callOK && s6CallName(call) == "NewPlanBuilder" {
			builderName = lhs.Name
		}
		return true
	})
	if builderName == "" {
		return false
	}
	addsRangeEntry := false
	returnsFreeze := false
	ast.Inspect(newPlan[0].Body, func(node ast.Node) bool {
		switch typed := node.(type) {
		case *ast.RangeStmt:
			source, sourceOK := typed.X.(*ast.Ident)
			value, valueOK := typed.Value.(*ast.Ident)
			if !sourceOK || source.Name != params[3] || !valueOK {
				return true
			}
			ast.Inspect(typed.Body, func(node ast.Node) bool {
				call, ok := node.(*ast.CallExpr)
				if !ok || len(call.Args) != 1 {
					return true
				}
				selector, ok := call.Fun.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				receiver, receiverOK := selector.X.(*ast.Ident)
				argument, argumentOK := call.Args[0].(*ast.Ident)
				if receiverOK && argumentOK &&
					receiver.Name == builderName &&
					selector.Sel.Name == "Add" &&
					argument.Name == value.Name {
					addsRangeEntry = true
				}
				return true
			})
		case *ast.ReturnStmt:
			for _, result := range typed.Results {
				call, ok := result.(*ast.CallExpr)
				if !ok {
					continue
				}
				selector, ok := call.Fun.(*ast.SelectorExpr)
				if !ok {
					continue
				}
				receiver, receiverOK := selector.X.(*ast.Ident)
				if receiverOK && receiver.Name == builderName &&
					selector.Sel.Name == "Freeze" {
					returnsFreeze = true
				}
			}
		}
		return true
	})
	return addsRangeEntry &&
		returnsFreeze &&
		s6PlanBuilderAddContract(add[0], model.functionParams["internal/intentpub.PlanBuilder.Add"]) &&
		s6PlanBuilderFreezeContract(freeze[0])
}

func s6PlanBuilderAddContract(function *ast.FuncDecl, params []string) bool {
	receiverName := s6SingleReceiverName(function)
	if receiverName == "" || len(params) != 1 {
		return false
	}
	valid := false
	ast.Inspect(function.Body, func(node ast.Node) bool {
		assign, ok := node.(*ast.AssignStmt)
		if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		lhs, lhsOK := assign.Lhs[0].(*ast.SelectorExpr)
		appendCall, callOK := assign.Rhs[0].(*ast.CallExpr)
		if !lhsOK || !callOK {
			return true
		}
		lhsReceiver, lhsReceiverOK := lhs.X.(*ast.Ident)
		appendIdent, appendOK := appendCall.Fun.(*ast.Ident)
		if !lhsReceiverOK || !appendOK ||
			lhsReceiver.Name != receiverName || lhs.Sel.Name != "entries" ||
			appendIdent.Name != "append" || len(appendCall.Args) != 2 {
			return true
		}
		previous, previousOK := appendCall.Args[0].(*ast.SelectorExpr)
		previousReceiver, previousReceiverOK := previous.X.(*ast.Ident)
		entry, entryOK := appendCall.Args[1].(*ast.Ident)
		if previousOK && previousReceiverOK && entryOK &&
			previousReceiver.Name == receiverName &&
			previous.Sel.Name == "entries" &&
			entry.Name == params[0] {
			valid = true
		}
		return true
	})
	return valid
}

func s6PlanBuilderFreezeContract(function *ast.FuncDecl) bool {
	receiverName := s6SingleReceiverName(function)
	if receiverName == "" {
		return false
	}
	clonedEntries := map[string]bool{}
	ast.Inspect(function.Body, func(node ast.Node) bool {
		assign, ok := node.(*ast.AssignStmt)
		if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		name, nameOK := assign.Lhs[0].(*ast.Ident)
		call, callOK := assign.Rhs[0].(*ast.CallExpr)
		if !nameOK || !callOK || s6CallName(call) != "cloneEntries" ||
			len(call.Args) != 1 {
			return true
		}
		selector, selectorOK := call.Args[0].(*ast.SelectorExpr)
		if !selectorOK {
			return true
		}
		receiver, receiverOK := selector.X.(*ast.Ident)
		if receiverOK && receiver.Name == receiverName &&
			selector.Sel.Name == "entries" {
			clonedEntries[name.Name] = true
		}
		return true
	})
	valid := false
	ast.Inspect(function.Body, func(node ast.Node) bool {
		literal, ok := node.(*ast.CompositeLit)
		if !ok {
			return true
		}
		for _, element := range literal.Elts {
			keyValue, ok := element.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			key, keyOK := keyValue.Key.(*ast.Ident)
			value, valueOK := keyValue.Value.(*ast.Ident)
			if keyOK && valueOK &&
				key.Name == "entries" && clonedEntries[value.Name] {
				valid = true
			}
		}
		return true
	})
	return valid
}

func s6SingleReceiverName(function *ast.FuncDecl) string {
	if function.Recv == nil || len(function.Recv.List) != 1 ||
		len(function.Recv.List[0].Names) != 1 {
		return ""
	}
	return function.Recv.List[0].Names[0].Name
}

func s6LocalBoundValues(
	model *s6SourceTypeModel,
	functionKey string,
	name string,
) []s6BoundExpression {
	declarations := model.functionDecls[functionKey]
	if len(declarations) != 1 {
		return nil
	}
	function := declarations[0]
	pkg := model.functionPackages[function]
	imports := model.functionImports[function]
	locals := s6FunctionLocalTypes(
		pkg, model.functionFiles[function], function, model,
	)
	var result []s6BoundExpression
	ast.Inspect(function.Body, func(node ast.Node) bool {
		if literal, ok := node.(*ast.FuncLit); ok && literal != nil {
			return false
		}
		switch typed := node.(type) {
		case *ast.AssignStmt:
			for index, lhs := range typed.Lhs {
				identifier, ok := lhs.(*ast.Ident)
				if !ok || identifier.Name != name {
					continue
				}
				bound := s6BoundExpression{
					imports:     imports,
					pkg:         pkg,
					functionKey: functionKey,
					bindings:    s6FunctionBindingsBefore(function, typed.Pos()),
					params:      s6FunctionCallableParameters(function),
					valueParams: s6FunctionParameters(function),
					locals:      locals,
				}
				switch {
				case len(typed.Rhs) == len(typed.Lhs):
					bound.expression = typed.Rhs[index]
				case len(typed.Rhs) == 1:
					bound.expression = typed.Rhs[0]
					bound.tupleForward = len(typed.Lhs) > 1
					bound.tuplePosition = index
				default:
					continue
				}
				result = append(result, bound)
			}
		case *ast.ValueSpec:
			for index, identifier := range typed.Names {
				if identifier.Name == name && index < len(typed.Values) {
					result = append(result, s6BoundExpression{
						expression:  typed.Values[index],
						imports:     imports,
						pkg:         pkg,
						functionKey: functionKey,
						bindings: s6FunctionBindingsBefore(
							function, typed.Pos(),
						),
						params:      s6FunctionCallableParameters(function),
						valueParams: s6FunctionParameters(function),
						locals:      locals,
					})
				}
			}
		}
		return true
	})
	return result
}

func s6FunctionReceiverNamed(
	model *s6SourceTypeModel,
	functionKey string,
	name string,
) bool {
	declarations := model.functionDecls[functionKey]
	if len(declarations) != 1 || declarations[0].Recv == nil {
		return false
	}
	for _, field := range declarations[0].Recv.List {
		for _, receiver := range field.Names {
			if receiver.Name == name {
				return true
			}
		}
	}
	return false
}

func s6CandidateFunctionReachable(
	model *s6SourceTypeModel,
	candidate s6BoundExpression,
) bool {
	return len(model.reachableFunctions) == 0 ||
		candidate.functionKey == "" ||
		model.reachableFunctions[candidate.functionKey]
}

func s6ExpressionReferencesName(expression ast.Expr, name string) bool {
	found := false
	ast.Inspect(expression, func(node ast.Node) bool {
		if identifier, ok := node.(*ast.Ident); ok && identifier.Name == name {
			found = true
			return false
		}
		return !found
	})
	return found
}

func s6WithCollectionElementResolution(
	resolving map[string]bool,
	expression ast.Expr,
	functionKey string,
) map[string]bool {
	clone := make(map[string]bool, len(resolving)+1)
	for key, value := range resolving {
		clone[key] = value
	}
	if identifier, ok := expression.(*ast.Ident); ok {
		clone["collection-element:"+functionKey+":"+identifier.Name+":0"] = true
	}
	return clone
}

func s6CollectionElementPosition(
	resolving map[string]bool,
	name string,
	functionKey string,
) (int, bool) {
	prefix := "collection-element:" + functionKey + ":" + name + ":"
	for key := range resolving {
		if !strings.HasPrefix(key, prefix) {
			continue
		}
		position, err := strconv.Atoi(strings.TrimPrefix(key, prefix))
		return position, err == nil
	}
	return 0, false
}

func s6CollectionCallFlow(
	expression ast.Expr,
	bindings *s6ReachingBindings,
	name string,
	resolving map[string]bool,
) (*ast.CallExpr, int, bool) {
	switch typed := expression.(type) {
	case *ast.CallExpr:
		return typed, 0, true
	case *ast.ParenExpr:
		return s6CollectionCallFlow(typed.X, bindings, name, resolving)
	case *ast.Ident:
		key := typed.Name
		if resolving[key] {
			return nil, 0, false
		}
		resolving[key] = true
		defer delete(resolving, key)
		assignments := bindings.tupleByName[typed.Name]
		if typed.Obj != nil && len(bindings.tupleByObj[typed.Obj]) != 0 {
			assignments = bindings.tupleByObj[typed.Obj]
		}
		for _, assignment := range assignments {
			return assignment.call, assignment.position, true
		}
		for _, candidate := range bindings.candidates(typed) {
			if call, position, ok := s6CollectionCallFlow(
				candidate, bindings, name, resolving,
			); ok {
				return call, position, true
			}
		}
	}
	return nil, 0, false
}

type s6TupleCallPosition struct {
	call     *ast.CallExpr
	position int
}

func s6ApprovedWriteTargetConstructor(call *ast.CallExpr) bool {
	switch s6CallName(call) {
	case "CanonicalPath", "ArchiveBlobPath", "IntentArchiveRootRel",
		"IntentArchiveIndexRel", "IntentArchiveBlobsRel", "IntentArchiveBlobRel",
		"IntentArchiveArtifactPath", "JournalRel", "JournalMarkerRel", "StageRel",
		"canonicalTempRel", "featureRel", "laneRel", "canonicalRel",
		"prepareFeatureRel", "prepareArtifactFeaturePath", "prepareFailurePreimageRel",
		"prepareCanonicalRel", "CanonicalSlug", "RandomHex12", "randomHex12", "prepareRandomHex12",
		"NewRunNonce":
		return true
	default:
		return false
	}
}

func s6ApprovedPlanTargetSelector(selector *ast.SelectorExpr) bool {
	base, ok := selector.X.(*ast.Ident)
	if !ok || base.Name != "entry" {
		return false
	}
	switch selector.Sel.Name {
	case "Rel", "PreimageRawRel", "StagedRel":
		return true
	default:
		return false
	}
}
